              {/* v160.3.0-adjust-13 — new Capture bucket. */}
              <Route path="risk-assessments" element={<RiskAssessments />} />
              {/* v58.13.12 — Submissions bucket. CS Incidents migrated
                  out of the "Risk Assessments" tab into its own tiled
