export default App;

import React, { useState } from 'react';
import { Trash2, Loader2 } from 'lucide-react';
import { toast } from 'sonner';
import {
  AlertDialog, AlertDialogTrigger, AlertDialogContent, AlertDialogHeader,
  AlertDialogTitle, AlertDialogDescription, AlertDialogFooter,
  AlertDialogCancel, AlertDialogAction,
} from './ui/alert-dialog';
import { Can } from '../lib/permissions';
import api, { apiError } from '../lib/api';

/**
 * Soft-delete button + confirm dialog used on every capture list page.
 *
 * v160.2.9-delete — Capture sub-tabs (Pre-Starts, Site Diary, Hazards,
 * Incidents, Inspections) union `form_submissions` rows into their list
 * response (see `crud.py::build_router` mirror_categories, shipped in
 * v160.2.5a). Those mirrored rows carry `source: "form_submission"` and
 * their `id` field is the source submission id — which does NOT exist in
 * the legacy per-entity collection. Calling `DELETE /api/pre-starts/{id}`
 * on a mirrored row therefore 404'd silently, which is exactly the bug
 * reported ("clicking the delete button does nothing / shows error").
 *
 * Fix: when `source === "form_submission"` we route the DELETE to
 * `/api/forms/submissions/{id}` which soft-deletes the correct row and
 * makes it disappear from every mirroring Capture tab.
 *
 * Props:
 *   resourceKind  e.g. "swms", "pre_starts", "site_diary",
 *                       "hazards", "incidents", "inspections"
 *   apiPath       URL segment under /api (e.g. "swms", "pre-starts") —
 *                 used ONLY for the legacy path.
 *   recordId      UUID of the record (or submission id when mirrored).
 *   label         human-friendly label shown in the dialog title (e.g. "SWMS")
 *   recordTitle   optional title to mention in the dialog body
 *   source        v160.2.9-delete — "form_submission" for mirrored rows,
 *                 undefined/null for legacy rows.
 *   onDeleted     callback invoked on successful delete (page refreshes its list)
 */
export default function DeleteRecordButton({
  resourceKind, apiPath, recordId, label, recordTitle, source, onDeleted,
  // eslint-disable-next-line no-unused-vars
  iconOnly,
}) {
  const [open, setOpen] = useState(false);
  const [busy, setBusy] = useState(false);

  const isMirrored = source === 'form_submission';

  const doDelete = async () => {
    setBusy(true);
    try {
      if (isMirrored) {
        // v160.2.9-delete — mirrored submissions live in `form_submissions`.
        await api.delete(`/forms/submissions/${recordId}`);
      } else {
        await api.delete(`/${apiPath}/${recordId}`);
      }
      toast.success('Record deleted');
      setOpen(false);
      onDeleted?.(recordId);
    } catch (e) {
      const status = e?.response?.status;
      if (status === 403) toast.error("You don't have permission to delete this record");
      else if (status === 404) toast.error('This record has already been deleted or moved.');
      else toast.error(apiError(e) || 'Could not delete record');
    } finally { setBusy(false); }
  };

  return (
    <Can resource={resourceKind} action="edit">
      <AlertDialog open={open} onOpenChange={setOpen}>
        <AlertDialogTrigger asChild>
          <button
            type="button"
            onClick={(e) => e.stopPropagation()}
            title="Delete"
            aria-label={`Delete ${label}`}
            data-testid={`delete-${resourceKind}-${recordId}`}
            className="inline-flex items-center justify-center w-6 h-6 rounded border border-rose-200 bg-white text-rose-500 hover:bg-rose-500 hover:text-white hover:border-rose-500 transition-colors"
          >
            <Trash2 size={13} />
          </button>
        </AlertDialogTrigger>
        <AlertDialogContent onClick={(e) => e.stopPropagation()} data-testid={`delete-dialog-${resourceKind}-${recordId}`}>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete {label}?</AlertDialogTitle>
            <AlertDialogDescription>
              {recordTitle && <span className="block font-medium text-slate-900 mb-2">{recordTitle}</span>}
              This will soft-delete the record. Records remain in the database for audit
              but are hidden from all lists and reports. This action can be reversed by an
              administrator.
              {isMirrored && (
                <span className="block mt-2 text-xs text-slate-500">
                  Submitted from the mobile app — this deletes the original submission.
                </span>
              )}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={busy} data-testid={`delete-cancel-${recordId}`}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={doDelete}
              disabled={busy}
              data-testid={`delete-confirm-${recordId}`}
              className="bg-rose-600 hover:bg-rose-700 focus:ring-rose-600"
            >
              {busy ? <Loader2 size={14} className="animate-spin mr-1.5" /> : <Trash2 size={14} className="mr-1.5" />}
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </Can>
  );
}

import React, { useEffect, useState } from 'react';
import { Mail, X as XIcon, Loader2, Send, Paperclip, ChevronDown, ChevronRight, AlertTriangle, Check } from 'lucide-react';
import { toast } from 'sonner';
import { Link } from 'react-router-dom';
import api, { apiError } from '../lib/api';
// v160.3.7k — Inoculation sweep: lock body scroll while this modal is open.
import useLockBodyScroll from '../lib/useLockBodyScroll';

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function PillInput({ values, onChange, placeholder, testid }) {
  const [draft, setDraft] = useState('');
  const commit = () => {
    const parts = draft.split(/[,\s;]+/).map((s) => s.trim()).filter(Boolean);
    const valid = parts.filter((e) => EMAIL_RE.test(e));
    const invalid = parts.filter((e) => !EMAIL_RE.test(e));
    if (invalid.length) toast.error(`Invalid email: ${invalid.join(', ')}`);
    if (valid.length) onChange([...values, ...valid.filter((v) => !values.includes(v))]);
    setDraft('');
  };
  return (
    <div className="flex flex-wrap gap-1.5 px-2 py-1.5 border border-slate-300 rounded-lg bg-white focus-within:ring-2 focus-within:ring-brand-blue/30">
      {values.map((v) => (
        <span key={v} className="inline-flex items-center gap-1 bg-brand-blue-soft text-brand-blue text-xs px-2 py-0.5 rounded-full" data-testid={`${testid}-pill-${v}`}>
          {v}
          <button type="button" onClick={() => onChange(values.filter((x) => x !== v))} className="hover:text-blue-700" aria-label="remove">
            <XIcon size={10} />
          </button>
        </span>
      ))}
      <input
        value={draft}
        onChange={(e) => setDraft(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ',') { e.preventDefault(); commit(); }
          if (e.key === 'Backspace' && !draft && values.length) onChange(values.slice(0, -1));
        }}
        onBlur={() => draft && commit()}
        placeholder={values.length === 0 ? placeholder : ''}
        className="flex-1 min-w-[180px] text-sm border-0 outline-none bg-transparent px-1 py-0.5"
        data-testid={testid}
      />
    </div>
  );
}

export default function EmailSendModal({
  isOpen, onClose,
  resourceKind, recordId,
  defaultSubject = '', defaultBody = '', defaultRecipients = [],
  attachments = [],
  convenienceEndpoint = null,
  onSent,
}) {
  const [to, setTo] = useState(defaultRecipients);
  const [cc, setCc] = useState([]);
  const [showCc, setShowCc] = useState(false);
  const [subject, setSubject] = useState(defaultSubject);
  const [message, setMessage] = useState(defaultBody.replace(/<[^>]+>/g, '').trim());
  const [m365Connected, setM365Connected] = useState(false);
  const [busy, setBusy] = useState(false);
  useLockBodyScroll(isOpen);

  useEffect(() => {
    if (!isOpen) return;
    setTo(defaultRecipients);
    setCc([]);
    setSubject(defaultSubject);
    setMessage(defaultBody.replace(/<[^>]+>/g, '').trim());
    api.get('/integrations').then(({ data }) => {
      const m = (data || []).find((x) => x.kind === 'microsoft365');
      setM365Connected(m?.status === 'connected');
    }).catch(() => setM365Connected(false));
  }, [isOpen, defaultSubject, defaultBody, defaultRecipients.join(',')]); // eslint-disable-line

  if (!isOpen) return null;

  const body_html = message.split(/\n\n+/).map((p) => `<p>${p.replace(/\n/g, '<br/>')}</p>`).join('');

  const send = async () => {
    if (to.length === 0) { toast.error('Add at least one recipient'); return; }
    if (!subject.trim()) { toast.error('Subject required'); return; }
    setBusy(true);
    try {
      let resp;
      if (convenienceEndpoint) {
        const url = convenienceEndpoint.replace('{id}', recordId);
        resp = (await api.post(url, { to, cc, message })).data;
      } else {
        resp = (await api.post('/email/send', {
          to, cc, subject, body_html,
          related_record_type: resourceKind, related_record_id: recordId,
          resource_kind: resourceKind,
          attachments: attachments.map((a) => ({ file_url: a.file_url, filename: a.label || a.filename })),
        })).data;
      }
      const sentNow = resp.status === 'sent';
      toast.success(sentNow ? 'Email sent via Microsoft 365' : 'Email queued in outbox', {
        description: sentNow ? null : 'M365 not connected — message stored',
        action: { label: 'View outbox', onClick: () => { window.location.href = '/app/outbox'; } },
      });
      onSent?.(resp);
      onClose();
    } catch (e) {
      const msg = apiError(e);
      if (e?.response?.status === 403) toast.error("You don't have permission to email this record.");
      else toast.error(msg || 'Failed to send');
    } finally { setBusy(false); }
  };

  return (
    <div className="fixed inset-0 bg-black/40 z-50 flex items-center justify-center p-3 sm:p-6" onClick={onClose}>
      <div className="bg-white rounded-2xl w-full max-w-xl max-h-[92vh] overflow-auto shadow-card-lg" onClick={(e) => e.stopPropagation()} data-testid="email-send-modal">
        <div className="flex items-start justify-between px-6 py-4 border-b border-slate-100">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-full bg-brand-blue-soft flex items-center justify-center"><Mail size={14} className="text-brand-blue" /></div>
            <div>
              <h2 className="font-display text-lg leading-tight">Send via email</h2>
              <div className="text-[11px] text-slate-500 uppercase tracking-wider">{resourceKind}</div>
            </div>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-700 text-2xl leading-none">&times;</button>
        </div>

        <div className="px-6 py-5 space-y-4">
          <div>
            <div className="text-[11px] uppercase tracking-[0.14em] font-semibold text-slate-500 mb-1.5">To</div>
            <PillInput values={to} onChange={setTo} placeholder="recipient@example.com" testid="email-to-input" />
          </div>

          <button type="button" onClick={() => setShowCc((s) => !s)} className="text-xs text-slate-500 hover:text-slate-800 inline-flex items-center gap-1" data-testid="toggle-cc">
