// Phase 4.9.1 — Fallback card for assets whose lifetime odometer can't be
// trusted (e.g. Kroll Recycler XT04CS: Navixy `get_counters` returns `[]`,
// the report API isn't on the plan, and the lifetime track-sum still under-
// shot the last 30 days of trips). Admins get an inline form to file a
// historical reading via `POST /api/assets/{id}/meter-history`; everyone
// else just sees the explainer.
function UnreliableOdoCard({ asset, onAssetUpdated }) {
  const user = getUser();
  // v160.3.9.29-2c — Migrated to users.edit (coarse identity, decision #3).
  const canEdit = useCan()('users', 'edit');
  void user;
  const [open, setOpen] = useState(false);
  const [date, setDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [km, setKm] = useState('');
  const [busy, setBusy] = useState(false);

  const submit = async () => {
    const n = Number(km);
    if (!Number.isFinite(n) || n < 0) { toast.error('Enter a non-negative km value'); return; }
    if (!date) { toast.error('Pick a date'); return; }
    setBusy(true);
    try {
      await api.post(`/assets/${asset.id}/meter-history`, {
        date, odometer_km: n,
      });
      toast.success('Historical odometer reading saved');
      setOpen(false); setKm('');
      try {
        const a = await api.get(`/assets/${asset.id}`);
        if (onAssetUpdated) onAssetUpdated(a.data);
      } catch { /* swallow */ }
    } catch (e) { toast.error(apiError(e)); }
    finally { setBusy(false); }
  };

  return (
    <div className="px-3 py-2.5 rounded-xl border border-amber-300 bg-amber-50/70 flex items-start gap-2.5"
      data-testid="counter-card-odo-unreliable">
      <div className="w-8 h-8 rounded-lg bg-white/80 border border-amber-300 flex items-center justify-center shrink-0">
        <Gauge size={15} className="text-amber-700" />
      </div>
      <div className="flex-1 min-w-0">
        <div className="text-[10px] uppercase tracking-wider font-bold text-amber-800/80">Odometer</div>
        <div className="mt-0.5 font-display text-base font-semibold text-amber-900 leading-tight">
          Lifetime not available
        </div>
        <div className="text-[10px] text-amber-800/80 mt-0.5 leading-snug">
          No panel counter — the GPS-derived estimate is lower than this month{`'`}s trips. Add a historical reading to anchor future deltas.
        </div>
        {canEdit && !open && (
          <button onClick={() => setOpen(true)} data-testid="odo-add-reading-btn"
            className="mt-1.5 inline-flex items-center gap-1 text-[11px] font-semibold text-amber-800 hover:text-amber-900 underline">
            + Add a historical reading
          </button>
        )}
        {canEdit && open && (
          <div className="mt-2 flex flex-wrap items-center gap-1.5" data-testid="odo-add-reading-form">
            <input type="date" value={date} onChange={(e) => setDate(e.target.value)}
              className="px-2 py-1 border border-amber-300 rounded-md text-[11px]"
              data-testid="odo-add-reading-date" />
            <input type="number" min="0" placeholder="Total km" value={km}
              onChange={(e) => setKm(e.target.value)}
              className="px-2 py-1 border border-amber-300 rounded-md text-[11px] w-24 tabular-nums"
              data-testid="odo-add-reading-km" />
            <button onClick={submit} disabled={busy}
              className="inline-flex items-center justify-center px-2 py-1 rounded-md bg-amber-600 text-white text-[11px] font-semibold hover:bg-amber-700 disabled:opacity-50"
              data-testid="odo-add-reading-submit">
              {busy ? <Loader2 size={11} className="animate-spin" /> : 'Save'}
            </button>
            <button onClick={() => setOpen(false)} disabled={busy}
              className="px-2 py-1 rounded-md text-[11px] font-semibold text-amber-800 hover:bg-amber-100"
              data-testid="odo-add-reading-cancel">Cancel</button>
          </div>
        )}
      </div>
    </div>
  );
}

function NavixyCounters({ asset, onAssetUpdated }) {  const user = getUser();
  // v160.3.9.29-2c — Migrated to users.edit (coarse identity, decision #3).
  const _can = useCan();
  const canRefresh = _can('users', 'edit');
  const canEdit = _can('users', 'edit');
  void user;
  const [refreshing, setRefreshing] = useState(false);
  const [historyOpen, setHistoryOpen] = useState(false);
  // Phase 4.8 — tabs + meter-trends fetch.
  const [tab, setTab] = useState('total'); // 'total' | 'week' | 'month'
  const [trends, setTrends] = useState(null);
  useEffect(() => {
    let alive = true;
    api.get(`/assets/${asset.id}/meter-trends`)
      .then((r) => { if (alive) setTrends(r.data); })
      .catch(() => { if (alive) setTrends({ error: true }); });
    return () => { alive = false; };
  }, [asset.id]);

  const refreshNow = async () => {
    setRefreshing(true);
    try {
      const r = await api.post('/assets/navixy/sync-counters');
      const d = r.data || {};
      if (d.updated > 0) toast.success(`Synced ${d.updated} asset${d.updated === 1 ? '' : 's'} from Navixy`);
      else toast.info(`No new readings — last sync still current (${d.devices || 0} devices polled)`);
      // Refetch this asset so the UI reflects the latest values
      try {
        const a = await api.get(`/assets/${asset.id}`);
        if (onAssetUpdated) onAssetUpdated(a.data);
        // also reload trends — the latest snapshot may have shifted
        const t = await api.get(`/assets/${asset.id}/meter-trends`);
        setTrends(t.data);
      } catch { /* swallow — UI will reload on its own */ }
    } catch (e) { toast.error(apiError(e)); }
    finally { setRefreshing(false); }
  };

  const hoursAgo = fmtAgo(asset.hours_meter_updated_at);
  const kmAgo = fmtAgo(asset.odo_km_updated_at);
  const syncedAgo = fmtAgo(asset.navixy_last_seen_at);
  const navixyAgo = fmtAgo(asset.navixy_last_position_time);

  const renderTotal = () => {
    // Phase 4.9.1 — surface the actual source per metric. Distinguishes a
    // Navixy panel counter (authoritative) from GPS-derived track-window
    // sums (estimates) so users can tell when a low number is "real" vs
    // "Navixy doesn't have a panel counter for this device".
    const srcLabel = (s) => {
      if (!s) return 'Synced from Navixy';
      if (s === 'panel' || s === 'navixy' || s === 'navixy_counters_v2') return 'Synced from Navixy · panel counter';
      if (s === 'navixy_report') return 'Synced from Navixy · mileage report';
      if (s === 'navixy_tracks_lifetime') return 'Estimated · sum of all trips since first sync';
      if (s.includes('tracks')) return 'GPS-derived (no panel counter)';
      if (s === 'manual') return 'Manually entered';
      return `Synced from Navixy · ${s}`;
    };
    // Phase 4.9.1 — when the backend repair couldn't recover a sensible
    // lifetime odometer (Navixy's `get_counters` returned `[]`, the report
    // API isn't on this plan, AND lifetime track-sum still under-shot the
    // last 30 days of trips), surface a fallback UI instead of a misleading
    // low number. Admins can punch in a historical reading inline.
    const odoUnreliable = !!asset.lifetime_unreliable;
    return (
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
        <CounterCardShell
          icon={Activity} label="Engine hours" unit="hrs"
          value={fmtHours(asset.hours_meter)}
          sub={`${srcLabel(asset.hours_meter_source)}${hoursAgo ? ' · ' + hoursAgo : ''}`}
          accent="border-emerald-200 bg-white"
          testid="counter-card-hours" />
        {odoUnreliable
          ? <UnreliableOdoCard asset={asset} onAssetUpdated={onAssetUpdated} />
          : <CounterCardShell
              icon={Gauge} label="Odometer" unit="km"
              value={fmtKm(asset.odo_km)}
              sub={`${srcLabel(asset.odo_km_source)}${kmAgo ? ' · ' + kmAgo : ''}`}
              accent="border-emerald-200 bg-white"
              testid="counter-card-odo" />
        }
      </div>
    );
  };

  const renderDelta = (slot, label) => {
    if (!trends || trends.error) {
      return <div className="text-xs text-slate-500 py-6 text-center" data-testid={`trends-${label}-empty`}>
        Collecting data — try again in a few minutes.
      </div>;
    }
    const s = trends[label]; // 'week' | 'month'
    const total = label === 'week' ? 7 : 30;
    const collecting = (s.days_available || 0) < total;
    return (
      <>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
          <div className="rounded-xl border border-emerald-200 bg-white p-3" data-testid={`counter-card-hours-${label}`}>
            <div className="flex items-center gap-2 text-[10px] uppercase tracking-wider font-bold text-slate-500">
              <Activity size={12} /> Engine hours
            </div>
            <div className="mt-1 font-display text-2xl font-bold text-slate-900">
              {fmtSigned(s.engine_hours_delta, 1)}
              <span className="text-sm text-slate-400 font-normal ml-1">hrs</span>
            </div>
            <div className="text-[11px] text-slate-500 mt-0.5">
              Daily avg: <span className="font-semibold text-slate-700">{s.daily_avg_hours} hrs · {s.daily_avg_km} km</span>
            </div>
            <Sparkline data={s.sparkline} dataKey="engine_hours" color="#10B981" />
          </div>
          <div className="rounded-xl border border-emerald-200 bg-white p-3" data-testid={`counter-card-odo-${label}`}>
            <div className="flex items-center gap-2 text-[10px] uppercase tracking-wider font-bold text-slate-500">
              <Gauge size={12} /> Odometer
            </div>
            <div className="mt-1 font-display text-2xl font-bold text-slate-900">
              {fmtSigned(s.odometer_km_delta, 0)}
              <span className="text-sm text-slate-400 font-normal ml-1">km</span>
            </div>
            <div className="text-[11px] text-slate-500 mt-0.5">
              Daily avg: <span className="font-semibold text-slate-700">{s.daily_avg_hours} hrs · {s.daily_avg_km} km</span>
            </div>
            <Sparkline data={s.sparkline} dataKey="odometer_km" color="#F97316" />
          </div>
        </div>
        {collecting && (
          <div className="mt-2 text-[11px] text-slate-500" data-testid={`trends-${label}-collecting`}>
            Collecting data — {s.days_available} of {total} day{total === 1 ? '' : 's'} available. Daily snapshots accumulate at 01:00 UTC.
          </div>
        )}
      </>
    );
  };

  return (
    <div className="rounded-2xl border border-emerald-200 bg-emerald-50/40 p-3" data-testid="live-counters-navixy">
      <div className="flex items-center justify-between mb-2">
        <div className="text-[10px] uppercase tracking-wider font-bold text-emerald-700 inline-flex items-center gap-1.5">
          <span className="inline-flex items-center px-1.5 py-0.5 rounded bg-emerald-600 text-white text-[9px]">LIVE</span>
          <span>Live counters · Navixy</span>
        </div>
        <div className="inline-flex items-center gap-1.5">
        {canRefresh && (
          <button onClick={refreshNow} disabled={refreshing}
            className="inline-flex items-center gap-1 text-[11px] font-semibold text-emerald-700 hover:text-emerald-900 disabled:opacity-50"
            data-testid="live-counters-refresh">
            {refreshing ? <Loader2 size={11} className="animate-spin" /> : <RefreshCcw size={11} />}
            Refresh now
          </button>
        )}
        {canEdit && (
          <AddReadingTrigger accent="emerald" testid="live-counters-history-open"
                             onClick={() => setHistoryOpen(true)} />
        )}
        </div>
      </div>
      {(syncedAgo || navixyAgo) && (
        <div
          title="Synced with Paneltec = when we last polled Navixy successfully. Navixy last heard = when the tracker last sent a position fix. A large gap between the two usually means the device is parked or out of mobile coverage."
          className="flex flex-wrap items-center gap-x-3 gap-y-0.5 mb-2 text-[10px] text-slate-600"
          data-testid="navixy-dual-timestamps">
          {syncedAgo && (
            <span className="inline-flex items-center gap-1" data-testid="navixy-synced-paneltec">
              <span className="inline-block w-1.5 h-1.5 rounded-full bg-emerald-500" />
              Synced with Paneltec: <span className="font-semibold text-slate-800">{syncedAgo}</span>
            </span>
          )}
          {navixyAgo && (
            <span className="inline-flex items-center gap-1" data-testid="navixy-last-heard">
              <span className="inline-block w-1.5 h-1.5 rounded-full bg-blue-500" />
              Navixy last heard: <span className="font-semibold text-slate-800">{navixyAgo}</span>
            </span>
          )}
        </div>
      )}

      {/* Phase 4.8 — tab strip */}
      <div className="inline-flex items-center gap-0.5 mb-2.5 p-0.5 rounded-lg bg-white border border-emerald-200" role="tablist">
        {[
          { k: 'total', label: 'Total' },
          { k: 'week',  label: 'This Week' },
          { k: 'month', label: 'Last Month' },
        ].map((t) => (
          <button key={t.k} role="tab" aria-selected={tab === t.k}
            onClick={() => setTab(t.k)}
            data-testid={`meter-tab-${t.k}`}
            className={`px-2.5 py-1 rounded-md text-[11px] font-semibold transition-colors ${
              tab === t.k ? 'bg-orange-500 text-white' : 'text-slate-600 hover:bg-slate-50'
            }`}>
            {t.label}
          </button>
        ))}
      </div>

      {tab === 'total' && renderTotal()}
      {tab === 'week'  && renderDelta('week', 'week')}
      {tab === 'month' && renderDelta('month', 'month')}

      <div className="text-[10px] text-slate-500 mt-2 leading-snug">
        {tab === 'total'
          ? 'These values come from the Navixy tracker. Manual edits are disabled — change them in Navixy or, for admin overrides, use the meter reset action.'
          : 'Deltas are computed from daily snapshots of the Navixy counters. Manual edits are disabled.'}
      </div>

      <HistoricalReadingModal
        asset={asset} open={historyOpen}
        onClose={() => setHistoryOpen(false)}
        onSaved={(a) => { if (onAssetUpdated) onAssetUpdated(a); }}
      />
    </div>
  );
}

function ManualCounters({ asset, onAssetUpdated }) {
  const user = getUser();
  // v160.3.9.29-2c — Migrated to users.edit (coarse identity, decision #3).
  const canEdit = useCan()('users', 'edit');
  void user;
  const [historyOpen, setHistoryOpen] = useState(false);
  const [hours, setHours] = useState(asset.hours_meter ?? '');
  const [km, setKm] = useState(asset.odo_km ?? '');
  const [busy, setBusy] = useState(null); // 'hours' | 'km' | null
  const [savedH, setSavedH] = useState(false);
  const [savedK, setSavedK] = useState(false);

  const save = async (kind) => {
    const v = kind === 'hours' ? hours : km;
    if (v === '' || v == null) { toast.error('Enter a value'); return; }
    setBusy(kind);
    try {
      const payload = {
        type: 'meter_update',
        title: kind === 'hours' ? 'Hours updated' : 'Odometer updated',
        [kind === 'hours' ? 'hours_at' : 'km_at']: Number(v),
      };
      await api.post(`/assets/${asset.id}/records`, payload);
      toast.success(`${kind === 'hours' ? 'Engine hours' : 'Odometer'} updated`);
      if (kind === 'hours') { setSavedH(true); setTimeout(() => setSavedH(false), 2000); }
      else { setSavedK(true); setTimeout(() => setSavedK(false), 2000); }
      try {
        const a = await api.get(`/assets/${asset.id}`);
        if (onAssetUpdated) onAssetUpdated(a.data);
      } catch { /* ignore */ }
    } catch (e) { toast.error(apiError(e)); }
    finally { setBusy(null); }
  };

  const hoursAgo = fmtAgo(asset.hours_meter_updated_at);
  const kmAgo = fmtAgo(asset.odo_km_updated_at);

  return (
    <div className="rounded-2xl border border-slate-200 bg-slate-50/60 p-3" data-testid="live-counters-manual">
      <div className="flex items-center justify-between mb-2">
        <div className="text-[10px] uppercase tracking-wider font-bold text-slate-600">Live counters · Manual</div>
        {canEdit && (
          <AddReadingTrigger accent="slate" testid="live-counters-manual-history-open"
                             onClick={() => setHistoryOpen(true)} />
        )}
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
        {/* Engine hours */}
        <div className="px-3 py-2.5 rounded-xl border border-slate-200 bg-white" data-testid="counter-card-hours">
          <div className="flex items-center gap-2 mb-1.5">
            <div className="w-7 h-7 rounded-lg bg-emerald-50 border border-emerald-200 flex items-center justify-center">
              <Activity size={13} className="text-emerald-700" />
            </div>
            <div className="text-[10px] uppercase tracking-wider font-bold text-slate-600">Engine hours</div>
          </div>
          <div className="flex items-center gap-2">
            <input type="number" step="0.1" value={hours} onChange={(e) => setHours(e.target.value)}
              className="flex-1 min-w-0 px-2.5 py-1.5 border border-slate-300 rounded-lg text-sm font-semibold tabular-nums"
              placeholder="0.0" data-testid="counter-input-hours" />
            <span className="text-xs font-semibold text-slate-500">hrs</span>
            <button onClick={() => save('hours')} disabled={busy === 'hours'}
              className="inline-flex items-center justify-center w-8 h-8 rounded-lg bg-blue-600 text-white hover:bg-blue-700 disabled:opacity-50"
              data-testid="counter-save-hours" aria-label="Save hours">
              {busy === 'hours' ? <Loader2 size={13} className="animate-spin" />
                : savedH ? <CheckCircle2 size={13} /> : <Save size={13} />}
            </button>
          </div>
          <div className="text-[10px] text-slate-500 mt-1">{hoursAgo ? `Last updated ${hoursAgo}` : 'Not yet recorded'}</div>
        </div>
        {/* Odometer */}
        <div className="px-3 py-2.5 rounded-xl border border-slate-200 bg-white" data-testid="counter-card-odo">
          <div className="flex items-center gap-2 mb-1.5">
            <div className="w-7 h-7 rounded-lg bg-emerald-50 border border-emerald-200 flex items-center justify-center">
              <Gauge size={13} className="text-emerald-700" />
            </div>
            <div className="text-[10px] uppercase tracking-wider font-bold text-slate-600">Odometer</div>
          </div>
          <div className="flex items-center gap-2">
            <input type="number" value={km} onChange={(e) => setKm(e.target.value)}
              className="flex-1 min-w-0 px-2.5 py-1.5 border border-slate-300 rounded-lg text-sm font-semibold tabular-nums"
              placeholder="0" data-testid="counter-input-km" />
            <span className="text-xs font-semibold text-slate-500">km</span>
            <button onClick={() => save('km')} disabled={busy === 'km'}
              className="inline-flex items-center justify-center w-8 h-8 rounded-lg bg-blue-600 text-white hover:bg-blue-700 disabled:opacity-50"
              data-testid="counter-save-km" aria-label="Save km">
              {busy === 'km' ? <Loader2 size={13} className="animate-spin" />
                : savedK ? <CheckCircle2 size={13} /> : <Save size={13} />}
            </button>
          </div>
          <div className="text-[10px] text-slate-500 mt-1">{kmAgo ? `Last updated ${kmAgo}` : 'Not yet recorded'}</div>
        </div>
      </div>
      <HistoricalReadingModal
        asset={asset} open={historyOpen}
        onClose={() => setHistoryOpen(false)}
        onSaved={(a) => { if (onAssetUpdated) onAssetUpdated(a); }}
      />
    </div>
  );
}

// Phase 3.14 — Import suppliers from Simpro into the contractor pool that
// backs Renewal Links. Top-level layout: search box + Refresh button at top,
// virtualised checkbox list in the middle, "Import N suppliers" at the
// bottom. Rows already promoted to contractors show a green "✓ Imported"
// badge with checkbox disabled.
import { useEffect, useMemo, useRef, useState } from 'react';
import { X, Loader2, RefreshCw, Check, Search, Download } from 'lucide-react';
import { toast } from 'sonner';
import api, { apiError } from '../lib/api';
import { getUser } from '../lib/auth';
import { useCan } from '../lib/permissions';
// v160.3.7k — Inoculation sweep: lock body scroll while this modal is open.
import useLockBodyScroll from '../lib/useLockBodyScroll';

// v160.3.9.29-2c — Legacy set retained; single authoritative gate below.
// PRIOR BUG (fixed here): the modal had 5 inconsistent gates:
//   Line 14: WRITE_ROLES = ['admin','manager'] (button visibility)
//   Line 58: user?.role !== 'admin' (submit-guard — STRICTER than button)
//   Lines 110-112: same admin-only submit-guard for the Refresh button
// Result: manager saw the buttons, clicked, got 403'd at confirm.
// Fix: ONE token drives everything — visibility + disabled + confirm.
const WRITE_ROLES = new Set(['admin', 'manager']);
const ROW_HEIGHT = 60; // px — used for windowed scroll calculation

export default function SimproSupplierImportModal({ onClose, onImported }) {
  useLockBodyScroll();
  const user = getUser();
  // v160.3.9.29-2c — LIVE BUG FIX: previously visibility used
  // `WRITE_ROLES=['admin','manager']` but confirm-guard used
  // `user?.role !== 'admin'` (stricter). A manager saw the buttons,
  // clicked, then got a "Admin only" toast at submit — broken UX.
  // Now ONE token drives visibility, disabled state, AND the confirm
  // guard, aligned with the backend's `integrations.edit` permission.
  const canImport = useCan()('integrations', 'edit');
  void user; void WRITE_ROLES;
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [importing, setImporting] = useState(false);
  const [search, setSearch] = useState('');
  const [selected, setSelected] = useState(() => new Set());
  const scrollRef = useRef(null);
  const [scrollTop, setScrollTop] = useState(0);

  const load = async () => {
    setLoading(true);
    try {
      const r = await api.get('/integrations/simpro/suppliers/cached', { params: { limit: 2000 } });
      setRows(r.data?.suppliers || []);
    } catch (e) { toast.error(apiError(e)); }
    finally { setLoading(false); }
  };
  useEffect(() => { load(); /* eslint-disable-next-line */ }, []);

  // ESC closes.
  useEffect(() => {
    const k = (e) => { if (e.key === 'Escape') onClose?.(); };
    window.addEventListener('keydown', k);
    return () => window.removeEventListener('keydown', k);
  }, [onClose]);

  const filtered = useMemo(() => {
    if (!search.trim()) return rows;
    const q = search.toLowerCase();
    return rows.filter((r) =>
      (r.name || '').toLowerCase().includes(q) ||
      (r.abn || '').toLowerCase().includes(q) ||
      (r.email || '').toLowerCase().includes(q),
    );
  }, [rows, search]);

  const refresh = async () => {
    if (!canImport) {
      toast.error('You don\u2019t have permission to refresh Simpro data');
      return;
    }
    setRefreshing(true);
    try {
      const r = await api.post('/integrations/simpro/sync-suppliers');
      toast.success(`Synced from Simpro · imported ${r.data?.imported} / updated ${r.data?.updated}`);
      await load();
    } catch (e) { toast.error(apiError(e)); }
    finally { setRefreshing(false); }
  };

  const toggle = (id, isImported) => {
    if (isImported) return; // can't re-tick already-imported rows
    const n = new Set(selected);
    if (n.has(id)) n.delete(id); else n.add(id);
    setSelected(n);
  };

  const doImport = async () => {
    if (selected.size === 0) return;
    setImporting(true);
    try {
      const r = await api.post('/contractors/import-from-simpro',
        { vendor_ids: [...selected] });
      const { created, updated, skipped } = r.data || {};
      toast.success(`Imported ${created} new · updated ${updated} · skipped ${skipped}`);
      onImported?.(r.data?.contractors || []);
      onClose?.();
    } catch (e) { toast.error(apiError(e)); }
    finally { setImporting(false); }
  };

  // Windowed scroll — show 12 extra rows above/below to keep momentum smooth.
  const overscan = 12;
  const totalHeight = filtered.length * ROW_HEIGHT;
  const start = Math.max(0, Math.floor(scrollTop / ROW_HEIGHT) - overscan);
  const end = Math.min(filtered.length, start + 30 + overscan * 2);
  const slice = filtered.slice(start, end);

  return (
    <div className="fixed inset-0 z-50 bg-slate-900/60 grid place-items-center p-0 md:p-6"
         data-testid="simpro-supplier-modal"
         onClick={(e) => e.target === e.currentTarget && onClose?.()}>
      <div className="w-full h-full md:max-w-3xl md:h-[88vh] bg-white md:rounded-2xl shadow-2xl flex flex-col overflow-hidden">
        {/* Header */}
        <div className="px-5 py-3 border-b border-slate-200 bg-slate-50 flex items-center gap-2">
          <div className="flex-1 min-w-0">
            <div className="text-[10px] uppercase tracking-[0.16em] font-semibold text-slate-500">Simpro · vendors</div>
            <h2 className="text-lg font-bold text-slate-900">Import suppliers</h2>
          </div>
          <button onClick={refresh} disabled={refreshing || !canImport}
            data-testid="simpro-supplier-refresh"
            title={!canImport ? 'Requires integrations.edit permission' : 'Pull latest vendor list from Simpro'}
            className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg border border-slate-300 bg-white text-xs font-semibold text-slate-700 hover:bg-slate-50 disabled:opacity-50">
            {refreshing ? <Loader2 size={12} className="animate-spin" /> : <RefreshCw size={12} />} Refresh from Simpro
          </button>
          <button onClick={onClose} className="w-9 h-9 grid place-items-center rounded-lg text-slate-500 hover:bg-slate-200">
            <X size={16} />
          </button>
        </div>

        {/* Search */}
        <div className="px-5 py-3 border-b border-slate-100 flex items-center gap-2">
          <div className="flex-1 relative">
            <Search size={13} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <input value={search} onChange={(e) => setSearch(e.target.value)}
              data-testid="simpro-supplier-search"
              placeholder="Search by name, ABN or email…"
              className="w-full pl-9 pr-3 py-2 text-sm border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#1e4a8c]/30" />
          </div>
          <div className="text-[11px] text-slate-500 whitespace-nowrap">
            {filtered.length} of {rows.length}
          </div>
        </div>

        {/* Body — windowed list */}
        <div ref={scrollRef} onScroll={(e) => setScrollTop(e.currentTarget.scrollTop)}
             className="flex-1 overflow-y-auto bg-slate-50">
          {loading ? (
            <div className="grid place-items-center h-full text-slate-400">
              <div className="inline-flex items-center gap-2 text-sm">
                <Loader2 size={14} className="animate-spin" /> Loading suppliers…
              </div>
            </div>
          ) : filtered.length === 0 ? (
            <div className="grid place-items-center h-full text-slate-400 text-sm">
              {rows.length === 0
                ? <span>No suppliers cached. Click <b>Refresh from Simpro</b> to pull the latest.</span>
                : <span>No matches for "{search}"</span>}
            </div>
          ) : (
            <div style={{ height: totalHeight, position: 'relative' }}>
              <div style={{ transform: `translateY(${start * ROW_HEIGHT}px)` }}>
                {slice.map((s) => {
                  const isImported = !!s.imported_contractor_id;
                  const checked = selected.has(s.simpro_vendor_id);
                  return (
                    <div key={s.simpro_vendor_id}
                      data-testid={`simpro-supplier-row-${s.simpro_vendor_id}`}
                      data-imported={isImported ? 'true' : 'false'}
                      onClick={() => toggle(s.simpro_vendor_id, isImported)}
                      className={`flex items-start gap-3 px-5 py-2 border-b border-slate-100 bg-white ${isImported ? 'opacity-60 cursor-default' : 'cursor-pointer hover:bg-[#f5f9ff]'}`}
                      style={{ height: ROW_HEIGHT }}>
                      <input type="checkbox" checked={checked} disabled={isImported}
                        readOnly onChange={() => {}}
                        className="mt-1 w-4 h-4 accent-[#1e4a8c]" />
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <div className="font-medium text-sm text-slate-900 truncate">{s.name}</div>
                          {isImported && (
                            <span className="inline-flex items-center gap-1 text-[10px] font-semibold uppercase tracking-wider px-1.5 py-0.5 rounded bg-[#d8ecdd] text-[#1f7a3f]">
                              <Check size={10} /> Imported
                            </span>
                          )}
                        </div>
                        <div className="text-[11px] text-slate-500 truncate">
                          {s.abn ? `ABN ${s.abn} · ` : ''}{s.email || 'no email'}{s.phone ? ` · ${s.phone}` : ''}
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="px-5 py-3 border-t border-slate-200 bg-slate-50 flex items-center justify-end gap-2">
          <div className="flex-1 text-[11px] text-slate-500">
            {selected.size === 0 ? 'Tick suppliers to import.' : `${selected.size} selected.`}
          </div>
          <button onClick={onClose} className="px-4 py-2 rounded-lg border border-slate-300 bg-white text-sm font-medium text-slate-700 hover:bg-slate-100">
            Cancel
          </button>
          <button onClick={doImport} disabled={!canImport || importing || selected.size === 0}
            data-testid="simpro-import-confirm"
            className="inline-flex items-center gap-1.5 px-4 py-2 rounded-lg bg-[#1e4a8c] text-white text-sm font-semibold uppercase tracking-wider hover:bg-[#143263] disabled:opacity-60">
            {importing ? <Loader2 size={12} className="animate-spin" /> : <Download size={12} />}
            Import {selected.size > 0 ? `${selected.size} suppliers` : ''}
          </button>
        </div>
      </div>
    </div>
  );
}

// Phase 3.11 — Per-worker Inductions card shown inside the worker drawer.
// Phase 3.12 — Cards now open `InductionCardModal` (view/edit/add).
import { useEffect, useState } from 'react';
import { Loader2, CalendarOff, Check, FileText, AlertTriangle } from 'lucide-react';
import api, { apiError } from '../lib/api';
import { filesUrl } from '../lib/downloadUrl';
import { toast } from 'sonner';
import InductionCardModal from './InductionCardModal';

const STATUS_CHIP = {
  current:        { label: 'Current',  cls: 'bg-[#d8ecdd] text-[#1f7a3f]' },
  expiring:       { label: 'Expiring', cls: 'bg-[#fef3c7] text-[#92400e]' },
  expired:        { label: 'Expired',  cls: 'bg-[#fbe4e7] text-[#7a1f33]' },
  not_held:       { label: 'Not held', cls: 'bg-slate-100 text-slate-500' },
  held_no_expiry: { label: 'Held',     cls: 'bg-[#e6eff9] text-[#1e4a8c]' },
  invalid_date:   { label: 'Invalid',  cls: 'bg-[#fbe4e7] text-[#7a1f33]' },
  unknown:        { label: '—',        cls: 'bg-slate-50 text-slate-400 border border-dashed border-slate-300' },
};

export default function WorkerInductionsCard({ workerId, workerName }) {
  const [row, setRow] = useState(null);
  const [cols, setCols] = useState([]);
  const [loading, setLoading] = useState(true);
  // Phase 3.12 — modal target. `{inductionId?, inductionNameHint?, mode}`.
  const [modal, setModal] = useState(null);

  const load = async () => {
    setLoading(true);
    try {
      const { data } = await api.get('/workers/inductions/matrix');
      setCols(data.columns);
      setRow(data.rows.find((r) => r.id === workerId) || null);
    } catch (e) { toast.error(apiError(e)); }
    finally { setLoading(false); }
  };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { load(); }, [workerId]);

  const openCard = (col, cell) => {
    if (cell?.cert_id) {
      setModal({ inductionId: cell.cert_id, mode: 'view' });
    } else {
      // Empty slot — open in add mode with column header as the name hint.
      setModal({ inductionNameHint: col.header, mode: 'add' });
    }
  };

  if (loading) {
    return (
      <div className="text-xs text-slate-400 inline-flex items-center gap-2">
        <Loader2 size={12} className="animate-spin" /> Loading inductions…
      </div>
    );
  }
  if (!row || cols.length === 0) {
    return (
      <p className="text-xs text-slate-400 italic">No induction columns set up. Import an .xlsx from the Inductions Matrix tab.</p>
    );
  }

  return (
    <>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2" data-testid={`worker-inductions-${workerId}`}>
        {cols.map((c) => {
          const cell = row.cells[c.column_key];
          const meta = STATUS_CHIP[cell?.status || 'unknown'];
          return (
            <button key={c.column_key} type="button"
              onClick={() => openCard(c, cell)}
              data-testid={`induction-card-${c.column_key}`}
              className="flex items-center justify-between gap-2 px-3 py-2 rounded-lg bg-slate-50 border border-slate-100 text-left hover:bg-white hover:border-[#bcd2ee] hover:shadow-sm transition-all cursor-pointer">
              <div className="min-w-0">
                <div className="text-[11px] font-medium text-slate-900 truncate">{c.header}</div>
                <div className="text-[10px] uppercase tracking-wider text-slate-400">{c.category.replace('_', ' ')}</div>
              </div>
              <div className="flex flex-col items-end gap-1 flex-shrink-0">
                <span className={`inline-flex items-center text-[10px] font-medium px-1.5 py-0.5 rounded ${meta.cls}`}>
                  {cell?.not_held ? <CalendarOff size={9} className="mr-1" /> : null}
                  {cell?.held_no_expiry ? <Check size={9} className="mr-1" /> : null}
                  {meta.label}
                </span>
                {/* v160.3.5b — per-row file-presence chip */}
                <FilePresenceChip
                  workerId={workerId}
                  cell={cell}
                />
                {cell?.expiry_date && (
                  <span className="text-[10px] font-mono text-slate-500">
                    {cell.expiry_date.slice(8, 10)}/{cell.expiry_date.slice(5, 7)}/{cell.expiry_date.slice(2, 4)}
                  </span>
                )}
              </div>
            </button>
          );
        })}
        {(row.access?.vehicle || row.access?.building_key || row.access?.gate_key || row.access?.extras) && (
          <div className="col-span-full px-3 py-2 rounded-lg bg-[#f5f3ff] border border-[#ddd6fe]">
            <div className="text-[10px] uppercase tracking-wider font-semibold text-[#5b21b6] mb-1">Access</div>
            <div className="flex flex-wrap gap-1.5">
              {row.access.vehicle && <Tag>Vehicle</Tag>}
              {row.access.building_key && <Tag>Building key</Tag>}
              {row.access.gate_key && <Tag>Gate key</Tag>}
              {row.access.extras && <span className="text-[11px] text-slate-500">· {row.access.extras}</span>}
            </div>
          </div>
        )}
      </div>

      {modal && (
        <InductionCardModal
          workerId={workerId}
          workerName={workerName || row?.name}
          inductionId={modal.inductionId}
          inductionNameHint={modal.inductionNameHint}
          initialMode={modal.mode}
          onClose={() => setModal(null)}
          onSaved={() => { load(); }}
        />
      )}
    </>
  );
}

const Tag = ({ children }) => (
  <span className="inline-flex items-center text-[10px] font-semibold uppercase tracking-wider px-2 py-0.5 rounded bg-white text-[#5b21b6]">{children}</span>
);

// v160.3.5b — Per-row file-presence chip. Renders one of three states:
//   • Cell has a `doc_file_id` → clickable "📄 File" (green) that opens the
//     GridFS blob via the shared download-token flow (`filesUrl`).
//   • Cell exists (cert_id set) but has NO doc_file_id → "⚠ No file"
//     (orange) — a real induction record with metadata only.
//   • Cell doesn't exist yet (empty slot) → renders nothing.
function FilePresenceChip({ workerId, cell }) {
  if (!cell || !cell.cert_id) return null;
  if (!cell.doc_file_id) {
    return (
      <span
        className="inline-flex items-center gap-1 text-[10px] font-semibold px-1.5 py-0.5 rounded bg-orange-50 text-orange-700 border border-orange-200"
        title="No file attached"
        data-testid={`induction-file-missing-${cell.cert_id}`}
      >
        <AlertTriangle size={9} /> No file
      </span>
    );
  }
  return (
    <button
      type="button"
      onClick={async (e) => {
        e.stopPropagation();
        try {
          const u = await filesUrl(`/workers/${workerId}/certifications/${cell.cert_id}/file`);
          window.open(u, '_blank', 'noopener,noreferrer');
        } catch (_err) { toast.error('Unable to open file'); }
      }}
      className="inline-flex items-center gap-1 text-[10px] font-semibold px-1.5 py-0.5 rounded bg-emerald-50 text-emerald-800 border border-emerald-200 hover:bg-emerald-100"
      title="Open attached file"
      data-testid={`induction-file-open-${cell.cert_id}`}
    >
      <FileText size={9} /> File
    </button>
  );
}

// Phase 4.7 — AccessSection: invite / PIN / reset / unlock controls for a user.
import React, { useEffect, useState } from 'react';
import { toast } from 'sonner';
import api, { apiError } from '@/lib/api';
import { PinRevealModal, ChannelPickerDialog } from '@/components/auth/AuthBundle';

const STATE_PILL = {
  active:          { label: 'Active',           cls: 'bg-emerald-50 text-emerald-700' },
  invite_pending:  { label: 'Invite pending',   cls: 'bg-orange-50 text-orange-700' },
  never_logged_in: { label: 'Never logged in',  cls: 'bg-slate-100 text-slate-600' },
  locked:          { label: 'Locked',           cls: 'bg-rose-50 text-rose-700' },
};

export default function AccessSection({ userId, compact = false }) {
  const [status, setStatus] = useState(null);
  const [picker, setPicker] = useState(null); // null | { kind: 'invite'|'reset' }
  const [busy, setBusy] = useState(false);
  const [pin, setPin] = useState(null);

  const refresh = async () => {
    try { const { data } = await api.get(`/users/${userId}/access-status`); setStatus(data); }
    catch (e) { toast.error(apiError(e)); }
  };
  useEffect(() => { refresh(); /* eslint-disable-next-line */ }, [userId]);

  const fireChannelAction = async (path, label, channel) => {
    setBusy(true);
    try {
      const { data } = await api.post(path, { channel });
      toast.success(`${label} sent via ${data?.channel || channel}`);
      setPicker(null);
      refresh();
    } catch (e) { toast.error(apiError(e)); }
    finally { setBusy(false); }
  };

  // v160.3.9.32-4c.1 — sendInvite removed. Admin uses sendReset (magic
  // link) or the direct Set-password dialog in the drawer instead.
  const sendReset  = (channel) => fireChannelAction(`/users/${userId}/reset-password`, 'Reset link', channel);
  const unlock = async () => {
    setBusy(true);
    try { await api.post(`/users/${userId}/unlock`); toast.success('Account unlocked'); refresh(); }
    catch (e) { toast.error(apiError(e)); } finally { setBusy(false); }
  };
  const genPin = async () => {
    setBusy(true);
    try {
      const { data } = await api.post(`/users/${userId}/pin`);
      setPin(data.pin); refresh();
    } catch (e) { toast.error(apiError(e)); }
    finally { setBusy(false); }
  };

  if (!status) return <div className="text-xs text-slate-500" data-testid="access-loading">Loading access…</div>;

  const pill = STATE_PILL[status.state] || STATE_PILL.active;
  const expiresIn = status.invite_expires_at
    ? Math.max(0, Math.floor((new Date(status.invite_expires_at) - new Date()) / 86400000))
    : null;
  const lastLogin = status.last_login_at
    ? Math.floor((new Date() - new Date(status.last_login_at)) / 86400000) : null;
  const subline = status.state === 'invite_pending' && expiresIn != null
    ? `expires in ${expiresIn} day${expiresIn === 1 ? '' : 's'}`
    : status.state === 'active' && lastLogin != null
    ? `last login ${lastLogin}d ago`
    : status.state === 'locked' ? 'too many failed attempts' : '';

  return (
    <section className={compact ? '' : 'rounded-2xl border border-slate-200 bg-white p-5'} data-testid="access-section">
      {!compact && <h3 className="font-display text-lg font-semibold text-slate-900 mb-2">Access</h3>}
      <div className="flex items-center gap-2 mb-3">
        <span data-testid="access-pill"
          className={`inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-semibold ${pill.cls}`}>
          {pill.label}
        </span>
        {subline && <span className="text-xs text-slate-500">· {subline}</span>}
      </div>
      <div className="flex flex-wrap gap-2">
        {/* v160.3.9.32-4c.1 — "Send invite…" button removed. Backend
            invite endpoint returns 410; admin uses Reset password or
            the direct Set-password dialog from the drawer instead. */}
        <button onClick={genPin} disabled={busy} data-testid="access-pin"
          className="px-3 py-1.5 rounded-lg border border-slate-300 hover:bg-slate-50 text-xs font-semibold text-slate-700 disabled:opacity-60">
          Generate one-time PIN
        </button>
        <button onClick={() => setPicker({ kind: 'reset' })} disabled={busy} data-testid="access-reset"
          className="px-3 py-1.5 rounded-lg border border-slate-300 hover:bg-slate-50 text-xs font-semibold text-slate-700 disabled:opacity-60">
          Reset password…
        </button>
        {status.state === 'locked' && (
          <button onClick={unlock} disabled={busy} data-testid="access-unlock"
            className="px-3 py-1.5 rounded-lg bg-rose-600 hover:bg-rose-700 text-white text-xs font-semibold disabled:opacity-60">
            Unlock account
          </button>
        )}
      </div>
      <ChannelPickerDialog
        open={picker?.kind === 'reset'} onClose={() => setPicker(null)}
        title="Send reset link"
        description="The worker will receive a link to choose a new password."
        onConfirm={sendReset} busy={busy}
      />
      <PinRevealModal pin={pin} open={!!pin} onClose={() => setPin(null)} />
    </section>
  );
}

// AssetScanField — Phase 2 of the Plant & Vehicles backbone.
// Three input modes (segmented control):
//   • QR Camera  (uses BarcodeDetector or jsqr fallback on a hidden <video>)
//   • NFC Tap    (Android Chrome only — NDEFReader.scan())
//   • Manual Pick (debounced search hitting /api/forms/assets/picker)
// On resolve, we call /api/forms/assets/lookup and surface a confirmation card
// before committing back to the FieldRunner. Autofill of dependent fields is
// done by the FieldRunner wrapper (not here) so the engine stays declarative.
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  Camera, ScanLine, Smartphone, Search, Loader2, AlertTriangle, Check, X,
  RefreshCw, Truck, Wrench,
} from 'lucide-react';
import { toast } from 'sonner';
import jsQR from 'jsqr';
import api, { apiError } from '../../lib/api';

const PUBLIC_PATH_RE = /\/scan\/([A-Za-z0-9_-]{6,32})$/;

function parseScanToken(payload) {
  if (!payload) return null;
  const trimmed = String(payload).trim();
  // Accept a raw token or a full /scan/{token} URL.
  if (/^[A-Za-z0-9_-]{6,32}$/.test(trimmed)) return trimmed;
  try {
    const u = new URL(trimmed);
    const m = u.pathname.match(PUBLIC_PATH_RE);
    if (m) return m[1];
  } catch { /* not a URL */ }
  const m = trimmed.match(PUBLIC_PATH_RE);
  return m ? m[1] : null;
}

export default function AssetScanField({ field, value, onChange, readOnly }) {
  const cfg = field?.config || {};
  const requireScan = !!cfg.requireScan;
  const kindFilter = cfg.kindFilter || 'any';
  // Capability detection.
  const hasNfc = typeof window !== 'undefined' && 'NDEFReader' in window;
  const hasCamera = typeof navigator !== 'undefined' && !!navigator.mediaDevices?.getUserMedia;
  const hasBarcode = typeof window !== 'undefined' && 'BarcodeDetector' in window;

  // Default to camera if available, else manual.
  const defaultMode = hasCamera ? 'qr' : (hasNfc ? 'nfc' : 'manual');
  const [mode, setMode] = useState(defaultMode);
  const [pending, setPending] = useState(null);     // payload before confirm
  const [resolved, setResolved] = useState(null);   // looked-up asset
  const [resolving, setResolving] = useState(false);
  const [err, setErr] = useState('');

  // ── Persist resolved value when committed ──
  const commit = useCallback((asset, resolved_via) => {
    onChange({
      asset_id: asset.id,
      scan_token: asset.scan_token,
      name: asset.name,
      rego_serial: asset.rego_serial,
      asset_type: asset.asset_type,
      vehicle_type_slug: asset.vehicle_type_slug,
      kind: asset.kind,
      last_known_lat: asset.last_known_lat,
      last_known_lng: asset.last_known_lng,
      resolved_via,
      resolved_at: new Date().toISOString(),
    });
    setResolved(null); setPending(null); setErr('');
  }, [onChange]);

  const lookup = useCallback(async (token, resolved_via) => {
    if (!token) return;
    setResolving(true); setErr('');
    try {
      const { data } = await api.get('/forms/assets/lookup', { params: { token } });
      // We're about to surface a confirmation card. Keep `resolved_via` in
      // local state so the Use button knows it.
      setResolved({ ...data, _resolved_via: resolved_via });
    } catch (e) {
      const code = e?.response?.status;
      setErr(code === 410 ? 'That asset has been retired.' : code === 404 ? 'Unknown scan code. Try again or pick manually.' : apiError(e));
    } finally { setResolving(false); }
  }, []);

  // ── Read-only / already-filled view ──
  if (value?.asset_id && !pending && !resolving) {
    return <ResolvedCard field={field} value={value} readOnly={readOnly} onClear={() => onChange(null)} />;
  }

  return (
    <div className="space-y-2.5" data-testid={`field-${field.id}`}>
      {/* segmented control */}
      <div className="inline-flex rounded-xl border border-slate-200 bg-slate-50 p-0.5 text-xs">
        {hasCamera && (
          <button type="button" onClick={() => setMode('qr')}
            className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg font-semibold ${mode === 'qr' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500'}`}
            data-testid={`scan-mode-qr-${field.id}`}>
            <ScanLine size={12} /> QR Camera
          </button>
        )}
        {hasNfc && (
          <button type="button" onClick={() => setMode('nfc')}
            className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg font-semibold ${mode === 'nfc' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500'}`}
            data-testid={`scan-mode-nfc-${field.id}`}>
            <Smartphone size={12} /> NFC Tap
          </button>
        )}
        {!requireScan && (
          <button type="button" onClick={() => setMode('manual')}
            className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg font-semibold ${mode === 'manual' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500'}`}
            data-testid={`scan-mode-manual-${field.id}`}>
            <Search size={12} /> Manual pick
          </button>
        )}
      </div>
      {!hasNfc && !requireScan && (
        <div className="text-[10px] text-slate-400">NFC tap is unavailable in this browser/device — use the QR camera or manual picker instead.</div>
      )}

      {mode === 'qr' && hasCamera && (
        <QrCameraScanner fieldId={field.id} hasBarcode={hasBarcode}
          onPayload={(p) => { setPending(p); const tok = parseScanToken(p); if (tok) lookup(tok, 'qr'); }} />
      )}
      {mode === 'nfc' && hasNfc && (
        <NfcTapScanner fieldId={field.id}
          onPayload={(p) => { setPending(p); const tok = parseScanToken(p); if (tok) lookup(tok, 'nfc'); }} />
      )}
      {mode === 'manual' && !requireScan && (
        <ManualPicker fieldId={field.id} kindFilter={kindFilter}
          onPicked={(asset) => lookup(asset.scan_token, 'manual')} />
      )}

      {resolving && (
        <div className="text-xs text-slate-500 inline-flex items-center gap-1" data-testid={`scan-resolving-${field.id}`}>
          <Loader2 size={12} className="animate-spin" /> Resolving asset…
        </div>
      )}
      {err && (
        <div className="px-3 py-2 rounded-lg bg-rose-50 border border-rose-200 text-xs text-rose-700 inline-flex items-center gap-1.5" data-testid={`scan-error-${field.id}`}>
          <AlertTriangle size={12} /> {err}
        </div>
      )}
      {resolved && (
        <ConfirmCard fieldId={field.id} asset={resolved}
          onUse={() => commit(resolved, resolved._resolved_via)}
          onAgain={() => { setResolved(null); setPending(null); setErr(''); }} />
      )}
    </div>
  );
}

// ─────────────── confirmation card ───────────────

function ConfirmCard({ fieldId, asset, onUse, onAgain }) {
  return (
    <div className="px-3 py-3 rounded-2xl bg-emerald-50 border-2 border-emerald-300" data-testid={`scan-confirm-${fieldId}`}>
      <div className="flex items-start gap-3">
        <div className="w-10 h-10 rounded-xl bg-white flex items-center justify-center shrink-0">
          {asset.kind === 'vehicle' ? <Truck size={18} className="text-emerald-700" /> : <Wrench size={18} className="text-emerald-700" />}
        </div>
        <div className="flex-1 min-w-0">
          <div className="text-[10px] uppercase tracking-wider font-semibold text-emerald-700">
            Resolved · {(asset.kind || '').toUpperCase()} · {(asset.asset_type || '').replace(/_/g, ' ').toUpperCase()}
          </div>
          <div className="font-semibold text-slate-900 truncate">{asset.name}</div>
          {asset.rego_serial && <div className="mt-0.5 inline-block px-2 py-0.5 rounded-md bg-white text-sm font-mono font-bold text-slate-900">{asset.rego_serial}</div>}
        </div>
      </div>
      <div className="mt-3 flex gap-2">
        <button type="button" onClick={onUse}
          className="flex-1 inline-flex items-center justify-center gap-1.5 px-3 py-2 rounded-lg bg-emerald-600 text-white text-sm font-semibold hover:bg-emerald-700"
          data-testid={`scan-use-${fieldId}`}>
          <Check size={14} /> Use this
        </button>
        <button type="button" onClick={onAgain}
          className="inline-flex items-center justify-center gap-1.5 px-3 py-2 rounded-lg border border-slate-300 bg-white text-sm font-semibold text-slate-700 hover:bg-slate-50"
          data-testid={`scan-again-${fieldId}`}>
          <RefreshCw size={14} /> Scan again
        </button>
      </div>
    </div>
  );
}

// ─────────────── locked / resolved view ───────────────

function ResolvedCard({ field, value, onClear, readOnly }) {
  return (
    <div className="px-3 py-2.5 rounded-xl bg-blue-50 border-2 border-blue-200 inline-flex items-center gap-2.5 max-w-full" data-testid={`field-${field.id}`}>
      {value.kind === 'vehicle' ? <Truck size={16} className="text-blue-700 shrink-0" /> : <Wrench size={16} className="text-blue-700 shrink-0" />}
      <div className="min-w-0">
        <div className="font-semibold text-slate-900 truncate">{value.name}</div>
        <div className="text-[11px] text-slate-500">
          <span className="font-mono font-semibold text-slate-800">{value.rego_serial || '—'}</span>
          <span className="ml-2 uppercase tracking-wider">{(value.asset_type || '').replace(/_/g, ' ')}</span>
          {value.resolved_via && <span className="ml-2 text-slate-400">via {value.resolved_via}</span>}
        </div>
      </div>
      {!readOnly && (
        <button type="button" onClick={onClear}
          className="ml-2 p-1.5 rounded-lg hover:bg-blue-100 text-slate-600"
          data-testid={`scan-clear-${field.id}`} title="Clear / scan again">
          <X size={14} />
        </button>
      )}
    </div>
  );
}

// ─────────────── QR camera scanner ───────────────

function QrCameraScanner({ fieldId, hasBarcode, onPayload }) {
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const rafRef = useRef(0);
  const streamRef = useRef(null);
  const detectorRef = useRef(null);
  const [running, setRunning] = useState(false);
  const [perm, setPerm] = useState('idle');

  const stop = useCallback(() => {
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    rafRef.current = 0;
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
      streamRef.current = null;
    }
    setRunning(false);
  }, []);

  const start = useCallback(async () => {
    setPerm('asking');
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: false,
        video: { facingMode: { ideal: 'environment' }, width: { ideal: 1280 } },
      });
      streamRef.current = stream;
      const v = videoRef.current;
      if (!v) return;
      v.srcObject = stream;
      await v.play();
      setRunning(true); setPerm('granted');
      if (hasBarcode && !detectorRef.current) {
        // eslint-disable-next-line no-undef
        detectorRef.current = new BarcodeDetector({ formats: ['qr_code'] });
      }
      const tick = async () => {
        if (!streamRef.current) return;
        if (v.readyState >= 2) {
          let payload = null;
          try {
            if (detectorRef.current) {
              const r = await detectorRef.current.detect(v);
              if (r && r[0]?.rawValue) payload = r[0].rawValue;
            } else {
              // jsqr fallback
              const canvas = canvasRef.current;
              const w = v.videoWidth, h = v.videoHeight;
              if (canvas && w && h) {
                canvas.width = w; canvas.height = h;
                const ctx = canvas.getContext('2d', { willReadFrequently: true });
                ctx.drawImage(v, 0, 0, w, h);
                const data = ctx.getImageData(0, 0, w, h);
                const r = jsQR(data.data, w, h, { inversionAttempts: 'attemptBoth' });
                if (r?.data) payload = r.data;
              }
            }
          } catch { /* keep scanning */ }
          if (payload) {
            stop();
            onPayload(payload);
            return;
          }
        }
        rafRef.current = requestAnimationFrame(tick);
      };
      rafRef.current = requestAnimationFrame(tick);
    } catch (e) {
      setPerm('denied');
      toast.error(`Camera unavailable: ${e?.message || e}`);
    }
  }, [hasBarcode, onPayload, stop]);

  useEffect(() => () => stop(), [stop]);

  return (
    <div className="rounded-2xl border border-slate-200 bg-slate-50 p-3" data-testid={`scan-qr-${fieldId}`}>
      <div className="relative aspect-video rounded-xl overflow-hidden bg-slate-900 flex items-center justify-center">
        <video ref={videoRef} muted playsInline className={`w-full h-full object-cover ${running ? '' : 'opacity-40'}`} />
        <canvas ref={canvasRef} className="hidden" />
        {!running && (
          <button type="button" onClick={start}
            className="absolute inline-flex items-center gap-2 px-4 py-2.5 rounded-xl bg-white/95 text-slate-900 text-sm font-bold shadow-lg"
            data-testid={`scan-start-${fieldId}`}>
            <Camera size={14} /> Start camera
          </button>
        )}
        {running && (
          <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
            <div className="w-48 h-48 border-2 border-emerald-300 rounded-2xl shadow-[0_0_0_9999px_rgba(15,23,42,0.45)]" />
          </div>
        )}
      </div>
      <div className="mt-2 flex items-center justify-between gap-2 text-[11px] text-slate-500">
        <span>{running ? 'Point at the QR label on the asset' : perm === 'denied' ? 'Camera permission was denied.' : 'Click Start camera to begin scanning'}</span>
        {running && (
          <button type="button" onClick={stop}
            className="px-2 py-1 rounded-md border border-slate-300 bg-white text-xs font-semibold text-slate-700 hover:bg-slate-50"
            data-testid={`scan-stop-${fieldId}`}>Stop</button>
        )}
      </div>
    </div>
  );
}

// ─────────────── NFC tap scanner ───────────────

function NfcTapScanner({ fieldId, onPayload }) {
  const [scanning, setScanning] = useState(false);
  const ctrlRef = useRef(null);
  const stop = useCallback(() => {
    try { ctrlRef.current?.abort(); } catch { /* ignore */ }
    ctrlRef.current = null;
    setScanning(false);
  }, []);
  const start = useCallback(async () => {
    setScanning(true);
    try {
      // eslint-disable-next-line no-undef
      const reader = new NDEFReader();
      const ctrl = new AbortController();
      ctrlRef.current = ctrl;
      await reader.scan({ signal: ctrl.signal });
      reader.onreading = (event) => {
        for (const rec of event.message.records || []) {
          if (rec.recordType === 'url') {
            const dec = new TextDecoder();
            const text = dec.decode(rec.data);
            stop();
            onPayload(text);
            return;
          }
        }
      };
    } catch (e) {
      toast.error(`NFC error: ${e?.message || e}`);
      stop();
    }
  }, [onPayload, stop]);

  useEffect(() => () => stop(), [stop]);

  return (
    <div className="rounded-2xl border border-violet-200 bg-violet-50 p-4 text-center" data-testid={`scan-nfc-${fieldId}`}>
      <div className={`mx-auto w-14 h-14 rounded-full bg-white flex items-center justify-center ${scanning ? 'animate-pulse' : ''}`}>
        <Smartphone size={22} className="text-violet-700" />
      </div>
      <div className="mt-2 text-sm font-semibold text-violet-900">{scanning ? 'Tap the NFC tag against your phone…' : 'Press start, then tap the tag'}</div>
      <div className="mt-2 flex justify-center gap-2">
        {!scanning ? (
          <button type="button" onClick={start}
            className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg bg-violet-600 text-white text-sm font-semibold"
            data-testid={`scan-nfc-start-${fieldId}`}>
            <Smartphone size={14} /> Start NFC
          </button>
        ) : (
          <button type="button" onClick={stop}
            className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg border border-slate-300 bg-white text-sm font-semibold text-slate-700"
            data-testid={`scan-nfc-stop-${fieldId}`}>Stop</button>
        )}
      </div>
    </div>
  );
}

// ─────────────── manual picker ───────────────

function ManualPicker({ fieldId, kindFilter, onPicked }) {
  const [q, setQ] = useState('');
  const [rows, setRows] = useState([]);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    let alive = true;
    const t = setTimeout(async () => {
      setBusy(true);
      try {
        const { data } = await api.get('/forms/assets/picker', {
          params: { q: q || undefined, kind: kindFilter === 'any' ? undefined : kindFilter, limit: 50 },
        });
        if (alive) setRows(data.assets || []);
      } catch (e) {
        if (alive) toast.error(apiError(e));
      } finally { if (alive) setBusy(false); }
    }, q ? 250 : 0);
    return () => { alive = false; clearTimeout(t); };
  }, [q, kindFilter]);

  return (
    <div className="rounded-2xl border border-slate-200 bg-white" data-testid={`scan-manual-${fieldId}`}>
      <div className="px-3 py-2 border-b border-slate-100 flex items-center gap-2">
        <Search size={13} className="text-slate-400" />
        <input value={q} onChange={(e) => setQ(e.target.value)}
          placeholder="Search by name, rego, serial…"
          className="flex-1 text-sm bg-transparent outline-none"
          data-testid={`scan-manual-search-${fieldId}`} />
        {busy && <Loader2 size={12} className="animate-spin text-slate-400" />}
      </div>
      <div className="max-h-60 overflow-y-auto divide-y divide-slate-100">
        {rows.length === 0 ? (
          <div className="px-3 py-4 text-center text-xs text-slate-500 italic">{busy ? 'Searching…' : 'No assets match.'}</div>
        ) : rows.map((a) => (
          <button key={a.id} type="button"
            onClick={() => onPicked(a)}
            data-testid={`scan-manual-opt-${a.id}`}
            className="w-full px-3 py-2.5 text-left hover:bg-blue-50 flex items-center gap-2">
            {a.kind === 'vehicle' ? <Truck size={13} className="text-slate-400" /> : <Wrench size={13} className="text-slate-400" />}
            <span className="font-semibold text-sm text-slate-900 truncate">{a.name}</span>
            {a.rego_serial && <span className="ml-auto text-xs font-mono font-semibold text-slate-700">{a.rego_serial}</span>}
          </button>
        ))}
      </div>
    </div>
  );
}

// ─────────────── helper for dependent autofill ───────────────

/**
 * Given a template's field list and the asset payload returned by the
 * lookup endpoint, return a values map (keyed by field.id) of dependent
 * fields that should be auto-filled. The FieldRunner wrapper applies
 * this on top of the current values map.
 */
export function buildAutofillFromAsset(allFields, asset, options = {}) {
  if (!asset || !Array.isArray(allFields)) return {};
  const targets = options.autofillTargets;
  const wants = (label, types = []) => {
    const target = allFields.find((f) => {
      const lbl = (f.label || '').toLowerCase();
      const lblHits = label.some((kw) => lbl.includes(kw));
      const typeHits = types.length === 0 || types.includes(f.type);
      const targetSelected = !targets || targets.length === 0 || targets.includes(f.id);
      return lblHits && typeHits && targetSelected;
    });
    return target || null;
  };
  const out = {};
  // vehicle_type select
  const vt = wants(['vehicle type', 'plant type', 'equipment type'], ['select']);
  if (vt && asset.vehicle_type_slug) {
    const v = asset.vehicle_type_slug;
    // Try to find a matching option case-insensitively.
    const opts = (vt.options || []).map((o) => o);
    const found = opts.find((o) => o && o.toLowerCase().replace(/[\s_-]+/g, '') === v.replace(/[_]/g, ''));
    if (found) out[vt.id] = found;
  }
  // rego / vehicle rego text field
  const rego = wants(['vehicle rego', 'rego', 'serial'], ['text', 'vehicle_navixy']);
  if (rego && asset.rego_serial) {
    if (rego.type === 'vehicle_navixy') {
      out[rego.id] = {
        navixy_id: asset.navixy_device_id || null,
        label: asset.name, registration: asset.rego_serial,
      };
    } else {
      out[rego.id] = asset.rego_serial;
    }
  }
  // GPS
  const gps = allFields.find((f) => f.type === 'gps');
  if (gps && asset.last_known_lat != null && asset.last_known_lng != null) {
    out[gps.id] = { lat: asset.last_known_lat, lng: asset.last_known_lng, at: new Date().toISOString() };
  }
  // Odometer / hours
  const odo = wants(['odometer', 'odo', 'kilometres'], ['number']);
  if (odo && asset.odo_km != null) out[odo.id] = String(asset.odo_km);
  const hrs = wants(['hours', 'hour meter'], ['number']);
  if (hrs && asset.hours_meter != null) out[hrs.id] = String(asset.hours_meter);
  return out;
}

// Phase 3.18 — Active Sessions panel inside the Session Timeout card.
// v160.3.0-adjust-5 — Swapped "Revoke" icon to red Trash2, wrapped in AlertDialog.
// v160.3.6v — Added the v6d selection pattern: master checkbox on the header row,
// per-row checkboxes, a floating "N selected · 🗑 Delete selected" action bar and
// a confirm modal that calls POST /admin/active-sessions/bulk-revoke.
//
// The user's own current session is:
//   • rendered with the "You" pill
//   • not selectable via the master checkbox (excluded from "select all visible")
//   • its per-row checkbox is disabled
//   • server-side ALSO filters it out defensively, so even if a stale UI selection
//     reaches the endpoint the caller can never nuke themselves.

import { useEffect, useState } from 'react';
import { Trash2, RefreshCw, Loader2, Users, Timer } from 'lucide-react';
import { toast } from 'sonner';
import api, { apiError } from '../../lib/api';
import { RUNNING_VERSION } from '../../lib/version';
import {
  AlertDialog, AlertDialogContent, AlertDialogHeader,
  AlertDialogTitle, AlertDialogDescription, AlertDialogFooter,
  AlertDialogCancel, AlertDialogAction,
} from '../ui/alert-dialog';

const ROLE_BADGE = {
  admin:      'bg-violet-100 text-violet-700',
  hseq_lead:  'bg-blue-100 text-blue-700',
  manager:    'bg-blue-100 text-blue-700',
  supervisor: 'bg-emerald-100 text-emerald-700',
  worker:     'bg-amber-100 text-amber-700',
  auditor:    'bg-slate-200 text-slate-700',
};

function relTime(iso) {
  if (!iso) return '—';
  const ms = Date.now() - new Date(iso).getTime();
  if (Number.isNaN(ms)) return '—';
  if (ms < 0) return 'just now';
  const s = Math.floor(ms / 1000);
  if (s < 60)        return `${s}s ago`;
  if (s < 3600)      return `${Math.floor(s / 60)}m ago`;
  if (s < 86400)     return `${Math.floor(s / 3600)}h ago`;
  return `${Math.floor(s / 86400)}d ago`;
}

export default function ActiveSessionsPanel() {
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [busyJti, setBusyJti] = useState(null);
  const [confirmRow, setConfirmRow] = useState(null);
  const [nowTick, setNowTick] = useState(0);

  // v160.3.6v — selection state
  const [selected, setSelected] = useState(() => new Set());
  const [bulkConfirmOpen, setBulkConfirmOpen] = useState(false);
  const [bulkBusy, setBulkBusy] = useState(false);

  // v160.3.7e — "Purge inactive > 24h" state
  const [purgeConfirmOpen, setPurgeConfirmOpen] = useState(false);
  const [purgePreview, setPurgePreview] = useState(null);   // { would_purge, cutoff }
  const [purgeBusy, setPurgeBusy] = useState(false);

  const load = async () => {
    try {
      const { data } = await api.get('/admin/active-sessions');
      const next = data.sessions || [];
      setRows(next);
      // v160.3.6v — prune any selected jtis that no longer exist
      const visibleJtis = new Set(next.map((r) => r.jti));
      setSelected((prev) => {
        const kept = new Set();
        prev.forEach((jti) => { if (visibleJtis.has(jti)) kept.add(jti); });
        return kept.size === prev.size ? prev : kept;
      });
    } catch (e) {
      toast.error(apiError(e));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
    const refresh = setInterval(load, 30000);
    const tick = setInterval(() => setNowTick((n) => n + 1), 15000);
    return () => { clearInterval(refresh); clearInterval(tick); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  void nowTick;

  const doRevoke = async (row) => {
    setBusyJti(row.jti);
    try {
      await api.delete(`/admin/active-sessions/${row.jti}`);
      toast.success(`${row.user_name}'s session deleted.`);
      setRows((rs) => rs.filter((r) => r.jti !== row.jti));
      setSelected((prev) => {
        if (!prev.has(row.jti)) return prev;
        const next = new Set(prev);
        next.delete(row.jti);
        return next;
      });
    } catch (e) {
      toast.error(apiError(e));
    } finally {
      setBusyJti(null);
      setConfirmRow(null);
    }
  };

  // v160.3.6v — selection helpers (mirrors the Outbox v6d pattern)
  const selectableRows = rows.filter((r) => !r.is_current_session);
  const selectableJtis = selectableRows.map((r) => r.jti);
  const allSelected = selectableJtis.length > 0 && selectableJtis.every((jti) => selected.has(jti));
  const someSelected = !allSelected && selectableJtis.some((jti) => selected.has(jti));

  const toggleRow = (jti) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(jti)) next.delete(jti); else next.add(jti);
      return next;
    });
  };
  const toggleAll = () => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (selectableJtis.every((jti) => next.has(jti))) {
        selectableJtis.forEach((jti) => next.delete(jti));
      } else {
        selectableJtis.forEach((jti) => next.add(jti));
      }
      return next;
    });
  };
  const clearSelection = () => setSelected(new Set());

  const doBulkRevoke = async () => {
    if (selected.size === 0) return;
    const ids = Array.from(selected);
    setBulkBusy(true);
    try {
      const { data } = await api.post('/admin/active-sessions/bulk-revoke', { ids });
      const revoked = data?.revoked || 0;
      const notFound = data?.not_found?.length || 0;
      let msg = `${revoked} session${revoked === 1 ? '' : 's'} deleted`;
      if (notFound > 0) msg += ` · ${notFound} already gone`;
      if (data?.skipped_self) msg += ' · your own session was skipped';
      toast.success(msg);
      setBulkConfirmOpen(false);
      clearSelection();
      await load();
    } catch (e) {
      toast.error(apiError(e) || 'Bulk delete failed');
    } finally {
      setBulkBusy(false);
    }
  };

  const selfInSelection = rows.some(
    (r) => r.is_current_session && selected.has(r.jti),
  );

  // v160.3.7e — Purge inactive > 24h. Opens confirm with a preview count.
  const openPurge = async () => {
    setPurgeConfirmOpen(true);
    setPurgePreview(null);
    try {
      const { data } = await api.get('/admin/active-sessions/purge-inactive/preview?older_than_hours=24');
      setPurgePreview(data);
    } catch (e) {
      toast.error(apiError(e) || 'Preview failed');
    }
  };
  const doPurge = async () => {
    setPurgeBusy(true);
    try {
      const { data } = await api.post('/admin/active-sessions/purge-inactive', { older_than_hours: 24 });
      toast.success(`${data?.purged || 0} inactive session${data?.purged === 1 ? '' : 's'} purged.`);
      setPurgeConfirmOpen(false);
      setPurgePreview(null);
      clearSelection();
      await load();
    } catch (e) {
      toast.error(apiError(e) || 'Purge failed');
    } finally {
      setPurgeBusy(false);
    }
  };

  return (
    <div className="mt-5 rounded-xl border border-slate-200 bg-white" data-testid="active-sessions-panel">
      <div className="flex items-center justify-between px-3.5 py-3 border-b border-slate-200 bg-slate-50/60">
        <div className="flex items-center gap-2 min-w-0">
          {/* v160.3.6v — master checkbox lives in the header, next to the title */}
          <input
            type="checkbox"
            checked={allSelected}
            ref={(el) => { if (el) el.indeterminate = someSelected; }}
            onChange={toggleAll}
            disabled={selectableJtis.length === 0}
            aria-label={allSelected ? 'Deselect all visible sessions' : 'Select all revocable sessions'}
            data-testid="active-sessions-select-all"
            className="w-3.5 h-3.5 mr-1 cursor-pointer disabled:opacity-40"
          />
          <div className="rounded-lg bg-violet-100 p-1.5 text-violet-700"><Users size={14} /></div>
          <div>
            <div className="text-sm font-bold text-slate-900">Active sessions</div>
            <div className="text-[11px] text-slate-500">
              {loading ? 'Loading…' : `${rows.length} live session${rows.length === 1 ? '' : 's'} · auto-refreshes every 30s`}
              {' · '}
              {/* v160.3.7f — Visible bundle-version chip so a stale-cache
                  browser is obvious. If a user reports a bug and this chip
                  shows an older version than the backend, they need a hard
                  refresh before we chase server bugs. */}
              <span
                data-testid="active-sessions-bundle-version"
                title="Frontend bundle version — hard-refresh if this is behind the backend"
                className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded bg-slate-100 text-slate-600 font-mono text-[10px]">
                {RUNNING_VERSION}
              </span>
            </div>
          </div>
        </div>
        <button
          type="button" onClick={() => { setLoading(true); load(); }}
          disabled={loading}
          data-testid="active-sessions-refresh"
          className="inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg border border-slate-300 bg-white text-[11px] font-semibold text-slate-700 hover:bg-slate-50 disabled:opacity-50">
          {loading ? <Loader2 size={11} className="animate-spin" /> : <RefreshCw size={11} />} Refresh
        </button>
        {/* v160.3.7e — Purge inactive > 24h. Safe for anyone active. */}
        <button
          type="button"
          onClick={openPurge}
          disabled={loading || purgeBusy}
          title="Deletes all sessions with no activity in the last 24 hours — safe for anyone actively signed in"
          data-testid="active-sessions-purge-inactive-btn"
          className="ml-1.5 inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg border border-slate-300 bg-white text-[11px] font-semibold text-slate-700 hover:bg-slate-50 disabled:opacity-50">
          <Timer size={11} /> Purge inactive &gt; 24h
        </button>
      </div>

      {loading && rows.length === 0 ? (
        <div className="px-3.5 py-6 text-center text-xs text-slate-500" data-testid="active-sessions-loading">
          <Loader2 size={14} className="animate-spin inline mr-1.5" /> Loading sessions…
        </div>
      ) : rows.length === 0 ? (
        <div className="px-3.5 py-6 text-center text-xs text-slate-500" data-testid="active-sessions-empty">
          No active sessions found. (Workers signed in via Simpro Login also land here.)
        </div>
      ) : (
        <ul className="divide-y divide-slate-100">
          {rows.map((r) => {
            const isSelected = selected.has(r.jti);
            return (
              <li key={r.jti}
                  className={`px-3.5 py-2.5 flex items-center gap-3 ${isSelected ? 'bg-[#e6eff9]/40' : ''}`}
                  data-testid={`session-row-${r.jti}`}>
                {/* v160.3.6v — per-row checkbox */}
                <input
                  type="checkbox"
                  checked={isSelected}
                  onChange={() => toggleRow(r.jti)}
                  disabled={r.is_current_session}
                  aria-label={r.is_current_session
                    ? 'Your current session — cannot be selected for delete'
                    : `Select ${r.user_name}'s session`}
                  data-testid={`session-select-${r.jti}`}
                  onClick={(e) => e.stopPropagation()}
                  className="w-3.5 h-3.5 cursor-pointer disabled:opacity-40 disabled:cursor-not-allowed"
                />
                <div className="flex-1 min-w-0">
                  <div className="text-sm font-semibold text-slate-900 truncate inline-flex items-center gap-1.5">
                    {r.user_name}
                    {r.is_current_session && (
                      <span className="text-[9px] uppercase tracking-wider font-bold bg-emerald-100 text-emerald-700 px-1.5 py-0.5 rounded">You</span>
                    )}
                    {r.remember_me && (
                      <span className="text-[9px] uppercase tracking-wider font-bold bg-amber-100 text-amber-700 px-1.5 py-0.5 rounded" title="Remember me enabled (30 day idle)">Remember</span>
                    )}
                  </div>
                  <div className="text-[11px] text-slate-500 truncate">{r.user_email}</div>
                </div>
                <div className="hidden sm:block">
                  <span className={`text-[10px] uppercase tracking-wider font-bold px-2 py-0.5 rounded ${ROLE_BADGE[r.role] || 'bg-slate-100 text-slate-700'}`}>
                    {r.role || 'user'}
                  </span>
                </div>
                <div className="text-[11px] text-slate-500 w-20 text-right" title={r.last_activity_at || ''}>
                  {relTime(r.last_activity_at)}
                </div>
                <button
                  type="button"
                  onClick={() => setConfirmRow(r)}
                  disabled={r.is_current_session || busyJti === r.jti}
                  title={r.is_current_session
                    ? 'This is your current session'
                    : 'Delete this session'}
                  data-testid={`revoke-session-${r.jti}`}
                  aria-label={`Delete ${r.user_name}'s session`}
                  className="inline-flex items-center justify-center w-7 h-7 rounded-lg border border-rose-200 bg-white text-rose-600 hover:bg-rose-500 hover:text-white hover:border-rose-500 transition-colors disabled:opacity-40 disabled:hover:bg-white disabled:hover:text-rose-600 disabled:hover:border-rose-200">
                  {busyJti === r.jti ? <Loader2 size={11} className="animate-spin" /> : <Trash2 size={12} />}
                </button>
              </li>
            );
          })}
        </ul>
      )}

      {/* v160.3.6v — floating selection action bar (Outbox v6d pattern) */}
      {selected.size > 0 && (
        <div
          role="region"
          aria-label="Bulk actions for selected sessions"
          data-testid="active-sessions-selection-bar"
          className="fixed inset-x-0 bottom-6 z-30 flex justify-center px-4 pointer-events-none"
        >
          <div className="pointer-events-auto flex items-center gap-3 rounded-full border border-slate-200 bg-white shadow-xl px-5 py-3">
            <span className="text-sm font-semibold text-slate-900" data-testid="active-sessions-selection-count">
              {selected.size} selected
            </span>
            <span className="text-slate-300">|</span>
            <button
              type="button"
              onClick={clearSelection}
              className="text-xs font-medium text-slate-600 hover:text-slate-900"
              data-testid="active-sessions-selection-clear"
            >
              Clear
            </button>
            <button
              type="button"
              onClick={() => setBulkConfirmOpen(true)}
              data-testid="active-sessions-selection-delete"
              className="inline-flex items-center gap-1.5 rounded-full bg-rose-600 hover:bg-rose-700 text-white text-xs font-semibold uppercase tracking-wider px-4 py-2"
            >
              <Trash2 size={13} /> Delete selected
            </button>
          </div>
        </div>
      )}

      {/* Single-row revoke confirmation (existing) */}
      <AlertDialog open={!!confirmRow} onOpenChange={(open) => !open && setConfirmRow(null)}>
        <AlertDialogContent data-testid="revoke-session-dialog">
          <AlertDialogHeader>
            <AlertDialogTitle>Delete this session?</AlertDialogTitle>
            <AlertDialogDescription>
              {confirmRow && (
                <>
                  <span className="block font-medium text-slate-900 mb-2">
                    {confirmRow.user_name} · {confirmRow.user_email}
                  </span>
                  The user will be logged out immediately on their next request.
                  Any unsaved work in that session will be lost.
                </>
              )}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel
              disabled={!!busyJti}
              data-testid="revoke-session-cancel">Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => confirmRow && doRevoke(confirmRow)}
              disabled={!!busyJti}
              data-testid="revoke-session-confirm"
              className="bg-rose-600 hover:bg-rose-700 focus:ring-rose-600">
              {busyJti ? <Loader2 size={14} className="animate-spin mr-1.5" /> : <Trash2 size={14} className="mr-1.5" />}
              Delete session
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* v160.3.6v — Bulk-revoke confirmation */}
      <AlertDialog open={bulkConfirmOpen} onOpenChange={(o) => { if (!o && !bulkBusy) setBulkConfirmOpen(false); }}>
        <AlertDialogContent data-testid="active-sessions-bulk-dialog">
          <AlertDialogHeader>
            <AlertDialogTitle>
              Delete {selected.size} selected session{selected.size === 1 ? '' : 's'}?
            </AlertDialogTitle>
            <AlertDialogDescription>
              Each selected user will be logged out on their next request. Any
              unsaved work in those sessions will be lost.
              {selfInSelection && (
                <span className="mt-3 block rounded-md border border-amber-300 bg-amber-50 px-3 py-2 text-xs font-semibold text-amber-900" data-testid="active-sessions-bulk-self-warning">
                  Your own current session is in the selection — the server will
                  skip it so you stay signed in.
                </span>
              )}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={bulkBusy} data-testid="active-sessions-bulk-cancel">Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={doBulkRevoke}
              disabled={bulkBusy || selected.size === 0}
              data-testid="active-sessions-bulk-confirm"
              className="bg-rose-600 hover:bg-rose-700 focus:ring-rose-600">
              {bulkBusy ? <Loader2 size={14} className="animate-spin mr-1.5" /> : <Trash2 size={14} className="mr-1.5" />}
              Delete {selected.size}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* v160.3.7e — Purge inactive > 24h confirm */}
      <AlertDialog open={purgeConfirmOpen} onOpenChange={(o) => { if (!o && !purgeBusy) { setPurgeConfirmOpen(false); setPurgePreview(null); } }}>
        <AlertDialogContent data-testid="active-sessions-purge-dialog">
          <AlertDialogHeader>
            <AlertDialogTitle>Purge inactive sessions</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete every session whose last activity is
              older than <strong>24 hours</strong>. Active users won&apos;t be
              affected. Your own session is excluded automatically.
              <span className="mt-3 block rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-xs text-slate-700" data-testid="active-sessions-purge-preview">
                {purgePreview === null ? (
                  <>
                    <Loader2 size={12} className="inline animate-spin mr-1.5" />
                    Calculating impact…
                  </>
                ) : (
                  <>
                    <strong className="tabular-nums">{purgePreview.would_purge}</strong>{' '}
                    session{purgePreview.would_purge === 1 ? '' : 's'} qualify for purge.
                    <span className="block text-[10px] text-slate-500 mt-0.5">
                      Cutoff: {new Date(purgePreview.cutoff).toLocaleString()}
                    </span>
                  </>
                )}
              </span>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={purgeBusy} data-testid="active-sessions-purge-cancel">Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={doPurge}
              disabled={purgeBusy || purgePreview === null || purgePreview.would_purge === 0}
              data-testid="active-sessions-purge-confirm"
              className="bg-rose-600 hover:bg-rose-700 focus:ring-rose-600">
              {purgeBusy ? <Loader2 size={14} className="animate-spin mr-1.5" /> : <Trash2 size={14} className="mr-1.5" />}
              {purgePreview === null ? 'Purge' : `Purge ${purgePreview.would_purge} session${purgePreview.would_purge === 1 ? '' : 's'}`}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

