function deepClone(o) { return JSON.parse(JSON.stringify(o || {})); }
function deepEq(a, b) { return JSON.stringify(a) === JSON.stringify(b); }

// Phase 4.4 — derive the Expo web build URL from REACT_APP_BACKEND_URL.
// Convention in this environment: backend lives at
//   https://<sub>.preview.emergentagent.com
// and the Expo web build lives at
//   https://<sub>.expo.preview.emergentagent.com
// (matches EXPO_PACKAGER_PROXY_URL in /app/mobile/.env). An explicit
// REACT_APP_EXPO_URL override wins if defined.
function computeExpoUrl(role, token) {
  const explicit = process.env.REACT_APP_EXPO_URL;
  const backend = process.env.REACT_APP_BACKEND_URL || '';
  const base = (explicit && explicit.trim())
    || backend.replace(/^(https?:\/\/[^.]+)\./, '$1.expo.');
  if (!base) return '';
  const u = new URL(base);
  u.searchParams.set('preview_role', role);
  if (token) u.searchParams.set('preview_token', token);
  // Cache-bust so the iframe forces a fresh boot on every explicit reload.
  u.searchParams.set('_t', Date.now().toString());
  return u.toString();
}

function PhonePreview({ canEdit }) {
  const [role, setRole] = useState('worker');
  const [src, setSrc] = useState('');
  // v160.3.9.33.3 → v58.4 — live-fetched roles now enriched with
  // `user_count` from the backend so the dropdown can prioritise
  // in-use roles and hide unassigned ones behind a checkbox.
  const [allRoles, setAllRoles] = useState([]);
  const [showUnassigned, setShowUnassigned] = useState(() => {
    try { return localStorage.getItem(LS_PREVIEW_SHOW_UNASSIGNED) === '1'; }
    catch { return false; }
  });
  useEffect(() => {
    try {
      localStorage.setItem(LS_PREVIEW_SHOW_UNASSIGNED, showUnassigned ? '1' : '0');
    } catch { /* noop */ }
  }, [showUnassigned]);
  useEffect(() => {
    api.get('/admin/roles').then(({ data }) => {
      const rs = (data?.roles || []).filter((r) => r.is_active !== false);
      setAllRoles(rs);
    }).catch(() => setAllRoles([]));
  }, []);
  const iframeRef = useRef(null);

  // v58.4 — Group live roles into 3 optgroups sorted by user count.
  //   · inUse   — anyone with users > 0 (the operational set)
  //   · seed    — untouched seeded roles nobody is on yet
  //   · simpro  — auto-created Simpro roles nobody is on yet
  // Admin is force-appended to `inUse` even if user_count is 0 so the
  // operator can always sanity-check the admin view.
  const { inUse, seedGroup, simproGroup } = useMemo(() => {
    const _byCountThenName = (a, b) =>
      (b.user_count || 0) - (a.user_count || 0)
      || (a.name || '').localeCompare(b.name || '');
    const _byName = (a, b) => (a.name || '').localeCompare(b.name || '');
    const inUse = allRoles
      .filter((r) => (r.user_count || 0) > 0 || r.role_id === 'admin')
      .sort(_byCountThenName);
    const seedGroup = allRoles
      .filter((r) => (r.user_count || 0) === 0 && r.role_id !== 'admin'
                     && ((r.source || (r.is_system ? 'seed' : '')) === 'seed'))
      .sort(_byName);
    const simproGroup = allRoles
      .filter((r) => (r.user_count || 0) === 0 && r.role_id !== 'admin'
                     && r.source === 'simpro_position_auto')
      .sort(_byName);
    return { inUse, seedGroup, simproGroup };
  }, [allRoles]);
  const hasLive = inUse.length + seedGroup.length + simproGroup.length > 0;
  const totalRoles = allRoles.length;
  const visibleCount = showUnassigned
    ? (inUse.length + seedGroup.length + simproGroup.length)
    : inUse.length;

  // Build the src once on first render — and only rebuild when the admin
  // explicitly changes role or clicks Reload. Deliberately NOT reactive to
  // the matrix state above (we want the iframe to reflect *saved* config).
  const rebuild = (r = role) => setSrc(computeExpoUrl(r, getToken()));
  useEffect(() => { rebuild(role); }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const onRoleChange = (e) => {
    const r = e.target.value;
    setRole(r);
    rebuild(r);
  };
  const onReload = () => rebuild(role);
  const onOpen = () => {
    if (src) window.open(src, '_blank', 'noopener,noreferrer');
  };

  return (
    // Phase 4.4.1 (v125) — sticky settings:
    //   · `top-20` (80px) clears the 64px AppShell topbar instead of
    //     the previous `top-4` which let the panel slide under it.
    //   · `max-h-[calc(100vh-6rem)] overflow-y-auto` lets a tall
    //     preview bezel scroll internally on shorter viewports
    //     instead of being clipped behind the topbar.
    //   · `self-start` belt-and-braces guarantee the aside doesn't
    //     stretch to grid row height (parent already carries
    //     `items-start`, but explicit is cheaper than a regression).
    // v58.7 — Palette sync with mobile redesign. The card chrome,
    // header logo tile, bezel notch, and select focus ring now use
    // the mobile palette's amber (`#F5B301`) accent + `#E5E5E5` borders
    // so the panel doesn't visually clash with the redesigned Expo
    // screens rendering inside the iframe. The iframe content itself
    // is unchanged — it inherits the mobile team's palette when the
    // Expo bundle loads.
    <aside className="space-y-3 lg:sticky lg:top-20 lg:self-start lg:max-h-[calc(100vh-6rem)] lg:overflow-y-auto" data-testid="mobile-preview-panel">
      <div className="rounded-2xl border bg-white p-4" style={{ borderColor: '#E5E5E5' }}>
        <div className="flex items-center justify-between gap-2 mb-3 pb-3 border-b" style={{ borderColor: '#E5E5E5' }}>
          <div className="inline-flex items-center gap-2">
            <span
              className="w-9 h-9 rounded-xl inline-flex items-center justify-center shadow-sm"
              style={{ background: '#F5B301', color: '#0A0A0A' }}
            >
              <Phone20Regular />
            </span>
            <div>
              <div className="text-sm font-semibold" style={{ color: '#0A0A0A' }}>Live Preview</div>
              <div className="text-[11px]" style={{ color: '#6B6B6B' }}>
                Saved config · {(() => {
                  const match = allRoles.find((r) => r.role_id === role);
                  return match ? match.name : role;
                })()}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-1">
            <button type="button" onClick={onReload} data-testid="mobile-preview-reload"
              className="p-1.5 rounded-lg hover:bg-amber-50 transition"
              style={{ color: '#6B6B6B' }}
              title="Reload preview">
              <ArrowClockwise20Regular />
            </button>
            <button type="button" onClick={onOpen} data-testid="mobile-preview-open"
              className="p-1.5 rounded-lg hover:bg-amber-50 transition"
              style={{ color: '#6B6B6B' }}
              title="Open in new tab">
              <Open20Regular />
            </button>
          </div>
        </div>

        <label className="block">
          <div className="flex items-center justify-between mb-1">
            <span className="block text-[10px] uppercase tracking-[0.12em] font-semibold" style={{ color: '#A0A0A0' }}>Preview as role</span>
            {/* v58.4 — role-count summary next to the dropdown. */}
            <span className="text-[10px] tabular-nums" style={{ color: '#A0A0A0' }}
                  data-testid="mobile-preview-role-count">
              {visibleCount} of {totalRoles}
            </span>
          </div>
          <select
            value={role}
            onChange={onRoleChange}
            data-testid="mobile-preview-role"
            disabled={!canEdit}
            className="w-full rounded-lg border bg-white text-sm px-3 py-2 focus:outline-none focus:ring-2"
            style={{
              borderColor: '#E5E5E5',
              color: '#0A0A0A',
              '--tw-ring-color': '#FEF3C7',
            }}
            onFocus={(e) => { e.currentTarget.style.borderColor = '#F5B301'; }}
            onBlur={(e) => { e.currentTarget.style.borderColor = '#E5E5E5'; }}
          >
            {!hasLive && ROLES.map((r) => (
              <option key={r.key} value={r.key}>{r.label}</option>
            ))}
            {hasLive && inUse.length > 0 && (
              <optgroup label={`In use (${inUse.length})`}>
                {inUse.map((r) => (
                  <option key={r.role_id} value={r.role_id}>
                    {r.name} · {r.user_count} user{r.user_count === 1 ? '' : 's'}
                  </option>
                ))}
              </optgroup>
            )}
            {hasLive && showUnassigned && seedGroup.length > 0 && (
              <optgroup label={`System / seed — unassigned (${seedGroup.length})`}>
                {seedGroup.map((r) => (
                  <option key={r.role_id} value={r.role_id}>{r.name}</option>
                ))}
              </optgroup>
            )}
            {hasLive && showUnassigned && simproGroup.length > 0 && (
              <optgroup label={`Simpro — unassigned (${simproGroup.length})`}>
                {simproGroup.map((r) => (
                  <option key={r.role_id} value={r.role_id}>{r.name}</option>
                ))}
              </optgroup>
            )}
          </select>
          {/* v58.4 — checkbox to reveal unassigned roles. Default OFF. */}
          <label className="mt-2 flex items-center gap-2 text-[11px] cursor-pointer select-none" style={{ color: '#6B6B6B' }}>
            <input type="checkbox"
                   checked={showUnassigned}
                   onChange={(e) => setShowUnassigned(e.target.checked)}
                   data-testid="mobile-preview-show-unassigned"
                   className="w-3.5 h-3.5 rounded"
                   style={{ borderColor: '#E5E5E5', accentColor: '#F5B301' }} />
            Show unassigned roles
            <span className="tabular-nums" style={{ color: '#A0A0A0' }}>
              (+{seedGroup.length + simproGroup.length})
            </span>
          </label>
          <p className="mt-1 text-[10px] leading-tight" style={{ color: '#6B6B6B' }}>
            Reviewing what a user with this role would see. Per-user overrides are not reflected here.
          </p>
        </label>

        {/* Phone bezel — dark body (a real phone bezel IS dark), amber
            notch dot to match the mobile team's v58.7 palette. Iframe
            content is unchanged; it inherits the new mobile palette
            when the Expo bundle loads. */}
        <div className="mx-auto mt-4" style={{ width: 320 }}>
          <div
            className="relative rounded-[36px] p-3 shadow-2xl"
            style={{ height: 680, background: '#1A1A1A' }}
            data-testid="mobile-preview-bezel"
          >
            {/* Notch */}
            <div className="absolute top-2 left-1/2 -translate-x-1/2 w-28 h-5 rounded-b-2xl flex items-center justify-center" style={{ background: '#0A0A0A' }}>
              <span className="block w-1.5 h-1.5 rounded-full" style={{ background: '#F5B301' }} />
            </div>
            <iframe
              ref={iframeRef}
              src={src || 'about:blank'}
              title="Paneltec Civil mobile preview"
              data-testid="mobile-preview-iframe"
              sandbox="allow-scripts allow-same-origin allow-forms allow-popups"
              referrerPolicy="no-referrer-when-downgrade"
              className="w-full h-full rounded-[24px] block"
              style={{ border: 0, background: '#F5F5F7' }}
            />
          </div>
        </div>

        <p className="mt-3 text-[11px] leading-relaxed" style={{ color: '#6B6B6B' }}>
          Preview reflects unsaved toggle changes <strong style={{ color: '#0A0A0A' }}>only after Save</strong>.
          Click <span className="inline-flex items-center align-middle gap-0.5"><ArrowClockwise20Regular style={{ width: 12, height: 12 }} /></span> to reload once you&rsquo;ve saved.
        </p>
      </div>
    </aside>
  );
}

export default function MobileModulesSection({ canEdit }) {
  const [loading, setLoading]   = useState(true);
  const [saving, setSaving]     = useState(false);
  const [applyingDefaults, setApplyingDefaults] = useState(false);
  const [original, setOriginal] = useState(null);
  const [matrix, setMatrix]     = useState(null);
  // v58.5 — per-role overrides layered on top of the 4-category matrix.
  // Shape: `{role_id: {module_key: bool}}`.
  const [overrides, setOverrides] = useState({});
  // v58.4 — Live-fetched roles shared between the matrix table and the
  // PhonePreview dropdown. Prevents the historical mismatch where the
  // matrix showed 4 static columns and the dropdown showed 30 live roles.
  const { allRoles, loading: rolesLoading } = useLiveRoles();
  // Show-all toggle for the matrix — off by default, in which case we
  // cap at MATRIX_TOP_N_DEFAULT (default 8) non-admin live roles by
  // user count. Legacy 4 categories always appear.
  const [showAllCols, setShowAllCols] = useState(false);
  // v159.1 — server-reported defaults metadata. When
  // `needs_migration_review === true` we render a persistent banner so
  // the admin consciously reviews + applies the new hardened defaults.
  // Banner clears once the stored `defaults_version` matches on next load.
  const [defaultsMeta, setDefaultsMeta] = useState({
    needs_migration_review: false,
    defaults_version: null,
    stored_defaults_version: null,
    server_defaults: null,
  });

  const load = async () => {
    setLoading(true);
    try {
      const { data } = await api.get('/settings/mobile-modules');
      setOriginal(deepClone(data.mobile_modules));
      setMatrix(deepClone(data.mobile_modules));
      setOverrides(deepClone(data.mobile_modules_overrides || {}));
      setDefaultsMeta({
        needs_migration_review: !!data.needs_migration_review,
        defaults_version: data.defaults_version || null,
        stored_defaults_version: data.stored_defaults_version || null,
        server_defaults: data.defaults || null,
      });
    } catch (e) { toast.error(apiError(e)); }
    finally { setLoading(false); }
  };
  useEffect(() => { load(); }, []);

  const dirty = useMemo(() => matrix && original && !deepEq(matrix, original), [matrix, original]);

  const toggle = (role_id, mod) => {
    // v160.3.9.36 (Phase 5) — Row-key renamed from `role` → `role_id`
    // to align with the token-permission nomenclature. The mobile-
    // modules matrix is keyed by role_id (values happen to match
    // legacy role strings for seeded roles like `admin` / `worker`),
    // so the lock behaviour is identical to the pre-shim implementation.
    if (role_id === 'admin') return;          // admin row locked
    if (!canEdit) return;
    setMatrix((m) => ({ ...m, [role_id]: { ...m[role_id], [mod]: !m[role_id][mod] } }));
  };

  const setAllInRole = (role_id, value) => {
    if (role_id === 'admin' || !canEdit) return;
    setMatrix((m) => ({
      ...m,
      [role_id]: Object.fromEntries(MODULES.map((mo) => [mo.key, value])),
    }));
  };

  const reset = () => setMatrix(deepClone(original));

  // v58.5 — Per-role override handlers. `toggleOverride` writes a
  // single (role_id, module_key) override; `resetRoleOverrides` wipes
  // every override for a live role, restoring pure inheritance.
  const toggleOverride = async (role_id, module_key, current) => {
    if (!canEdit) return;
    const next = !current;
    // Optimistic update — snap the UI so rapid toggles feel responsive.
    setOverrides((o) => {
      const roleO = { ...(o[role_id] || {}) };
      roleO[module_key] = next;
      return { ...o, [role_id]: roleO };
    });
    try {
      const { data } = await api.patch('/settings/mobile-modules/overrides', {
        role_id, module_key, enabled: next,
      });
      // Server may UNSET the override (same-as-inherited); reflect that.
      setOverrides((o) => {
        const roleO = { ...(o[role_id] || {}) };
        if (data.override === null) delete roleO[module_key];
        else roleO[module_key] = data.override;
        const cleaned = { ...o };
        if (Object.keys(roleO).length === 0) delete cleaned[role_id];
        else cleaned[role_id] = roleO;
        return cleaned;
      });
    } catch (e) {
      // Roll back on failure.
      setOverrides((o) => {
        const roleO = { ...(o[role_id] || {}) };
        if (roleO[module_key] !== undefined && roleO[module_key] === next) {
          delete roleO[module_key];
        }
        const cleaned = { ...o };
        if (Object.keys(roleO).length === 0) delete cleaned[role_id];
        else cleaned[role_id] = roleO;
        return cleaned;
      });
      toast.error(apiError(e, 'Override write failed'));
    }
  };

  const resetRoleOverrides = async (role_id) => {
    if (!canEdit) return;
    try {
      await api.delete(`/settings/mobile-modules/overrides/${role_id}`);
      setOverrides((o) => {
        const cleaned = { ...o };
        delete cleaned[role_id];
        return cleaned;
      });
      toast.success('Reset to inherited');
    } catch (e) {
      toast.error(apiError(e, 'Reset failed'));
    }
  };

  // v58.4 — Compute the ordered list of columns to render in the matrix.
  // Contract:
  //   · Legacy 4 categories (Worker/Supervisor/Contractor/Admin) always
  //     appear FIRST and are editable — they are the storage buckets.
  //   · Live roles then follow, sorted by user_count desc then name.
  //   · When `showAllCols` is off, non-legacy live roles are capped at
  //     `MATRIX_TOP_N_DEFAULT`.
  //   · Each column carries a `category` field so the non-legacy cells
  //     can render the INHERITED toggle value from that category's
  //     storage bucket (read-only — you can only edit the 4 categories).
  const matrixCols = useMemo(() => {
    const cols = LEGACY_CATEGORIES.map((c) => ({
      key: c.key,
      label: c.label,
      category: c.key,
      is_category: true,
      user_count: allRoles
        .filter((r) => _categoryForRole(r.role_id, r.name) === c.key)
        .reduce((s, r) => s + (r.user_count || 0), 0),
    }));
    const seenLegacy = new Set(LEGACY_CATEGORIES.map((c) => c.key));
    const liveExtras = allRoles
      .filter((r) => !seenLegacy.has(r.role_id))
      .map((r) => ({
        key: r.role_id,
        label: r.name || r.role_id,
        category: _categoryForRole(r.role_id, r.name),
        is_category: false,
        source: r.source,
        user_count: r.user_count || 0,
      }))
      .sort((a, b) => (b.user_count - a.user_count)
                     || (a.label || '').localeCompare(b.label || ''));
    const visibleExtras = showAllCols ? liveExtras : liveExtras.slice(0, MATRIX_TOP_N_DEFAULT);
    return {
      cols: [...cols, ...visibleExtras],
      liveExtrasCount: liveExtras.length,
      hiddenCount: Math.max(0, liveExtras.length - visibleExtras.length),
    };
  }, [allRoles, showAllCols]);


  const save = async () => {
    setSaving(true);
    try {
      const r = await api.put('/settings/mobile-modules', { mobile_modules: matrix });
      toast.success(r.data.changes
        ? `Saved — ${r.data.changes} change${r.data.changes === 1 ? '' : 's'} applied.`
        : 'Saved.');
      setOriginal(deepClone(r.data.mobile_modules));
      setMatrix(deepClone(r.data.mobile_modules));
      // v159.1 — the PUT stamps `defaults_version` server-side, so reload
      // the metadata so the banner dismisses without a page refresh.
      await load();
    } catch (e) { toast.error(apiError(e)); }
    finally { setSaving(false); }
  };

  // v159.1 — one-click migration: overwrite the current matrix with the
  // server-supplied hardened defaults and persist. Uses the same PUT so
  // the audit log picks up a diff row per role/module that changes.
  const applyServerDefaults = async () => {
    if (!defaultsMeta.server_defaults) return;
    setApplyingDefaults(true);
    try {
      const next = deepClone(defaultsMeta.server_defaults);
      // Admin row is enforced all-true server-side, but mirror here so
      // the UI reflects the effective state immediately.
      next.admin = Object.fromEntries(MODULES.map((mo) => [mo.key, true]));
      const r = await api.put('/settings/mobile-modules', { mobile_modules: next });
      toast.success(r.data.changes
        ? `Hardened defaults applied — ${r.data.changes} change${r.data.changes === 1 ? '' : 's'}.`
        : 'Hardened defaults applied.');
      setOriginal(deepClone(r.data.mobile_modules));
      setMatrix(deepClone(r.data.mobile_modules));
      await load();
    } catch (e) { toast.error(apiError(e)); }
    finally { setApplyingDefaults(false); }
  };

  if (loading || !matrix) {
    return <div className="text-sm text-slate-500 p-6" data-testid="mobile-modules-loading">Loading mobile module matrix…</div>;
  }

  return (
    <div className="space-y-4" data-testid="mobile-modules-section">
      {/* v159.1 — "New defaults available" banner. Persistent (no
          localStorage dismiss) until the admin clicks Apply defaults or
          Save on the current matrix — either action stamps
          `defaults_version` server-side so the banner disappears on the
          next load. */}
      {canEdit && defaultsMeta.needs_migration_review && (
        <div
          data-testid="mobile-modules-defaults-banner"
          className="flex items-start gap-3 rounded-2xl border border-amber-200 bg-amber-50 p-4"
        >
          <div className="shrink-0 w-10 h-10 rounded-xl bg-amber-100 text-amber-700 inline-flex items-center justify-center">
            <DefaultsIcon />
          </div>
          <div className="min-w-0 flex-1">
            <div className="text-sm font-semibold text-amber-900">
              New hardened defaults available
              {defaultsMeta.defaults_version ? ` · ${defaultsMeta.defaults_version}` : ''}
            </div>
            <p className="text-[13px] text-amber-800 mt-1 leading-relaxed max-w-3xl">
              Paneltec has published a stricter default module matrix
              (workers no longer see Plant &amp; Vehicles, Document Library
              or the Users tile by default). Your current saved matrix was
              stamped
              <span className="font-mono px-1"> {defaultsMeta.stored_defaults_version || 'pre-v159'} </span>.
              Review the toggles below and click <strong>Apply hardened defaults</strong>
              to overwrite in one step, or make manual edits and hit Save.
            </p>
            <div className="flex flex-wrap items-center gap-2 mt-3">
              <button
                type="button"
                onClick={applyServerDefaults}
                disabled={applyingDefaults || saving}
                data-testid="mobile-modules-apply-defaults"
                className="inline-flex items-center gap-1.5 px-3.5 py-1.5 rounded-lg text-sm font-semibold bg-amber-600 hover:bg-amber-700 text-white disabled:opacity-60"
              >
                <DefaultsIcon /> {applyingDefaults ? 'Applying…' : 'Apply hardened defaults'}
              </button>
              <span className="text-[12px] text-amber-700">
                Or edit manually and press Save — either action clears this banner.
              </span>
            </div>
          </div>
        </div>
      )}

      <div className="flex items-start gap-3 rounded-2xl border border-slate-200 bg-white p-5">
        <div className="shrink-0 w-10 h-10 rounded-xl bg-orange-50 text-orange-600 inline-flex items-center justify-center">
          <Phone20Regular />
        </div>
        <div className="min-w-0">
          <h2 className="font-display text-xl font-semibold text-slate-900">Mobile App Modules</h2>
          <p className="text-sm text-slate-600 mt-1 max-w-2xl">
            Control which tabs and drawer entries appear in the Paneltec Civil
            mobile app for each role. Toggles take effect the next time a user
            signs in or pulls-to-refresh on Profile. Admins always see everything.
          </p>
        </div>
      </div>

      {/* Phase 4.4 — Two-column layout: matrix on the left, sticky
          phone-bezel preview on the right (stacks on < lg). */}
      <div className="grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_380px] gap-4 items-start">
        <div className="rounded-2xl border border-slate-200 bg-white overflow-hidden">
          {/* v58.4 — Column control strip. Shows the matrix ↔ preview
              consistency count and the "show all columns" toggle. */}
          <div className="flex items-center justify-between gap-3 px-4 py-2.5 border-b border-slate-100 bg-slate-50/60"
               data-testid="mobile-modules-cols-strip">
            <div className="text-[11px] text-slate-600">
              <span className="font-semibold text-slate-800">
                {matrixCols.cols.length}
              </span>{' '}
              column{matrixCols.cols.length === 1 ? '' : 's'} —
              {' '}4 legacy categories + {' '}
              <span className="tabular-nums">
                {matrixCols.cols.length - LEGACY_CATEGORIES.length}
              </span>{' '}
              live role{matrixCols.cols.length - LEGACY_CATEGORIES.length === 1 ? '' : 's'}
              {matrixCols.hiddenCount > 0 && (
                <span className="text-slate-400">
                  {' · '}{matrixCols.hiddenCount} hidden
                </span>
              )}
            </div>
            <label className="flex items-center gap-2 text-[11px] text-slate-700 cursor-pointer select-none">
              <input type="checkbox"
                     checked={showAllCols}
                     onChange={(e) => setShowAllCols(e.target.checked)}
                     data-testid="mobile-modules-show-all-cols"
                     className="w-3.5 h-3.5 rounded border-slate-300" />
              Show all columns
            </label>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm" data-testid="mobile-modules-grid">
              <thead className="bg-slate-50 text-slate-500 text-[11px] uppercase tracking-wider">
                <tr>
                  <th className="text-left px-4 py-3 font-semibold w-[42%]">Module</th>
                  {matrixCols.cols.map((r) => (
                    <th key={r.key} className="px-3 py-3 font-semibold text-center"
                        data-testid={`mobile-col-${r.key}`}
                        data-category={r.category}>
                      <div className="inline-flex items-center gap-1.5 justify-center">
                        <span className="text-slate-700">{r.label}</span>
                        {r.key === 'admin' && <LockClosed20Regular style={{ width: 12, height: 12 }} className="text-slate-400" />}
                      </div>
                      {/* v58.4/v58.5 — For non-category live-role columns
                          show which storage bucket they inherit from,
                          user count, override count, and a "Reset to
                          inherited" affordance. */}
                      {!r.is_category ? (
                        <div className="mt-1 flex flex-col items-center gap-0.5">
                          <span className="text-[9px] font-medium text-slate-400 normal-case tracking-normal">
                            inherits {r.category}
                          </span>
                          <span className="text-[9px] text-slate-500 tabular-nums normal-case">
                            {r.user_count} user{r.user_count === 1 ? '' : 's'}
                          </span>
                          {overrides[r.key] && Object.keys(overrides[r.key]).length > 0 && (
                            <button
                              type="button"
                              onClick={() => resetRoleOverrides(r.key)}
                              disabled={!canEdit}
                              className="text-[9px] font-medium text-orange-600 hover:underline normal-case tracking-normal disabled:opacity-50"
                              data-testid={`mobile-reset-overrides-${r.key}`}
                              title="Remove all overrides for this role"
                            >
                              reset ({Object.keys(overrides[r.key]).length})
                            </button>
                          )}
                        </div>
                      ) : r.key !== 'admin' && canEdit ? (
                        <div className="flex items-center justify-center gap-1.5 mt-1.5 text-[10px] font-medium">
                          <button
                            type="button"
                            onClick={() => setAllInRole(r.key, true)}
                            data-testid={`mobile-all-on-${r.key}`}
                            className="text-orange-600 hover:text-orange-700 hover:underline"
                          >All on</button>
                          <span className="text-slate-300">·</span>
                          <button
                            type="button"
                            onClick={() => setAllInRole(r.key, false)}
                            data-testid={`mobile-all-off-${r.key}`}
                            className="text-slate-500 hover:text-slate-700 hover:underline"
                          >All off</button>
                        </div>
                      ) : null}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {MODULES.map(({ key, label, Icon }) => (
                  <tr key={key} className="border-t border-slate-100" data-testid={`mobile-row-${key}`}>
                    <td className="px-4 py-3">
                      <div className="inline-flex items-center gap-2.5">
                        <span className="w-8 h-8 rounded-lg bg-slate-100 text-slate-700 inline-flex items-center justify-center">
                          <Icon />
                        </span>
                        <span className="font-medium text-slate-800">{label}</span>
                      </div>
                    </td>
                    {matrixCols.cols.map((r) => {
                      // v58.5 — Non-category columns render either the
                      // EFFECTIVE toggle (overridden) or the INHERITED
                      // toggle (from their category's bucket) with
                      // distinct visual states.
                      const bucketKey = r.is_category ? r.key : r.category;
                      const inherited = !!matrix[bucketKey]?.[key];
                      const roleOverride = !r.is_category
                        ? (overrides[r.key] || {})[key]
                        : undefined;
                      const hasOverride = roleOverride !== undefined;
                      const on = hasOverride ? !!roleOverride : inherited;
                      const locked = r.key === 'admin' || !canEdit;
                      return (
                        <td key={r.key} className="text-center px-3 py-3"
                            data-inherit={!r.is_category || undefined}
                            data-override={hasOverride || undefined}>
                          {r.is_category ? (
                            <ToggleCell
                              on={on}
                              locked={locked}
                              onChange={() => toggle(r.key, key)}
                              testid={`mobile-toggle-${r.key}-${key}`}
                            />
                          ) : (
                            <button
                              type="button"
                              disabled={!canEdit}
                              onClick={() => toggleOverride(r.key, key, on)}
                              data-testid={`mobile-override-${r.key}-${key}`}
                              data-state={hasOverride ? (on ? 'override-on' : 'override-off') : 'inherit'}
                              title={hasOverride
                                ? `Overridden (${on ? 'ON' : 'OFF'}) — click to revert`
                                : `Inheriting from ${r.category} — click to override`}
                              className={`
                                inline-flex items-center justify-center w-8 h-6 rounded-md text-[11px] font-semibold transition
                                ${hasOverride
                                  ? (on
                                    ? 'bg-emerald-100 text-emerald-800 border border-emerald-300 hover:bg-emerald-200'
                                    : 'bg-red-100 text-red-800 border border-red-300 hover:bg-red-200')
                                  : (on
                                    ? 'text-emerald-500/60 hover:bg-slate-100'
                                    : 'text-slate-300 hover:bg-slate-100')
                                }
                                disabled:opacity-50 disabled:cursor-not-allowed
                              `.trim().replace(/\s+/g, ' ')}
                            >
                              {hasOverride ? (on ? '✓' : '✕') : (on ? '↳✓' : '↳·')}
                            </button>
                          )}
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <PhonePreview canEdit={canEdit} />
      </div>

      {/* Sticky save bar — appears only when dirty so the page stays calm. */}
      {canEdit && dirty && (
        <div className="sticky bottom-4 z-10" data-testid="mobile-modules-savebar">
          <div className="mx-auto max-w-3xl rounded-2xl border border-slate-900/10 bg-slate-900 text-white shadow-2xl px-4 py-3 flex items-center justify-between gap-3">
            <div className="text-sm">
              <span className="inline-block w-2 h-2 rounded-full bg-orange-400 mr-2 align-middle"></span>
              Unsaved mobile module changes.
            </div>
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={reset}
                disabled={saving}
                data-testid="mobile-modules-reset"
                className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-medium text-slate-100 hover:bg-white/10"
              ><ArrowReset20Regular /> Reset</button>
              <button
                type="button"
                onClick={save}
                disabled={saving}
                data-testid="mobile-modules-save"
                className="inline-flex items-center gap-1.5 px-3.5 py-1.5 rounded-lg text-sm font-semibold bg-orange-500 hover:bg-orange-600 disabled:opacity-60"
              ><Save20Regular /> {saving ? 'Saving…' : 'Save changes'}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// v160.3.8.1 — Draggable Settings sub-nav.
//
// Replaces the old flat "Settings" section in `AppShell.jsx`. Layout is
// persisted per-org in Mongo (`settings_nav_layout`) and read/written
// via `/api/settings/nav-layout`. Admins get drag handles, "+ New
// folder", inline rename (double-click), and per-folder delete;
// non-admins see the same layout as read-only nav.
//
// Powered by @dnd-kit for accessibility (arrow keys move focused item,
// space activates the drag). Two SortableContext scopes: root and one
// per folder — dragging BETWEEN scopes uses `onDragOver` to move the
// item into the destination scope.
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { NavLink } from 'react-router-dom';
import { toast } from 'sonner';
import {
  DndContext, PointerSensor, KeyboardSensor,
  useSensor, useSensors, closestCenter,
  DragOverlay, useDroppable,
} from '@dnd-kit/core';
import {
  SortableContext, useSortable, verticalListSortingStrategy,
  sortableKeyboardCoordinates, arrayMove,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import {
  ChevronDown20Regular, ChevronRight20Regular,
  ReOrderDotsVertical20Regular, Add20Regular,
  Delete20Regular, FolderAdd20Regular,
} from '@fluentui/react-icons';

import api, { apiError } from '../../lib/api';
import useLockBodyScroll from '../../lib/useLockBodyScroll';
import { useCan } from '../../lib/permissions';
import {
  SETTINGS_NAV_BY_KEY, defaultSettingsLayout,
} from '../../lib/settingsNavRegistry';

const COLLAPSE_KEY = 'paneltec_settings_nav_collapsed';

// Load per-user collapsed state; wrap in try/catch for Safari private.
function loadCollapsed() {
  try {
    const raw = localStorage.getItem(COLLAPSE_KEY);
    return raw ? JSON.parse(raw) : { folder_admin: true };
  } catch { return { folder_admin: true }; }
}
function saveCollapsed(state) {
  try { localStorage.setItem(COLLAPSE_KEY, JSON.stringify(state)); } catch { /* noop */ }
}

// Fresh folder id. v160.3.8.5 — Prefer `crypto.randomUUID()` when
// available so the id is guaranteed unique and stable across the
// call site. Falls back to a Math.random-based combo for older
// browsers (Safari <15) which don't expose it on window.
function newFolderId() {
  try {
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
      return 'folder_' + crypto.randomUUID();
    }
  } catch { /* noop */ }
  return 'folder_' + Math.random().toString(36).slice(2, 8) + '_' + Date.now().toString(36);
}

// Walk the layout and yield {node, path[]} for each leaf.
function findItem(layout, id) {
  for (let i = 0; i < layout.length; i++) {
    const n = layout[i];
    if (n.type === 'item' && n.key === id) return { path: [i], node: n };
    if (n.type === 'folder') {
      if (n.id === id) return { path: [i], node: n };
      const c = n.children || [];
      for (let j = 0; j < c.length; j++) {
        if (c[j].type === 'item' && c[j].key === id) return { path: [i, j], node: c[j] };
      }
    }
  }
  return null;
}

function removeAtPath(layout, path) {
  const copy = JSON.parse(JSON.stringify(layout));
  if (path.length === 1) {
    const [n] = copy.splice(path[0], 1);
    return { next: copy, node: n };
  }
  const [fi, ci] = path;
  const [n] = copy[fi].children.splice(ci, 1);
  return { next: copy, node: n };
}

function insertAtIndex(layout, targetPath, node) {
  const copy = JSON.parse(JSON.stringify(layout));
  if (targetPath.length === 1) copy.splice(targetPath[0], 0, node);
  else copy[targetPath[0]].children.splice(targetPath[1], 0, node);
  return copy;
}

export default function SettingsNav({ collapsed: navCollapsed, onItemClick, canAdminNav }) {
  const can = useCan();
  // v160.3.9.29-2a — Prop renamed from `isAdmin` to `canAdminNav` to
  // reflect the new semantic (users.edit-derived, not the literal
  // `admin` role). Behaviour unchanged for admin + hseq_lead.
  const isAdmin = canAdminNav;
  const [layout, setLayout] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [folderCollapsed, setFolderCollapsed] = useState(loadCollapsed);
  const [activeId, setActiveId] = useState(null);
  const [renamingFolderId, setRenamingFolderId] = useState(null);
  const [renameDraft, setRenameDraft] = useState('');
  const [newFolderInput, setNewFolderInput] = useState(null); // { label: '' } when adding
  const [deleteFolder, setDeleteFolder] = useState(null);
  const saveTimer = useRef(null);
  const lastSaved = useRef(null);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 4 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  );

  // Load from server; fall back to default seed on error.
  useEffect(() => {
    let live = true;
    (async () => {
      try {
        const { data } = await api.get('/settings/nav-layout');
        if (!live) return;
        setLayout(data.layout || defaultSettingsLayout());
        lastSaved.current = JSON.stringify(data.layout || []);
      } catch {
        if (!live) return;
        setLayout(defaultSettingsLayout());
      } finally {
        if (live) setLoaded(true);
      }
    })();
    return () => { live = false; };
  }, []);

  const persist = useCallback((nextLayout) => {
    if (!isAdmin) return;
    if (saveTimer.current) clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(async () => {
      try {
        await api.put('/settings/nav-layout', { layout: nextLayout });
        lastSaved.current = JSON.stringify(nextLayout);
      } catch (e) {
        toast.error(apiError(e));
        // Revert to last-known-good so the UI doesn't lie.
        try {
          if (lastSaved.current) setLayout(JSON.parse(lastSaved.current));
        } catch { /* noop */ }
      }
    }, 500);
  }, [isAdmin]);

  const toggleFolder = (fid) => {
    const next = { ...folderCollapsed, [fid]: !folderCollapsed[fid] };
    setFolderCollapsed(next);
    saveCollapsed(next);
  };

  const commitLayout = (nextLayout) => {
    setLayout(nextLayout);
    persist(nextLayout);
  };

  const handleDragStart = (evt) => setActiveId(evt.active.id);

  const handleDragEnd = (evt) => {
    setActiveId(null);
    const { active, over } = evt;
    if (!over || active.id === over.id) return;

    // v160.3.8.5 — Body-drop path. Every folder registers an
    // additional `body:<id>` droppable on its inner <ul> (see
    // <FolderBody /> below) so drops onto an empty folder — which
    // has zero sortable children — still land on a valid target.
    // Without this, dropping on the "Drop items here" placeholder
    // of a newly-created folder produced no `over` id and the drag
    // was silently discarded. Root cause (1) in v160.3.8.5 spec.
    if (typeof over.id === 'string' && over.id.startsWith('body:')) {
      const folderId = over.id.slice('body:'.length);
      const src = findItem(layout, active.id);
      const target = findItem(layout, folderId);
      if (!src || !target || target.node.type !== 'folder' || src.node.type !== 'item') return;
      const { next: removed } = removeAtPath(layout, src.path);
      const idx = removed.findIndex((n) => n.type === 'folder' && n.id === folderId);
      if (idx < 0) return;
      const withInsert = JSON.parse(JSON.stringify(removed));
      withInsert[idx].children.push(src.node);   // append to end
      commitLayout(withInsert);
      return;
    }

    const src = findItem(layout, active.id);
    const dst = findItem(layout, over.id);
    if (!src || !dst) return;

    // Both at root & no folder involved → simple arrayMove
    if (src.path.length === 1 && dst.path.length === 1
        && src.node.type === 'item' && dst.node.type === 'item') {
      const from = src.path[0], to = dst.path[0];
      commitLayout(arrayMove(layout, from, to));
      return;
    }

    // If we dropped onto a folder header, append to the end of its
    // children (v160.3.8.5 — was `unshift` prior; APPEND is more
    // intuitive when dropping onto a partially-populated folder so
    // the operator's most-recently-added item is at the bottom).
    if (dst.node.type === 'folder' && src.node.type === 'item') {
      const { next: removed } = removeAtPath(layout, src.path);
      const folderIdx = findItem(removed, dst.node.id).path[0];
      const withInsert = JSON.parse(JSON.stringify(removed));
      withInsert[folderIdx].children.push(src.node);
      commitLayout(withInsert);
      return;
    }

    // Otherwise: same container reorder OR cross-container move.
    const srcContainer = src.path.length === 1 ? 'root' : layout[src.path[0]].id;
    const dstContainer = dst.path.length === 1 ? 'root' : layout[dst.path[0]].id;
    const { next: removed } = removeAtPath(layout, src.path);
    // Recompute dst path AFTER removal (indices may have shifted).
    const dstAfter = findItem(removed, over.id);
    if (!dstAfter) {
      commitLayout(removed);
      return;
    }
    const insertPath = [...dstAfter.path];
    if (srcContainer === dstContainer && src.path[src.path.length - 1] < dst.path[dst.path.length - 1]) {
      // Same container, moving DOWN → dst index was decremented by removal, so drop AFTER.
      insertPath[insertPath.length - 1] += 1;
    }
    commitLayout(insertAtIndex(removed, insertPath, src.node));
  };

  const handleAddFolder = () => setNewFolderInput({ label: '' });

  const commitNewFolder = () => {
    const label = (newFolderInput?.label || '').trim() || 'New folder';
    const folder = { type: 'folder', id: newFolderId(), label, children: [] };
    commitLayout([...layout, folder]);
    setNewFolderInput(null);
  };

  const startRename = (folder) => {
    if (!isAdmin) return;
    setRenamingFolderId(folder.id);
    setRenameDraft(folder.label);
  };
  const commitRename = () => {
    if (!renamingFolderId) return;
    const label = (renameDraft || '').trim() || 'Folder';
    commitLayout(layout.map((n) =>
      n.type === 'folder' && n.id === renamingFolderId ? { ...n, label } : n,
    ));
    setRenamingFolderId(null);
    setRenameDraft('');
  };

  const doDeleteFolder = (folder) => {
    // Cascade children back to root at the folder's original position.
    const idx = layout.findIndex((n) => n.type === 'folder' && n.id === folder.id);
    if (idx < 0) return;
    const next = JSON.parse(JSON.stringify(layout));
    const children = next[idx].children || [];
    next.splice(idx, 1, ...children);
    commitLayout(next);
    setDeleteFolder(null);
  };

  const visibleAt = (nodes) => nodes.filter((n) => {
    if (n.type !== 'item') return true;
    const reg = SETTINGS_NAV_BY_KEY[n.key];
    if (!reg) return false;
    // v160.3.9.29-2a — `requiresCan: [resource, action]` supersedes the
    // legacy `adminOnly: true` flag. Both branches supported during
    // the sub-phase 2a → 2b/2c migration.
    if (reg.requiresCan && !can(...reg.requiresCan)) return false;
    if (reg.adminOnly && !isAdmin) return false;
    if (reg.resource && !can(reg.resource, 'open')) return false;
    return true;
  });

  const visibleRoot = useMemo(() => visibleAt(layout), [layout, isAdmin]); // eslint-disable-line react-hooks/exhaustive-deps
  const rootIds = visibleRoot.map((n) => n.type === 'item' ? n.key : n.id);

  if (!loaded) {
    return (
      <div className="px-2 mb-2 text-[10px] font-semibold uppercase tracking-[0.12em] text-slate-400">
        Settings
      </div>
    );
  }

  return (
    <div className="mb-5" data-testid="settings-nav">
      {!navCollapsed && (
        <div className="px-2 mb-2 text-[10px] font-semibold uppercase tracking-[0.12em] text-slate-400">
          Settings
        </div>
      )}
      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <SortableContext items={rootIds} strategy={verticalListSortingStrategy}>
          <ul className="space-y-0.5">
            {visibleRoot.map((n) => (
              n.type === 'item' ? (
                <SortableItem
                  key={n.key} id={n.key} node={n}
                  navCollapsed={navCollapsed} onItemClick={onItemClick}
                  isAdmin={isAdmin} inFolder={false}
                />
              ) : (
                <SortableFolder
                  key={n.id} folder={n}
                  collapsed={!!folderCollapsed[n.id]}
                  onToggle={() => toggleFolder(n.id)}
                  isRenaming={renamingFolderId === n.id}
                  renameDraft={renameDraft}
                  onRenameDraftChange={setRenameDraft}
                  onStartRename={() => startRename(n)}
                  onCommitRename={commitRename}
                  onDelete={() => setDeleteFolder(n)}
                  onItemClick={onItemClick} navCollapsed={navCollapsed}
                  isAdmin={isAdmin}
                  visibleAt={visibleAt}
                />
              )
            ))}
          </ul>
        </SortableContext>
        <DragOverlay>
          {activeId ? <div className="rounded-lg bg-white shadow-md border border-slate-300 px-2 py-1.5 text-xs text-slate-700">Moving…</div> : null}
        </DragOverlay>
      </DndContext>
      {isAdmin && !navCollapsed && (
        <div className="mt-2 px-2">
          {newFolderInput ? (
            <div className="flex items-center gap-1">
              <input
                autoFocus
                value={newFolderInput.label}
                onChange={(e) => setNewFolderInput({ label: e.target.value })}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') commitNewFolder();
                  if (e.key === 'Escape') setNewFolderInput(null);
                }}
                onBlur={commitNewFolder}
                placeholder="Folder name"
                data-testid="settings-nav-new-folder-input"
                className="flex-1 text-xs px-2 py-1 rounded border border-slate-300 focus:border-blue-500 focus:outline-none"
              />
            </div>
          ) : (
            <button type="button" onClick={handleAddFolder}
              data-testid="settings-nav-new-folder-btn"
              className="w-full flex items-center gap-1.5 text-[11px] text-slate-500 hover:text-slate-800 hover:bg-slate-100 rounded px-1.5 py-1"
            >
              <FolderAdd20Regular style={{ width: 14, height: 14 }} />
              New folder
            </button>
          )}
        </div>
      )}
      {deleteFolder && (
        <DeleteFolderModal
          folder={deleteFolder}
          onCancel={() => setDeleteFolder(null)}
          onConfirm={() => doDeleteFolder(deleteFolder)}
        />
      )}
    </div>
  );
}

function SortableItem({ id, node, navCollapsed, onItemClick, isAdmin, inFolder }) {
  const reg = SETTINGS_NAV_BY_KEY[node.key];
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id, disabled: !isAdmin });
  const style = { transform: CSS.Transform.toString(transform), transition, opacity: isDragging ? 0.4 : 1 };
  if (!reg) return null;
  const IconFilled = reg.iconActive || reg.icon;
  return (
    <li ref={setNodeRef} style={style} className="group relative">
      {isAdmin && !navCollapsed && (
        <button
          type="button"
          /* v160.3.8.5 — Bright-blue grip. Previous slate-400 was
             barely visible on the cream sidebar. Uses Tailwind
             blue-600 (`#2563EB`) idle → blue-700 (`#1D4ED8`) on
             hover. Reveal-on-row-hover behaviour unchanged. */
          className="absolute left-0 top-1/2 -translate-y-1/2 opacity-0 group-hover:opacity-100 text-[#2563EB] hover:text-[#1D4ED8] cursor-grab active:cursor-grabbing p-0.5"
          data-testid={`${reg.testid}-drag-handle`}
          {...attributes} {...listeners}
          title="Drag to reorder"
        >
          <ReOrderDotsVertical20Regular style={{ width: 12, height: 12 }} />
        </button>
      )}
      <NavLink
        to={reg.route}
        onClick={onItemClick}
        data-testid={reg.testid}
        className={({ isActive }) =>
          `flex items-center gap-3 rounded-lg py-2 text-sm transition-all ${
            inFolder ? 'pr-2.5 pl-6' : 'pr-2.5 pl-4'
          } ${
            isActive
              ? 'sidebar-active text-slate-900'
              : 'sidebar-idle text-slate-700 hover:text-slate-900'
          }`}
        title={navCollapsed ? reg.label : undefined}
      >
        {({ isActive }) => (
          <>
            <IconFilled
              className={`shrink-0 transition-colors sidebar-icon ${isActive ? 'text-orange-500' : 'text-slate-500 group-hover:text-slate-700'}`}
              style={{ width: 20, height: 20 }}
            />
            {!navCollapsed && <span className="truncate flex-1">{reg.label}</span>}
          </>
        )}
      </NavLink>
    </li>
  );
}

function SortableFolder({
  folder, collapsed, onToggle,
  isRenaming, renameDraft, onRenameDraftChange, onStartRename, onCommitRename,
  onDelete, onItemClick, navCollapsed, isAdmin, visibleAt,
}) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: folder.id, disabled: !isAdmin });
  const style = { transform: CSS.Transform.toString(transform), transition, opacity: isDragging ? 0.4 : 1 };
  const kids = visibleAt(folder.children || []);
  const kidIds = kids.map((k) => k.key);
  const Chevron = collapsed ? ChevronRight20Regular : ChevronDown20Regular;
  return (
    <li ref={setNodeRef} style={style} className="group/folder relative"
        data-testid={`settings-nav-folder-${folder.id}`}>
      <div className="flex items-stretch gap-1">
        {isAdmin && !navCollapsed && (
          <button
            type="button"
            /* v160.3.8.5 — Bright-blue grip on folders too. */
            className="opacity-0 group-hover/folder:opacity-100 text-[#2563EB] hover:text-[#1D4ED8] cursor-grab active:cursor-grabbing px-0.5 self-center"
            data-testid={`settings-nav-folder-${folder.id}-drag-handle`}
            {...attributes} {...listeners}
            title="Drag folder"
          >
            <ReOrderDotsVertical20Regular style={{ width: 12, height: 12 }} />
          </button>
        )}
        <button
          type="button"
          onClick={onToggle}
          onDoubleClick={() => !isRenaming && onStartRename()}
          data-testid={`settings-nav-folder-${folder.id}-toggle`}
          className="flex-1 flex items-center gap-1.5 rounded-lg pr-2.5 pl-1.5 py-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500 hover:text-slate-800 hover:bg-slate-50"
        >
          <Chevron style={{ width: 14, height: 14 }} />
          {isRenaming ? (
            <input
              autoFocus
              value={renameDraft}
              onChange={(e) => onRenameDraftChange(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') onCommitRename();
                if (e.key === 'Escape') onCommitRename();
              }}
              onBlur={onCommitRename}
              onClick={(e) => e.stopPropagation()}
              data-testid={`settings-nav-folder-${folder.id}-rename-input`}
              className="flex-1 bg-transparent border-b border-blue-400 text-slate-800 focus:outline-none text-[11px] uppercase tracking-wider"
            />
          ) : (
            !navCollapsed && <span className="truncate flex-1 text-left">{folder.label}</span>
          )}
        </button>
        {isAdmin && !navCollapsed && !isRenaming && (
          <button type="button" onClick={onDelete}
            data-testid={`settings-nav-folder-${folder.id}-delete`}
            title="Delete folder"
            className="opacity-0 group-hover/folder:opacity-100 text-slate-400 hover:text-rose-600 px-1 self-center"
          >
            <Delete20Regular style={{ width: 12, height: 12 }} />
          </button>
        )}
      </div>
      {!collapsed && (
        <SortableContext items={kidIds} strategy={verticalListSortingStrategy}>
          <FolderBody folderId={folder.id} navCollapsed={navCollapsed} kids={kids} isAdmin={isAdmin} onItemClick={onItemClick} />
        </SortableContext>
      )}
    </li>
  );
}

/**
 * v160.3.8.5 — Explicit droppable for a folder's body ul.
 *
 * The parent `<SortableContext>` gives us ordering-inside-folder for
 * whatever items live in the folder, but it does NOT register the ul
 * itself as a drop target. When the folder is empty (kidIds = []),
 * there are no sortable children to collide with, so any drop that
 * misses the folder-header row falls through and gets silently
 * discarded. Registering the ul as its own droppable — with id
 * `body:<folderId>` — gives every folder (including brand-new
 * empty ones) a robust drop zone that spans the whole card body.
 *
 * `handleDragEnd()` recognises the `body:` prefix and appends the
 * dragged item to the folder's children.
 */
function FolderBody({ folderId, navCollapsed, kids, isAdmin, onItemClick }) {
  const { setNodeRef, isOver } = useDroppable({ id: 'body:' + folderId });
  return (
    <ul
      ref={setNodeRef}
      className="space-y-0.5 ml-1"
      data-testid={`settings-nav-folder-${folderId}-body`}
      style={{
        minHeight: kids.length === 0 ? 30 : undefined,
        borderRadius: 8,
        background: isOver ? 'rgba(37, 99, 235, 0.08)' : 'transparent',
        transition: 'background 120ms ease',
      }}
    >
      {kids.map((k) => (
        <SortableItem
          key={k.key} id={k.key} node={k}
          navCollapsed={navCollapsed} onItemClick={onItemClick}
          isAdmin={isAdmin} inFolder={true}
        />
      ))}
      {kids.length === 0 && !navCollapsed && (
        <li className={`text-[10px] italic pl-6 py-1 transition-colors ${isOver ? 'text-[#1D4ED8] font-semibold' : 'text-slate-400'}`}>
          {isOver ? 'Release to drop here' : 'Drop items here'}
        </li>
      )}
    </ul>
  );
}

function DeleteFolderModal({ folder, onCancel, onConfirm }) {
  useLockBodyScroll(true);
  const childCount = (folder.children || []).length;
  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 p-4"
      onClick={onCancel}
      data-testid={`settings-nav-folder-${folder.id}-delete-modal`}
    >
      <div className="w-full max-w-md rounded-2xl bg-white shadow-xl" onClick={(e) => e.stopPropagation()}>
        <div className="px-5 py-4 border-b border-slate-200">
          <h2 className="text-base font-semibold text-slate-900">
            Delete folder “{folder.label}”?
          </h2>
        </div>
        <div className="px-5 py-4 text-sm text-slate-700 space-y-2">
          {childCount === 0
            ? <p>This folder is empty. Deleting it just removes the header — no nav items are affected.</p>
            : (
              <>
                <p>
                  This folder contains {childCount} item{childCount === 1 ? '' : 's'}.
                </p>
                <p className="text-xs text-slate-500">
                  Deleting the folder moves those items back to the Settings root — they’re not deleted.
                </p>
              </>
            )}
        </div>
        <div className="px-5 py-3 border-t border-slate-200 flex justify-end gap-2">
          <button type="button" onClick={onCancel}
            data-testid={`settings-nav-folder-${folder.id}-delete-cancel`}
            className="px-3 py-1.5 rounded-lg text-sm font-medium text-slate-700 hover:bg-slate-100"
          >
            Cancel
          </button>
          <button type="button" onClick={onConfirm}
            data-testid={`settings-nav-folder-${folder.id}-delete-confirm`}
            className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-rose-600 text-white text-sm font-semibold hover:bg-rose-700"
          >
            Delete folder
          </button>
        </div>
      </div>
    </div>
  );
}

// SupplierDrawer — right-side drawer holding the Tasks / Notes / Members /
// Folders panels for a single supplier. Phase 2 wiring (Folders panel is a
// placeholder until next turn).
import React, { useEffect, useMemo, useState } from 'react';
import {
  Calendar, Check, CheckSquare, FolderOpen, Loader2, Pencil, Plus,
  StickyNote, Trash2, User as UserIcon, Users, X,
} from 'lucide-react';
import { toast } from 'sonner';
import {
  Sheet, SheetContent, SheetHeader, SheetTitle,
} from '../ui/sheet';
import api, { apiError } from '../../lib/api';
import { getUser } from '../../lib/auth';
import { useCan } from '../../lib/permissions';

// v160.3.9.29-2c — Legacy set retained; authoritative gate is useCan below.
const WRITE_ROLES = new Set(['admin', 'hseq_lead']);

const PANEL_THEMES = {
  tasks:   { name: 'Tasks',   icon: CheckSquare,  bg: 'bg-[#fbf3df]', ink: 'text-[#8c6a1a]' },
  notes:   { name: 'Notes',   icon: StickyNote,   bg: 'bg-[#e6eff9]', ink: 'text-[#1e4a8c]' },
  folders: { name: 'Folders', icon: FolderOpen,   bg: 'bg-[#ece6f4]', ink: 'text-[#4f3a8c]' },
  members: { name: 'Members', icon: Users,        bg: 'bg-[#fbeadf]', ink: 'text-[#a8480f]' },
};

function initials(name) {
  return (name || '?').split(/\s+/).filter(Boolean).slice(0, 2).map((p) => p[0].toUpperCase()).join('') || '?';
}
function fmtDate(s) { return s ? s.slice(0, 10) : ''; }
function isOverdue(due, status) {
  if (!due || status === 'done' || status === 'cancelled') return false;
  return due < new Date().toISOString().slice(0, 10);
}

// ────────────────────── Tasks panel ──────────────────────
function TasksPanel({ supplierId, canEdit, onChanged }) {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [editing, setEditing] = useState(null); // null | "new" | task object

  const load = async () => {
    setLoading(true);
    try {
      const { data } = await api.get(`/suppliers/${supplierId}/tasks`);
      setItems(data || []);
    } catch (e) { toast.error(apiError(e)); }
    finally { setLoading(false); }
  };
  useEffect(() => { load(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [supplierId]);

  const filtered = useMemo(() => {
    if (filter === 'all') return items;
    return items.filter((t) => t.status === filter);
  }, [items, filter]);

  const toggleDone = async (t) => {
    const next = t.status === 'done' ? 'open' : 'done';
    try {
      await api.patch(`/suppliers/tasks/${t.id}`, { status: next });
      await load(); onChanged?.();
    } catch (e) { toast.error(apiError(e)); }
  };

  const saveTask = async (form) => {
    try {
      if (editing === 'new') {
        await api.post(`/suppliers/${supplierId}/tasks`, form);
        toast.success('Task added');
      } else {
        await api.patch(`/suppliers/tasks/${editing.id}`, form);
        toast.success('Task updated');
      }
      setEditing(null); await load(); onChanged?.();
    } catch (e) { toast.error(apiError(e)); }
  };

  const remove = async (t) => {
    try {
      await api.delete(`/suppliers/tasks/${t.id}`);
      toast.success('Task deleted'); await load(); onChanged?.();
    } catch (e) { toast.error(apiError(e)); }
  };

  return (
    <div className="space-y-3" data-testid="tasks-panel">
      <div className="flex items-center gap-2 flex-wrap">
        {canEdit && (
          <button onClick={() => setEditing('new')} data-testid="task-add"
            className="inline-flex items-center gap-1 px-3 py-1.5 rounded-lg bg-[#8c6a1a] text-white text-xs font-medium hover:bg-[#6f5314]">
            <Plus size={12} /> Add task
          </button>
        )}
        <div className="flex gap-1 ml-auto">
          {['all', 'open', 'in_progress', 'done'].map((f) => (
            <button key={f} onClick={() => setFilter(f)} data-testid={`task-filter-${f}`}
              className={`text-[11px] px-2 py-1 rounded-full uppercase tracking-wider ${
                filter === f ? 'bg-[#fbf3df] text-[#8c6a1a] font-semibold' : 'text-slate-500 hover:bg-slate-100'
              }`}>{f.replace('_', ' ')}</button>
          ))}
        </div>
      </div>

      {editing === 'new' && <TaskForm onSave={saveTask} onCancel={() => setEditing(null)} />}

      {loading ? (
        <div className="text-xs text-slate-500"><Loader2 size={12} className="inline animate-spin" /> Loading…</div>
      ) : filtered.length === 0 ? (
        <div className="text-xs text-slate-500 py-6 text-center bg-slate-50 rounded-lg">No tasks{filter !== 'all' ? ' in this status' : ''}.</div>
      ) : filtered.map((t) => (
        editing && editing.id === t.id ? (
          <TaskForm key={t.id} initial={t} onSave={saveTask} onCancel={() => setEditing(null)} />
        ) : (
          <div key={t.id} className="rounded-lg border border-slate-200 bg-white p-3" data-testid={`task-row-${t.id}`}>
            <div className="flex items-start gap-2">
              <button onClick={() => canEdit && toggleDone(t)} disabled={!canEdit}
                data-testid={`task-toggle-${t.id}`}
                className={`mt-0.5 w-4 h-4 rounded border ${t.status === 'done' ? 'bg-emerald-500 border-emerald-500 text-white' : 'border-slate-300'} flex items-center justify-center shrink-0`}>
                {t.status === 'done' && <Check size={11} />}
              </button>
              <div className="flex-1 min-w-0">
                <div className={`text-sm font-medium ${t.status === 'done' ? 'line-through text-slate-400' : 'text-slate-900'}`}>{t.title}</div>
                <div className="flex items-center gap-2 mt-1 flex-wrap">
                  <PriorityBadge value={t.priority} />
                  {t.due_date && (
                    <span className={`text-[11px] inline-flex items-center gap-1 ${isOverdue(t.due_date, t.status) ? 'text-[#7a1f33] font-semibold' : 'text-slate-500'}`}>
                      <Calendar size={10} /> {fmtDate(t.due_date)}{isOverdue(t.due_date, t.status) ? ' · overdue' : ''}
                    </span>
                  )}
                  <span className="text-[11px] text-slate-400">{t.status.replace('_', ' ')}</span>
                </div>
                {t.description && <p className="mt-2 text-xs text-slate-600 whitespace-pre-wrap">{t.description}</p>}
              </div>
              {canEdit && (
                <div className="flex gap-0.5 shrink-0">
                  <button onClick={() => setEditing(t)} data-testid={`task-edit-${t.id}`} className="p-1 rounded text-slate-400 hover:text-brand-blue hover:bg-slate-100"><Pencil size={11} /></button>
                  <button onClick={() => remove(t)} data-testid={`task-delete-${t.id}`} className="p-1 rounded text-slate-400 hover:text-brand-red hover:bg-slate-100"><Trash2 size={11} /></button>
                </div>
              )}
            </div>
          </div>
        )
      ))}
    </div>
  );
}

function PriorityBadge({ value }) {
  const map = {
    low:  'bg-slate-100 text-slate-600',
    med:  'bg-[#fbf3df] text-[#8c6a1a]',
    high: 'bg-[#fbeadf] text-[#a8480f]',
  };
  return <span className={`text-[10px] uppercase tracking-wider font-semibold px-1.5 py-0.5 rounded-full ${map[value] || map.med}`}>{value}</span>;
}

function TaskForm({ initial, onSave, onCancel }) {
  const [f, setF] = useState({
    title: initial?.title || '',
    description: initial?.description || '',
    due_date: initial?.due_date || '',
    priority: initial?.priority || 'med',
    status: initial?.status || 'open',
  });
  const [saving, setSaving] = useState(false);
  const submit = async (e) => {
    e?.preventDefault();
    if (!f.title.trim()) return;
    setSaving(true);
    try { await onSave({ ...f, due_date: f.due_date || null }); }
    finally { setSaving(false); }
  };
  return (
    <form onSubmit={submit} className="rounded-lg border border-[#e6d99c] bg-[#fbf3df]/40 p-3 space-y-2" data-testid="task-form">
      <input autoFocus value={f.title} onChange={(e) => setF({ ...f, title: e.target.value })}
        placeholder="Task title" data-testid="task-title"
        className="w-full px-2 py-1.5 text-sm border border-slate-300 rounded bg-white" />
      <textarea value={f.description} onChange={(e) => setF({ ...f, description: e.target.value })}
        placeholder="Description (optional)" rows={2} data-testid="task-description"
        className="w-full px-2 py-1.5 text-xs border border-slate-300 rounded bg-white" />
      <div className="flex gap-2 flex-wrap">
        <input type="date" value={f.due_date || ''} onChange={(e) => setF({ ...f, due_date: e.target.value })}
          data-testid="task-due" className="px-2 py-1 text-xs border border-slate-300 rounded bg-white" />
        <select value={f.priority} onChange={(e) => setF({ ...f, priority: e.target.value })}
          data-testid="task-priority" className="px-2 py-1 text-xs border border-slate-300 rounded bg-white">
          <option value="low">Low</option><option value="med">Medium</option><option value="high">High</option>
        </select>
        <select value={f.status} onChange={(e) => setF({ ...f, status: e.target.value })}
          data-testid="task-status" className="px-2 py-1 text-xs border border-slate-300 rounded bg-white">
          <option value="open">Open</option><option value="in_progress">In progress</option>
          <option value="done">Done</option><option value="cancelled">Cancelled</option>
        </select>
      </div>
      <div className="flex justify-end gap-1">
        <button type="button" onClick={onCancel} className="text-xs px-3 py-1 rounded border border-slate-300 bg-white">Cancel</button>
        <button type="submit" disabled={saving} data-testid="task-save"
          className="text-xs px-3 py-1 rounded bg-[#8c6a1a] text-white font-medium disabled:opacity-60">
          {saving ? <Loader2 size={11} className="inline animate-spin" /> : 'Save'}
        </button>
      </div>
    </form>
  );
}

// ────────────────────── Notes panel ──────────────────────
function NotesPanel({ supplierId, canEdit, onChanged }) {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [draft, setDraft] = useState('');
  const [saving, setSaving] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [editValue, setEditValue] = useState('');
  const user = getUser();

  const load = async () => {
    setLoading(true);
    try {
      const { data } = await api.get(`/suppliers/${supplierId}/notes`);
      setItems(data || []);
    } catch (e) { toast.error(apiError(e)); }
    finally { setLoading(false); }
  };
  useEffect(() => { load(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [supplierId]);

  const add = async () => {
    if (!draft.trim()) return;
    setSaving(true);
    try {
      await api.post(`/suppliers/${supplierId}/notes`, { body_md: draft.trim() });
      toast.success('Note added'); setDraft(''); await load(); onChanged?.();
    } catch (e) { toast.error(apiError(e)); }
    finally { setSaving(false); }
  };
  const saveEdit = async (id) => {
    try {
      await api.patch(`/suppliers/notes/${id}`, { body_md: editValue.trim() });
      toast.success('Note updated'); setEditingId(null); await load();
    } catch (e) { toast.error(apiError(e)); }
  };
  const remove = async (n) => {
    try {
      await api.delete(`/suppliers/notes/${n.id}`);
      toast.success('Note deleted'); await load(); onChanged?.();
    } catch (e) { toast.error(apiError(e)); }
  };

  return (
    <div className="space-y-3" data-testid="notes-panel">
      {canEdit && (
        <div className="rounded-lg border border-[#b9d2ec] bg-[#e6eff9]/40 p-2.5">
          <textarea value={draft} onChange={(e) => setDraft(e.target.value)}
            placeholder="Write a note… (Markdown supported)" rows={3}
            data-testid="note-draft"
            className="w-full px-2 py-1.5 text-sm border border-slate-300 rounded bg-white" />
          <div className="flex justify-end mt-2">
            <button onClick={add} disabled={saving || !draft.trim()} data-testid="note-add"
              className="text-xs px-3 py-1.5 rounded bg-[#1e4a8c] text-white font-medium disabled:opacity-60 inline-flex items-center gap-1">
              {saving ? <Loader2 size={11} className="animate-spin" /> : <Plus size={11} />} Add note
            </button>
          </div>
        </div>
      )}
      {loading ? (
        <div className="text-xs text-slate-500"><Loader2 size={12} className="inline animate-spin" /> Loading…</div>
      ) : items.length === 0 ? (
        <div className="text-xs text-slate-500 py-6 text-center bg-slate-50 rounded-lg">No notes yet.</div>
      ) : items.map((n) => {
        const mine = n.created_by === user?.id;
        const editable = canEdit || mine;
        return (
          <div key={n.id} className="rounded-lg border border-slate-200 bg-white p-3" data-testid={`note-row-${n.id}`}>
            <div className="flex items-start gap-2">
              <div className="w-6 h-6 rounded-full bg-slate-100 text-slate-600 text-[10px] font-semibold flex items-center justify-center shrink-0">{initials(n.created_by_name)}</div>
              <div className="flex-1 min-w-0">
                <div className="text-xs text-slate-500">
                  <span className="font-medium text-slate-700">{n.created_by_name || 'Unknown'}</span> · {fmtDate(n.created_at)}
                </div>
                {editingId === n.id ? (
                  <div className="mt-1">
                    <textarea value={editValue} onChange={(e) => setEditValue(e.target.value)} rows={3}
                      className="w-full px-2 py-1.5 text-sm border border-slate-300 rounded bg-white" />
                    <div className="flex justify-end gap-1 mt-1">
                      <button onClick={() => setEditingId(null)} className="text-xs px-2 py-1 rounded border border-slate-300 bg-white">Cancel</button>
                      <button onClick={() => saveEdit(n.id)} className="text-xs px-2 py-1 rounded bg-[#1e4a8c] text-white">Save</button>
                    </div>
                  </div>
                ) : (
                  <p className="text-sm text-slate-800 whitespace-pre-wrap mt-0.5">{n.body_md}</p>
                )}
              </div>
              {editable && editingId !== n.id && (
                <div className="flex gap-0.5 shrink-0">
                  <button onClick={() => { setEditingId(n.id); setEditValue(n.body_md); }} data-testid={`note-edit-${n.id}`}
                    className="p-1 rounded text-slate-400 hover:text-brand-blue hover:bg-slate-100"><Pencil size={11} /></button>
                  <button onClick={() => remove(n)} data-testid={`note-delete-${n.id}`}
                    className="p-1 rounded text-slate-400 hover:text-brand-red hover:bg-slate-100"><Trash2 size={11} /></button>
                </div>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ────────────────────── Members panel ──────────────────────
function MembersPanel({ supplierId, canEdit, onChanged }) {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState(null);

  const load = async () => {
    setLoading(true);
    try {
      const { data } = await api.get(`/suppliers/${supplierId}/members`);
      setItems(data || []);
    } catch (e) { toast.error(apiError(e)); }
    finally { setLoading(false); }
  };
  useEffect(() => { load(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [supplierId]);

  const save = async (form) => {
    try {
      if (editing === 'new') {
        await api.post(`/suppliers/${supplierId}/members`, form);
        toast.success('Member added');
      } else {
        await api.patch(`/suppliers/members/${editing.id}`, form);
        toast.success('Member updated');
      }
      setEditing(null); await load(); onChanged?.();
    } catch (e) { toast.error(apiError(e)); }
  };
  const remove = async (m) => {
    try {
      await api.delete(`/suppliers/members/${m.id}`);
      toast.success('Member removed'); await load(); onChanged?.();
    } catch (e) { toast.error(apiError(e)); }
  };

  return (
    <div className="space-y-3" data-testid="members-panel">
      {canEdit && editing !== 'new' && (
        <button onClick={() => setEditing('new')} data-testid="member-add"
          className="inline-flex items-center gap-1 px-3 py-1.5 rounded-lg bg-[#a8480f] text-white text-xs font-medium hover:bg-[#8a3a0c]">
          <Plus size={12} /> Add member
        </button>
      )}
      {editing === 'new' && <MemberForm onSave={save} onCancel={() => setEditing(null)} />}
      {loading ? (
        <div className="text-xs text-slate-500"><Loader2 size={12} className="inline animate-spin" /> Loading…</div>
      ) : items.length === 0 ? (
        <div className="text-xs text-slate-500 py-6 text-center bg-slate-50 rounded-lg">No members linked.</div>
      ) : items.map((m) => (
        editing && editing.id === m.id ? (
          <MemberForm key={m.id} initial={m} onSave={save} onCancel={() => setEditing(null)} />
        ) : (
          <div key={m.id} className="rounded-lg border border-slate-200 bg-white p-3" data-testid={`member-row-${m.id}`}>
            <div className="flex items-start gap-2">
              <div className="w-9 h-9 rounded-full bg-[#fbeadf] text-[#a8480f] text-xs font-semibold flex items-center justify-center shrink-0">{initials(m.name)}</div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-1.5 flex-wrap">
                  <span className="text-sm font-medium text-slate-900">{m.name}</span>
                  {m.is_primary_contact && (
                    <span className="text-[10px] uppercase tracking-wider font-semibold px-1.5 py-0.5 rounded-full bg-[#d8ecdd] text-[#1f7a3f]">Primary</span>
                  )}
                </div>
                {m.role && <div className="text-xs text-slate-500">{m.role}</div>}
                <div className="text-xs text-slate-500 mt-1 space-y-0.5">
                  {m.email && <div className="truncate">{m.email}</div>}
                  {m.phone && <div>{m.phone}</div>}
                </div>
              </div>
              {canEdit && (
                <div className="flex gap-0.5 shrink-0">
                  <button onClick={() => setEditing(m)} data-testid={`member-edit-${m.id}`} className="p-1 rounded text-slate-400 hover:text-brand-blue hover:bg-slate-100"><Pencil size={11} /></button>
                  <button onClick={() => remove(m)} data-testid={`member-delete-${m.id}`} className="p-1 rounded text-slate-400 hover:text-brand-red hover:bg-slate-100"><Trash2 size={11} /></button>
                </div>
              )}
            </div>
          </div>
        )
      ))}
    </div>
  );
}

function MemberForm({ initial, onSave, onCancel }) {
  const [f, setF] = useState({
    name: initial?.name || '', role: initial?.role || '',
    email: initial?.email || '', phone: initial?.phone || '',
    is_primary_contact: !!initial?.is_primary_contact,
  });
  const [saving, setSaving] = useState(false);
  const submit = async (e) => {
    e?.preventDefault();
    if (!f.name.trim()) return;
    setSaving(true);
    try { await onSave(f); } finally { setSaving(false); }
  };
  return (
    <form onSubmit={submit} className="rounded-lg border border-[#e9c0a5] bg-[#fbeadf]/40 p-3 space-y-2" data-testid="member-form">
      <input autoFocus value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })}
        placeholder="Full name" data-testid="member-name"
        className="w-full px-2 py-1.5 text-sm border border-slate-300 rounded bg-white" />
      <input value={f.role} onChange={(e) => setF({ ...f, role: e.target.value })}
        placeholder="Role / title (optional)" data-testid="member-role"
        className="w-full px-2 py-1.5 text-sm border border-slate-300 rounded bg-white" />
      <div className="grid grid-cols-2 gap-2">
        <input value={f.email} onChange={(e) => setF({ ...f, email: e.target.value })}
          placeholder="email@example.com" data-testid="member-email"
          className="w-full px-2 py-1.5 text-xs border border-slate-300 rounded bg-white" />
        <input value={f.phone} onChange={(e) => setF({ ...f, phone: e.target.value })}
          placeholder="Phone" data-testid="member-phone"
          className="w-full px-2 py-1.5 text-xs border border-slate-300 rounded bg-white" />
      </div>
      <label className="inline-flex items-center gap-2 text-xs text-slate-700 cursor-pointer">
        <input type="checkbox" checked={f.is_primary_contact}
          onChange={(e) => setF({ ...f, is_primary_contact: e.target.checked })}
          data-testid="member-primary" className="w-3.5 h-3.5 rounded" />
        Primary contact
      </label>
      <div className="flex justify-end gap-1">
        <button type="button" onClick={onCancel} className="text-xs px-3 py-1 rounded border border-slate-300 bg-white">Cancel</button>
        <button type="submit" disabled={saving} data-testid="member-save"
          className="text-xs px-3 py-1 rounded bg-[#a8480f] text-white font-medium disabled:opacity-60">
          {saving ? <Loader2 size={11} className="inline animate-spin" /> : 'Save'}
        </button>
      </div>
    </form>
  );
}

