export default function SupplierDrawer({ supplier, initialPanel, onClose, onChanged }) {
  const [panel, setPanel] = useState(initialPanel || 'tasks');
  const user = getUser();
  // v160.3.9.29-2c — Migrated to suppliers.edit token.
  const canEdit = useCan()('suppliers', 'edit');
  void user; void WRITE_ROLES;

  useEffect(() => { setPanel(initialPanel || 'tasks'); }, [initialPanel]);
  if (!supplier) return null;
  const theme = PANEL_THEMES[panel] || PANEL_THEMES.tasks;
  const Icon = theme.icon;

  return (
    <Sheet open={!!supplier} onOpenChange={(o) => { if (!o) onClose(); }}>
      <SheetContent side="right" className="w-full sm:max-w-lg p-0 flex flex-col" data-testid="supplier-drawer">
        <SheetHeader className={`${theme.bg} px-5 py-4 border-b border-slate-200`}>
          <div className={`text-[10px] uppercase tracking-[0.16em] font-semibold ${theme.ink} flex items-center gap-1.5`}>
            <Icon size={12} /> {theme.name}
          </div>
          <SheetTitle className="text-lg font-display font-semibold text-slate-900 truncate">
            {supplier.name}
          </SheetTitle>
        </SheetHeader>

        <div className="border-b border-slate-200 flex bg-white">
          {(['tasks', 'notes', 'folders', 'members']).map((k) => {
            const PI = PANEL_THEMES[k].icon;
            const active = panel === k;
            return (
              <button key={k} onClick={() => setPanel(k)} data-testid={`tab-${k}`}
                className={`flex-1 inline-flex items-center justify-center gap-1.5 py-2 text-xs font-medium transition-colors ${
                  active ? `${PANEL_THEMES[k].bg} ${PANEL_THEMES[k].ink}` : 'text-slate-500 hover:bg-slate-50'
                }`}>
                <PI size={12} /> {PANEL_THEMES[k].name}
              </button>
            );
          })}
        </div>

        <div className="flex-1 overflow-y-auto p-5">
          {panel === 'tasks'   && <TasksPanel supplierId={supplier.simpro_supplier_id} canEdit={canEdit} onChanged={onChanged} />}
          {panel === 'notes'   && <NotesPanel supplierId={supplier.simpro_supplier_id} canEdit={canEdit} onChanged={onChanged} />}
          {panel === 'members' && <MembersPanel supplierId={supplier.simpro_supplier_id} canEdit={canEdit} onChanged={onChanged} />}
          {panel === 'folders' && <FoldersPanel supplierId={supplier.simpro_supplier_id} canEdit={canEdit} onChanged={onChanged} />}
        </div>
      </SheetContent>
    </Sheet>
  );
}

// FolderCard — supplier folder with hover-revealed rename + delete affordances.
function FolderCard({ folder, canEdit, onOpen, onRenamed, onDeleted }) {
  const [renaming, setRenaming] = useState(false);
  const [name, setName] = useState(folder.name);
  const [busy, setBusy] = useState(false);

  const saveRename = async () => {
    const next = name.trim();
    if (!next || next === folder.name) { setRenaming(false); setName(folder.name); return; }
    setBusy(true);
    try {
      await api.patch(`/document-library/folders/${folder.id}`, { name: next });
      toast.success('Folder renamed');
      setRenaming(false);
      onRenamed?.({ ...folder, name: next });
    } catch (e) { toast.error(apiError(e)); setName(folder.name); }
    finally { setBusy(false); }
  };

  const onKey = (e) => {
    if (e.key === 'Enter') { e.preventDefault(); saveRename(); }
    else if (e.key === 'Escape') { e.preventDefault(); setRenaming(false); setName(folder.name); }
  };

  const handleDelete = async () => {
    const fileLine = folder.file_count
      ? `\n\nThis will also delete the ${folder.file_count} file${folder.file_count === 1 ? '' : 's'} inside it.`
      : '';
    if (!window.confirm(`Delete folder "${folder.name}"?${fileLine}`)) return;
    setBusy(true);
    try {
      await api.delete(`/document-library/folders/${folder.id}`);
      toast.success(`Deleted "${folder.name}"`);
      onDeleted?.(folder);
    } catch (e) { toast.error(apiError(e)); }
    finally { setBusy(false); }
  };

  if (renaming) {
    return (
      <div className="rounded-lg border border-[#c8bce0] bg-[#ece6f4]/60 p-3" data-testid={`supplier-folder-rename-${folder.id}`}>
        <input autoFocus value={name} maxLength={80}
          onChange={(e) => setName(e.target.value)}
          onKeyDown={onKey}
          onBlur={saveRename}
          data-testid={`folder-rename-input-${folder.id}`}
          className="w-full px-2 py-1.5 text-xs font-semibold border border-slate-300 rounded bg-white" />
        <div className="text-[10px] text-slate-500 mt-1">Press Enter to save · Esc to cancel</div>
      </div>
    );
  }

  return (
    <div className="group relative rounded-lg border border-slate-200 bg-[#ece6f4]/40 hover:shadow-sm transition-shadow"
      data-testid={`supplier-folder-${folder.id}`}>
      <button onClick={() => onOpen(folder)} disabled={busy}
        data-testid={`supplier-folder-open-${folder.id}`}
        className="w-full p-3 text-left disabled:opacity-60">
        <FolderOpen size={20} className="text-[#4f3a8c] mb-1.5" />
        <div className="text-xs font-semibold text-slate-900 line-clamp-2 leading-snug min-h-[2.25rem] pr-12">{folder.name}</div>
        <div className="text-[10px] text-slate-500 mt-1">{folder.file_count} file{folder.file_count === 1 ? '' : 's'}</div>
      </button>
      {canEdit && !folder.is_system && (
        <div className="absolute top-1.5 right-1.5 flex items-center gap-0.5 opacity-0 group-hover:opacity-100 focus-within:opacity-100 transition-opacity">
          <button onClick={(e) => { e.stopPropagation(); setRenaming(true); }} disabled={busy}
            data-testid={`folder-rename-${folder.id}`}
            title="Rename folder" aria-label="Rename folder"
            className="w-7 h-7 rounded-md bg-white/80 backdrop-blur text-slate-600 hover:text-slate-900 hover:bg-white border border-slate-200 flex items-center justify-center">
            <Pencil size={11} />
          </button>
          <button onClick={(e) => { e.stopPropagation(); handleDelete(); }} disabled={busy}
            data-testid={`folder-delete-${folder.id}`}
            title="Delete folder" aria-label="Delete folder"
            className="w-7 h-7 rounded-md bg-white/80 backdrop-blur text-rose-600 hover:text-rose-700 hover:bg-rose-50 border border-rose-200 flex items-center justify-center">
            <Trash2 size={11} />
          </button>
        </div>
      )}
    </div>
  );
}

// ────────────────────── Folders panel + file sub-view ──────────────────────
function FoldersPanel({ supplierId, canEdit, onChanged }) {
  const [folders, setFolders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);
  const [name, setName] = useState('');
  const [saving, setSaving] = useState(false);
  const [openFolder, setOpenFolder] = useState(null);

  const load = async () => {
    setLoading(true);
    try {
      const { data } = await api.get(`/suppliers/${supplierId}/folders`);
      setFolders(data || []);
    } catch (e) { toast.error(apiError(e)); }
    finally { setLoading(false); }
  };
  useEffect(() => { load(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [supplierId]);

  const createFolder = async (e) => {
    e?.preventDefault();
    if (!name.trim()) return;
    setSaving(true);
    try {
      await api.post(`/suppliers/${supplierId}/folders`, { name: name.trim() });
      toast.success('Folder created');
      setName(''); setCreating(false);
      await load(); onChanged?.();
    } catch (err) { toast.error(apiError(err)); }
    finally { setSaving(false); }
  };

  if (openFolder) {
    return <FolderFiles folder={openFolder} canEdit={canEdit}
      onBack={() => { setOpenFolder(null); load(); onChanged?.(); }} />;
  }

  return (
    <div className="space-y-3" data-testid="folders-panel">
      <div className="flex items-center justify-between">
        <div className="text-xs text-slate-500">{folders.length} folder{folders.length === 1 ? '' : 's'}</div>
        {canEdit && !creating && (
          <button onClick={() => setCreating(true)} data-testid="folder-add"
            className="inline-flex items-center gap-1 px-3 py-1.5 rounded-lg bg-[#4f3a8c] text-white text-xs font-medium hover:bg-[#3f2e70]">
            <Plus size={12} /> New folder
          </button>
        )}
      </div>
      {creating && (
        <form onSubmit={createFolder} className="rounded-lg border border-[#e2dcef] bg-[#ece6f4]/40 p-2.5 flex gap-2">
          <input autoFocus value={name} onChange={(e) => setName(e.target.value)}
            placeholder="Folder name" maxLength={80} data-testid="folder-create-input"
            className="flex-1 px-2 py-1.5 text-sm border border-slate-300 rounded bg-white" />
          <button type="submit" disabled={saving} data-testid="folder-create-save"
            className="text-xs px-3 py-1.5 rounded bg-[#4f3a8c] text-white font-medium disabled:opacity-60">
            {saving ? <Loader2 size={11} className="inline animate-spin" /> : 'Create'}
          </button>
          <button type="button" onClick={() => { setCreating(false); setName(''); }} className="text-xs px-3 py-1.5 rounded border border-slate-300 bg-white">Cancel</button>
        </form>
      )}
      {loading ? (
        <div className="text-xs text-slate-500"><Loader2 size={12} className="inline animate-spin" /> Loading…</div>
      ) : folders.length === 0 ? (
        <div className="text-xs text-slate-500 py-6 text-center bg-slate-50 rounded-lg">
          No folders linked to this supplier yet.
        </div>
      ) : (
        <div className="grid grid-cols-3 gap-2">
          {folders.map((f) => (
            <FolderCard key={f.id} folder={f} canEdit={canEdit}
              onOpen={() => setOpenFolder(f)}
              onRenamed={(next) => { setFolders((prev) => prev.map((x) => (x.id === next.id ? { ...x, name: next.name } : x))); onChanged?.(); }}
              onDeleted={() => { load(); onChanged?.(); }} />
          ))}
        </div>
      )}
    </div>
  );
}

function FolderFiles({ folder, canEdit, onBack }) {
  const [files, setFiles] = useState([]);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [renaming, setRenaming] = useState(false);
  const [name, setName] = useState(folder.name);
  const fileInputRef = React.useRef(null);

  const load = async () => {
    setLoading(true);
    try {
      const { data } = await api.get(`/document-library/folders/${folder.id}/files`);
      setFiles(data || []);
    } catch (e) { toast.error(apiError(e)); }
    finally { setLoading(false); }
  };
  useEffect(() => { load(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [folder.id]);

  const saveRename = async () => {
    const next = name.trim();
    if (!next || next === folder.name) { setRenaming(false); setName(folder.name); return; }
    try {
      await api.patch(`/document-library/folders/${folder.id}`, { name: next });
      folder.name = next; // mutate so the back-button list refresh shows new name
      toast.success('Folder renamed');
      setRenaming(false);
    } catch (e) { toast.error(apiError(e)); setName(folder.name); }
  };

  const deleteFolder = async () => {
    const fileLine = files.length
      ? `\n\nThis will also delete the ${files.length} file${files.length === 1 ? '' : 's'} inside it.`
      : '';
    if (!window.confirm(`Delete folder "${folder.name}"?${fileLine}`)) return;
    try {
      await api.delete(`/document-library/folders/${folder.id}`);
      toast.success(`Deleted "${folder.name}"`);
      onBack();
    } catch (e) { toast.error(apiError(e)); }
  };

  const upload = async (fileList) => {
    if (!fileList?.length) return;
    setUploading(true);
    const form = new FormData();
    for (const f of fileList) form.append('files', f);
    try {
      const { data } = await api.post(`/document-library/folders/${folder.id}/files`, form);
      const ok = (data.saved || []).length;
      if (ok) toast.success(`${ok} file${ok === 1 ? '' : 's'} uploaded`);
      (data.rejected || []).forEach((r) => toast.error(`${r.filename}: ${r.reason}`));
      await load();
    } catch (e) { toast.error(apiError(e)); }
    finally { setUploading(false); }
  };

  const remove = async (f) => {
    try {
      await api.delete(`/document-library/files/${f.id}`);
      toast.success('File deleted'); await load();
    } catch (e) { toast.error(apiError(e)); }
  };

  return (
    <div className="space-y-3" data-testid="folder-files-view">
      <div className="flex items-center justify-between">
        <button onClick={onBack} data-testid="folder-back"
          className="inline-flex items-center gap-1 text-xs text-slate-600 hover:text-slate-900">
          ← Back to folders
        </button>
        {canEdit && (
          <>
            <input ref={fileInputRef} type="file" multiple className="hidden"
              accept=".pdf,.doc,.docx,.xls,.xlsx,.png,.jpg,.jpeg,.txt,.csv"
              onChange={(e) => { upload(Array.from(e.target.files || [])); e.target.value = ''; }}
              data-testid="folder-file-input" />
            <button onClick={() => fileInputRef.current?.click()} disabled={uploading}
              data-testid="folder-upload"
              className="inline-flex items-center gap-1 px-3 py-1.5 rounded-lg bg-[#4f3a8c] text-white text-xs font-medium hover:bg-[#3f2e70] disabled:opacity-60">
              {uploading ? <Loader2 size={11} className="animate-spin" /> : <Plus size={11} />} Upload
            </button>
          </>
        )}
      </div>
      <div className="flex items-center gap-2">
        {renaming ? (
          <input autoFocus value={name} maxLength={80}
            onChange={(e) => setName(e.target.value)}
            onBlur={saveRename}
            onKeyDown={(e) => {
              if (e.key === 'Enter') { e.preventDefault(); saveRename(); }
              else if (e.key === 'Escape') { e.preventDefault(); setRenaming(false); setName(folder.name); }
            }}
            data-testid="folder-rename-input"
            className="flex-1 px-2 py-1.5 text-sm font-display font-semibold text-slate-900 border border-slate-300 rounded bg-white" />
        ) : (
          <div className="text-sm font-display font-semibold text-slate-900 flex-1">{folder.name}</div>
        )}
        {canEdit && !renaming && !folder.is_system && (
          <>
            <button onClick={() => setRenaming(true)} data-testid="folder-header-rename"
              title="Rename folder" aria-label="Rename folder"
              className="p-1.5 rounded text-slate-500 hover:text-slate-900 hover:bg-slate-100">
              <Pencil size={12} />
            </button>
            <button onClick={deleteFolder} data-testid="folder-header-delete"
              title="Delete folder" aria-label="Delete folder"
              className="p-1.5 rounded text-rose-600 hover:text-rose-700 hover:bg-rose-50">
              <Trash2 size={12} />
            </button>
          </>
        )}
      </div>
      {loading ? (
        <div className="text-xs text-slate-500"><Loader2 size={12} className="inline animate-spin" /> Loading…</div>
      ) : files.length === 0 ? (
        <div className="text-xs text-slate-500 py-6 text-center bg-slate-50 rounded-lg">No files yet.</div>
      ) : (
        <div className="space-y-1.5">
          {files.map((f) => (
            <div key={f.id} className="flex items-center gap-2 px-3 py-2 rounded-lg border border-slate-200 bg-white" data-testid={`file-row-${f.id}`}>
              <FolderOpen size={14} className="text-slate-400" />
              <div className="flex-1 min-w-0">
                <div className="text-sm font-medium text-slate-900 truncate">{f.filename}</div>
                <div className="text-[10px] text-slate-500">{Math.round((f.size || 0) / 1024)} KB</div>
              </div>
              {canEdit && (
                <button onClick={() => remove(f)} data-testid={`file-delete-${f.id}`}
                  className="p-1 rounded text-slate-400 hover:text-brand-red hover:bg-slate-100">
                  <Trash2 size={11} />
                </button>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// v96.2 — Stuck-SW self-heal.
//
// Some Paneltec admins hit a state where the deployed bundle ships new
// UI (e.g. the Fluent icon migration in v96) yet their browser keeps
// rendering the previous build. Root cause is always the same: an old
// Service Worker is still controlling the tab and serving cached chunks.
//
// This module is invoked once from <AppShell> on mount. It:
//   1. Asks the backend what CACHE_VERSION it expects (single source of
//      truth = the SW file on disk).
//   2. postMessages the controlling SW with a MessageChannel asking
//      `GET_VERSION`.
//   3. If the SW's version doesn't match the backend's, OR no SW is
//      controlling despite a registration existing (which happens after a
//      version skew during install), it nukes every cache, unregisters
//      every SW, and force-reloads the page exactly once per browser
//      session (session-storage guard).
//
// Idempotent + best-effort: any thrown error is swallowed so a bad probe
// never breaks the app.

import { API_BASE } from '@/lib/api';
import api from '@/lib/api';

const GUARD_KEY = 'paneltec_sw_self_heal_done';
const PROBE_TIMEOUT_MS = 1500;

async function probeSwVersion() {
  if (!('serviceWorker' in navigator)) return null;
  const controller = navigator.serviceWorker.controller;
  if (!controller) return null;
  return await new Promise((resolve) => {
    const channel = new MessageChannel();
    const timer = setTimeout(() => resolve(null), PROBE_TIMEOUT_MS);
    channel.port1.onmessage = (event) => {
      clearTimeout(timer);
      resolve(event?.data?.version || null);
    };
    try {
      controller.postMessage({ type: 'GET_VERSION' }, [channel.port2]);
    } catch (_) {
      clearTimeout(timer);
      resolve(null);
    }
  });
}

async function fetchExpectedVersion() {
  try {
    const res = await fetch(`${API_BASE}/health/version`, { credentials: 'omit' });
    if (!res.ok) return null;
    const data = await res.json();
    return data?.cache_version || null;
  } catch (_) {
    return null;
  }
}

async function nukeAndReload() {
  try { sessionStorage.setItem(GUARD_KEY, '1'); } catch (_) { /* noop */ }
  try {
    if ('serviceWorker' in navigator) {
      const regs = await navigator.serviceWorker.getRegistrations();
      await Promise.all(regs.map((r) => r.unregister().catch(() => false)));
    }
  } catch (_) { /* noop */ }
  try {
    if ('caches' in window) {
      const keys = await caches.keys();
      await Promise.all(keys.map((k) => caches.delete(k).catch(() => false)));
    }
  } catch (_) { /* noop */ }
  // Defer one tick so any pending side-effects flush.
  setTimeout(() => window.location.reload(), 0);
}

export async function runSwVersionGuard() {
  if (typeof window === 'undefined') return;
  if (!('serviceWorker' in navigator)) return;
  try {
    if (sessionStorage.getItem(GUARD_KEY) === '1') return;
  } catch (_) { /* sessionStorage unavailable — proceed once anyway */ }

  // In DEV mode `registerServiceWorker` already unregisters stale prod
  // SWs on every load — no further action needed here.
  if (process.env.NODE_ENV !== 'production') return;

  const [swVersion, expected] = await Promise.all([
    probeSwVersion(),
    fetchExpectedVersion(),
  ]);

  if (!expected || expected === 'unknown') return; // backend can't read — bail
  if (swVersion && swVersion === expected) return; // happy path

  // Either no SW is controlling (cold load — let the install handler do
  // its thing) or there IS a mismatch. Only force-heal on actual mismatch
  // so we don't loop-reload first-time visitors.
  if (swVersion && swVersion !== expected) {
    console.warn(`[paneltec-sw] version mismatch — sw=${swVersion} expected=${expected}. Self-healing.`);
    await nukeAndReload();
  }
}

// Phase 3.21 Item 5 — Force-refresh signal poll. Separate from the
// version-mismatch self-heal so an admin can broadcast a refresh
// without bumping the SW version (e.g. critical CSS hotfix).
//
// Persistence: localStorage so we DON'T loop-reload across sessions.
// First-read seeds with the current server signal so a returning user
// doesn't immediately reload on first poll.
const SIGNAL_KEY = 'paneltec_last_seen_force_refresh';

async function fetchSignal() {
  try {
    // Use the shared api wrapper which already attaches the JWT.
    const res = await api.get('/settings/force-refresh-signal');
    return res?.data?.signal_at || null;
  } catch (_) { return null; }
}

export async function runForceRefreshSignalCheck() {
  if (typeof window === 'undefined') return;
  const signal = await fetchSignal();
  if (!signal) return;
  let lastSeen = null;
  try { lastSeen = localStorage.getItem(SIGNAL_KEY); } catch (_) { /* noop */ }
  if (!lastSeen) {
    // First read this browser — seed without reloading so returning
    // users don't trigger on a historical signal.
    try { localStorage.setItem(SIGNAL_KEY, signal); } catch (_) { /* noop */ }
    return;
  }
  if (signal > lastSeen) {
    // eslint-disable-next-line no-console
    console.warn('[paneltec-sw] force-refresh-all signal received. Reloading.');
    try { localStorage.setItem(SIGNAL_KEY, signal); } catch (_) { /* noop */ }
    await nukeAndReload();
  }
}

// Kick off a 60s heartbeat once on first import so the poll keeps
// running even while the user is sitting on a long-lived screen.
if (typeof window !== 'undefined' && !window.__paneltec_force_refresh_poll_started) {
  window.__paneltec_force_refresh_poll_started = true;
  setInterval(() => { runForceRefreshSignalCheck(); }, 60_000);
  // Fire once shortly after AppShell mounts so the first poll isn't 60s away.
  setTimeout(() => { runForceRefreshSignalCheck(); }, 5_000);
}

// v160.3.9.58.13.39 — Capture tile density hook.
// v160.3.9.58.13.47 — Fire-and-forget telemetry on every setMode +
//   one initial `resolved_from_auto` ping per (page, session).
//   Debounced 500 ms so rapid A/B/A clicks don't spam the endpoint.
//   Silent on failure — analytics MUST NOT surface toasts or block
//   the UX. Non-'auto' persisted modes short-circuit the initial
//   ping so we only capture what auto actually resolved to.
//
// Central density state for Capture list pages. Manages the
// user-facing "Auto / Compact / Comfortable / Spacious" segmented
// control in `CaptureListToolbar` and derives the effective grid
// classes + card min-height + subtitle visibility that
// `GroupedTilesView`, `CaptureCardGrid`, and `CaptureCard` consume.
//
// Persistence: per-page localStorage key `captureDensity:<pageKey>`.
// Users tend to browse Incidents in Comfortable but scan a big
// Sign-In register in Compact — per-page is more useful than global.
//
// Auto-density thresholds (fired when mode === 'auto'):
//   ·  <12 items  → Spacious   (breathing room; sparse days)
//   · 12–48 items → Comfortable (default; current pre-v58.13.39 look)
//   · >48 items   → Compact    (dense; scanning long registers)
//
// Grid classes are per-mode Tailwind strings; card min-heights are
// px values (so callers can pass them as inline `min-h-[Xpx]`
// classes or as inline styles). Subtitle lines: 0 = hidden,
// 1 = line-clamp-1, 2 = line-clamp-2.

import { useEffect, useRef, useState, useMemo, useCallback } from 'react';
import axios from 'axios';

const MODES = ['auto', 'compact', 'comfortable', 'spacious'];
const TELEMETRY_DEBOUNCE_MS = 500;
const TELEMETRY_URL = `${process.env.REACT_APP_BACKEND_URL || ''}/api/metrics/capture-density`;

// v58.13.47 — fire-and-forget POST. Never awaits, never throws,
// never surfaces a toast. Timeout at 2 s so a slow endpoint can't
// pile up in-flight requests. Uses a bare axios instance (NOT the
// authed `/lib/api` client) so this call can't accidentally trip
// a 401-redirect interceptor.
function _emit(payload) {
  if (typeof window === 'undefined') return;
  if (!TELEMETRY_URL) return;
  try {
    axios.post(TELEMETRY_URL, payload, {
      timeout: 2000,
      // eslint-disable-next-line no-empty-function
    }).catch(() => {});
  } catch { /* never throws */ }
}

const SPEC = {
  spacious: {
    gridClass:
      'grid gap-3 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4',
    cardMinH: '96px',
    subtitleLines: 2,
  },
  comfortable: {
    gridClass:
      'grid gap-2.5 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-5 2xl:grid-cols-6',
    cardMinH: '96px',
    subtitleLines: 1,
  },
  compact: {
    gridClass:
      'grid gap-1.5 sm:grid-cols-3 lg:grid-cols-5 xl:grid-cols-7 2xl:grid-cols-8',
    cardMinH: '64px',
    subtitleLines: 0,
  },
};

/**
 * @param {number} itemCount
 * @returns {'compact'|'comfortable'|'spacious'}
 */
export function autoModeForCount(itemCount) {
  const n = Number(itemCount) || 0;
  if (n < 12) return 'spacious';
  if (n > 48) return 'compact';
  return 'comfortable';
}

function _lsKey(pageKey) {
  return `captureDensity:${pageKey || 'default'}`;
}

/**
 * @param {string} pageKey
 * @param {number} itemCount
 */
export default function useCaptureDensity(pageKey, itemCount) {
  const [mode, _setMode] = useState('auto');
  // v58.13.47 — debounce + initial-ping tracking.
  const debounceRef = useRef(null);
  const initialPingSentRef = useRef(false);

  // Read persisted mode on mount (SSR-safe: localStorage lazy-check).
  useEffect(() => {
    try {
      const raw = typeof window !== 'undefined'
        ? window.localStorage.getItem(_lsKey(pageKey)) : null;
      if (raw && MODES.includes(raw)) _setMode(raw);
    } catch { /* ignore quota / disabled */ }
  }, [pageKey]);

  const setMode = useCallback((next) => {
    if (!MODES.includes(next)) return;
    // Grab the previous value BEFORE React batches the update so
    // the telemetry payload can report the transition.
    const prev = mode;
    _setMode(next);
    try {
      if (typeof window !== 'undefined') {
        window.localStorage.setItem(_lsKey(pageKey), next);
      }
    } catch { /* ignore */ }
    // v58.13.47 — debounced telemetry ping. No-op when the mode
    // didn't actually change (idempotent click on the same button).
    if (next === prev) return;
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      _emit({
        page: pageKey || 'default',
        mode: next,
        previous_mode: prev,
        effective_mode: next === 'auto' ? autoModeForCount(itemCount) : next,
        item_count: Number(itemCount) || 0,
        ts: Date.now(),
        event: 'setMode',
      });
    }, TELEMETRY_DEBOUNCE_MS);
  }, [pageKey, mode, itemCount]);

  const effectiveMode = mode === 'auto' ? autoModeForCount(itemCount) : mode;
  const spec = SPEC[effectiveMode] || SPEC.comfortable;

  // v58.13.47 — one-shot initial ping capturing what `auto`
  // actually resolved to (or what the persisted non-auto choice
  // is). Fires exactly once per hook instance, only after
  // `itemCount` has been non-zero at least once (avoids emitting
  // during the initial `items = []` render pass while the list is
  // still loading).
  useEffect(() => {
    if (initialPingSentRef.current) return;
    if (!itemCount) return;
    initialPingSentRef.current = true;
    _emit({
      page: pageKey || 'default',
      mode,
      effective_mode: effectiveMode,
      item_count: Number(itemCount) || 0,
      ts: Date.now(),
      event: 'resolved_from_auto',
    });
  }, [pageKey, mode, effectiveMode, itemCount]);

  return useMemo(() => ({
    mode,
    effectiveMode,
    setMode,
    gridClass: spec.gridClass,
    cardMinH: spec.cardMinH,
    subtitleLines: spec.subtitleLines,
  }), [mode, effectiveMode, setMode, spec]);
}

// Phase 4.7.3 — Comms Safe Mode admin page.
//
// Shows the current effective mode (env-locked vs org-overridable), a toggle
// (admin only, disabled when env locks it), and a chronological list of the
// most recent blocked email/SMS messages so the admin can audit what would
// have been delivered.
import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { toast } from 'sonner';
import { Zap, Mail, MessageSquare, Lock, ChevronRight } from 'lucide-react';
import api, { apiError } from '../lib/api';
import { PageHeader } from '../components/capture/Ui';
import HowThisWorks from '../components/help/HowThisWorks';

const CHANNEL_ICON = { email: Mail, sms: MessageSquare };

export default function CommsSafeMode() {
  const [status, setStatus] = useState(null);
  const [blocked, setBlocked] = useState({ items: [], count: 0 });
  const [channelF, setChannelF] = useState('');
  const [busy, setBusy] = useState(false);

  const load = async () => {
    try {
      const [s, b] = await Promise.all([
        api.get('/admin/comms-safe-mode/status'),
        api.get(`/admin/comms-outbox-blocked${channelF ? `?channel=${channelF}` : ''}`),
      ]);
      setStatus(s.data);
      setBlocked(b.data);
    } catch (e) { toast.error(apiError(e)); }
  };
  useEffect(() => { load(); /* eslint-disable-next-line */ }, [channelF]);

  const toggle = async (mode) => {
    if (status?.env_locked) {
      toast.error('Locked by env var — contact your operator.');
      return;
    }
    setBusy(true);
    try {
      await api.patch('/admin/comms-safe-mode', { mode });
      toast.success(`Comms Safe Mode set to ${mode.toUpperCase()}`);
      await load();
    } catch (e) {
      // v58.7.1 — Defensive: if the backend rejects with 423 (env
      // locked between load and click) surface the same toast as the
      // pre-check above so the user isn't left wondering.
      const code = e?.response?.status;
      if (code === 423) toast.error('Locked by env var — contact your operator.');
      else toast.error(apiError(e));
    }
    finally { setBusy(false); }
  };

  const eff = status?.effective || 'on';
  const locked = !!status?.env_locked;

  return (
    <div data-testid="comms-safe-mode-page">
      <PageHeader title="Comms Safe Mode" subtitle="Outbound email and SMS kill switch." />

      <HowThisWorks schematicSlug="comms_safe_mode" />

      <div className={`mb-6 rounded-2xl border p-5 flex items-start gap-4 ${
        eff === 'on'
          ? 'bg-amber-50 border-amber-200'
          : 'bg-emerald-50 border-emerald-200'
      }`}>
        <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${
          eff === 'on' ? 'bg-amber-200 text-amber-800' : 'bg-emerald-200 text-emerald-800'
        }`}>
          <Zap size={20} className={eff === 'on' ? 'fill-amber-600 text-amber-600' : ''} />
        </div>
        <div className="flex-1">
          <div className="font-display text-lg font-semibold text-slate-900">
            Safe Mode is {eff === 'on' ? 'ON' : 'OFF'}
          </div>
          <div className="text-sm text-slate-600 mt-1">
            {eff === 'on'
              ? 'Outbound email and SMS are being CAPTURED for review but NOT delivered. Toggle off when you\'re ready to send to real recipients.'
              : 'Outbound email and SMS are being delivered normally via M365 / TextMagic.'}
          </div>
          {locked && (
            <div className="mt-2 inline-flex items-center gap-1.5 text-xs font-semibold text-slate-700 bg-slate-200 px-2 py-0.5 rounded-md" data-testid="env-lock-pill">
              <Lock size={11} /> Locked by env var (operator-controlled)
            </div>
          )}
          {/* v58.7.1 — Prominent lock banner ABOVE the toggle buttons.
              The old small pill was too easy to miss; users would
              click the greyed-out buttons and get no visible feedback.
              This banner spells out both the "why" (env var) and the
              "how" (ask operator) in one row. */}
          {locked && (
            <div className="mt-3 rounded-xl border border-slate-300 bg-slate-100 p-3 flex items-start gap-2 text-sm text-slate-800"
                 data-testid="env-lock-banner">
              <Lock size={16} className="mt-0.5 shrink-0 text-slate-600" />
              <span>
                <span className="font-semibold">Toggle is locked at the environment level.</span>
                {' '}Ask your operator to lift the lock before changing this setting.
              </span>
            </div>
          )}
          <div className="mt-3 flex gap-2">
            <button onClick={() => toggle('on')} disabled={busy || locked || eff === 'on'}
              data-testid="safe-mode-toggle-on"
              className="px-3 py-1.5 rounded-lg text-xs font-semibold bg-amber-500 hover:bg-amber-600 text-white disabled:opacity-40 disabled:cursor-not-allowed disabled:hover:bg-amber-500">
              Turn ON
            </button>
            <button onClick={() => toggle('off')} disabled={busy || locked || eff === 'off'}
              data-testid="safe-mode-toggle-off"
              className="px-3 py-1.5 rounded-lg text-xs font-semibold border border-slate-300 text-slate-700 hover:bg-slate-50 disabled:opacity-40 disabled:cursor-not-allowed disabled:hover:bg-transparent">
              Turn OFF
            </button>
          </div>
          {status && (
            <div className="mt-2 text-[11px] text-slate-500">
              env: <span className="font-mono">{status.env_value}</span> · org: <span className="font-mono">{status.org_value}</span> · effective: <span className="font-mono font-semibold">{status.effective}</span>
            </div>
          )}
        </div>
