// ─────────────── Page ───────────────

export default function Forms() {
  const user = getUser();
  const navigate = useNavigate();
  // v160.3.9.29-2c — Migrated from WRITE_ROLES to forms.edit token.
  const can = useCan();
  const canEdit = can('forms', 'edit');
  void user; void WRITE_ROLES;
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [search, setSearch] = useState('');
  const [filterOpen, setFilterOpen] = useState(false);
  const [previewT, setPreviewT] = useState(null);
  const [fillTemplate, setFillTemplate] = useState(null);
  const [importing, setImporting] = useState(false);
  const [aiOpen, setAiOpen] = useState(false);
  const [builderTemplate, setBuilderTemplate] = useState(null);  // {} for new, {id,...} for edit
  const filterRef = useRef(null);

  const load = async () => {
    setLoading(true);
    try {
      // Phase 3.9c — workers see only forms applicable to them by default.
      // Admins/managers/hseq see the full library.
      // v160.3.9.29-2c — `isWorker` was a negative gate on the admin/manager/
      // hseq_lead write set. Under new model, "no forms.edit" replaces it
      // exactly — no need to enumerate roles.
      const isWorker = !canEdit;
      const params = isWorker ? { for_worker: 'me' } : {};
      const { data } = await api.get('/forms/templates', { params });
      setRows(data || []);
    }
    catch (e) { toast.error(apiError(e)); }
    finally { setLoading(false); }
  };
  useEffect(() => { load(); }, []);

  const location = useLocation();

  // Deep-link from /scan/{token}?form={id} → auto-open the fill-out modal and
  // pre-fill the first asset_scan field with the scanned asset.
  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const tid = params.get('template');
    const tok = params.get('scan');
    if (!tid || !tok || !rows.length) return;
    const tpl = rows.find((t) => t.id === tid);
    if (!tpl) return;
    (async () => {
      try {
        const { data: asset } = await api.get('/forms/assets/lookup', { params: { token: tok } });
        const scanField = (tpl.fields || []).find((f) => f.type === 'asset_scan');
        const initial = {};
        if (scanField) initial[scanField.id] = {
          asset_id: asset.id, scan_token: asset.scan_token, name: asset.name,
          rego_serial: asset.rego_serial, asset_type: asset.asset_type,
          vehicle_type_slug: asset.vehicle_type_slug, kind: asset.kind,
          last_known_lat: asset.last_known_lat, last_known_lng: asset.last_known_lng,
          resolved_via: 'qr', resolved_at: new Date().toISOString(),
        };
        // Phase 3.8 — pre-fill the *logged-in* worker into any worker_picker
        // field. We match by email against the org's workers register so a
        // user without a worker row simply skips this step.
        const me = user;
        if (me?.email) {
          try {
            const { data: wp } = await api.get('/forms/pickers/workers', { params: { q: me.email, limit: 5 } });
            const match = (wp?.workers || []).find((w) => (w.email || '').toLowerCase() === me.email.toLowerCase());
            if (match) {
              (tpl.fields || []).forEach((f) => {
                if (f.type === 'worker_picker' && initial[f.id] == null) {
                  initial[f.id] = {
                    id: match.id, name: match.name, trade: match.trade || null,
                    phone: match.phone || null, email: match.email || null,
                  };
                }
              });
            }
          } catch { /* picker not available — skip silently */ }
        }
        // Phase 3.8 — auto-capture GPS so the worker doesn't have to tap a
        // button on their phone. Best-effort: silently no-op if the browser
        // denies / takes too long.
        const gpsField = (tpl.fields || []).find((f) => f.type === 'gps');
        if (gpsField && navigator.geolocation) {
          try {
            await new Promise((resolve) => {
              navigator.geolocation.getCurrentPosition(
                (pos) => {
                  initial[gpsField.id] = {
                    lat: pos.coords.latitude, lng: pos.coords.longitude,
                    accuracy: pos.coords.accuracy,
                    captured_at: new Date().toISOString(),
                  };
                  resolve();
                },
                () => resolve(),
                { enableHighAccuracy: true, timeout: 4000, maximumAge: 30_000 },
              );
            });
          } catch { /* noop */ }
        }
        // Schedule autofill of dependent fields after the modal mounts.
        const auto = buildAutofillFromAsset(tpl.fields || [], { ...asset });
        setFillTemplate({
          ...tpl,
          _initialValues: { ...initial, ...auto },
          _sourceScanToken: tok,
          _sourceAssetId: asset.id,
        });
      } catch (e) { toast.error(apiError(e)); }
      navigate('/app/forms', { replace: true });
    })();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location.search, rows.length]);

  useEffect(() => {
    const params = new URLSearchParams(location.search);
    if (params.get('builder') === 'ai' && canEdit) {
      setAiOpen(true);
      navigate('/app/forms', { replace: true });
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location.search]);

  // v58.13.19 — Deep-link `?template_id=<id>` → auto-open the preview
  // modal (read-only, no fill-out). Fired by rich-text "View
  // Checklist" links inserted into schedule descriptions. Ignored if
  // the id isn't in the loaded rows (e.g. archived or from a
  // different org). Runs after `rows` is populated so the modal has
  // a template to render.
  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const tid = params.get('template_id');
    if (!tid || !rows.length) return;
    const tpl = rows.find((t) => t.id === tid);
    if (!tpl) return;
    setPreviewT(tpl);
    // Strip the query param so a back-nav doesn't retrigger the
    // modal after the user closes it.
    navigate('/app/forms', { replace: true });
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location.search, rows.length]);

  useEffect(() => {
    if (!filterOpen) return;
    const onDoc = (e) => { if (filterRef.current && !filterRef.current.contains(e.target)) setFilterOpen(false); };
    document.addEventListener('mousedown', onDoc);
    return () => document.removeEventListener('mousedown', onDoc);
  }, [filterOpen]);

  const counts = useMemo(() => {
    const c = { all: rows.length, incident: 0, inspection: 0, toolbox: 0, near_miss: 0, general: 0 };
    for (const r of rows) if (c[r.category] !== undefined) c[r.category]++;
    return c;
  }, [rows]);

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    return rows
      .filter((r) => filter === 'all' ? true : r.category === filter)
      .filter((r) => !q || `${r.name} ${r.description || ''}`.toLowerCase().includes(q))
      .sort((a, b) => (a.name || '').localeCompare(b.name || ''));
  }, [rows, filter, search]);

  const removeTemplate = async (t) => {
    if (!window.confirm(`Delete "${t.name}"?`)) return;
    try { await api.delete(`/forms/templates/${t.id}`); toast.success(`${t.name} deleted`); load(); }
    catch (e) { toast.error(apiError(e)); }
  };

  const exportAll = () => {
    const payload = {
      app: 'Paneltec Civil', exported_at: new Date().toISOString(), version: 1,
      count: rows.length,
      templates: rows.map((r) => ({ name: r.name, category: r.category, description: r.description, fields: r.fields })),
    };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = `forms-export-${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(a); a.click(); a.remove();
    URL.revokeObjectURL(url);
  };

  const onEditTemplate = (t) => { setBuilderTemplate(t); };

  const currentFilterLabel = filter === 'all' ? `All categories (${counts.all})` : `${categoryLabel(filter)} (${counts[filter] ?? 0})`;

  return (
    <div className="max-w-7xl mx-auto" data-testid="forms-page">
      {/* v160.3.0-adjust-17e/20 — Sticky page header: title + action
          buttons + search + category filter stay pinned; card grid
          scrolls below. */}
      <div className="sticky top-16 z-20 bg-white -mx-4 sm:-mx-6 lg:-mx-8 px-4 sm:px-6 lg:px-8 pt-1 pb-3 border-b border-slate-100">
      {/* Page header */}
      <div className="mb-4">
        <h1 className="font-display text-4xl sm:text-5xl font-bold text-slate-900 tracking-tight">Form Templates</h1>
        <p className="mt-1 text-sm text-slate-500">Choose a form to fill, build your own, or generate with AI</p>
      </div>

      {/* Toolbar */}
      <div className="mb-3 flex flex-wrap items-center gap-2">
        {canEdit && (
          <button onClick={() => setImporting(true)} data-testid="toolbar-import"
            className="inline-flex items-center gap-2 px-4 py-2.5 rounded-2xl border border-slate-300 bg-white text-sm font-semibold text-slate-700 hover:bg-slate-50">
            <Download size={14} /> Import Civil Library
          </button>
        )}
        <button onClick={exportAll} disabled={rows.length === 0} data-testid="toolbar-export"
          className="inline-flex items-center gap-2 px-4 py-2.5 rounded-2xl border border-slate-300 bg-white text-sm font-semibold text-slate-700 hover:bg-slate-50 disabled:opacity-50">
          <Share2 size={14} /> Export All Forms
        </button>
        {canEdit && (
          <button onClick={() => setAiOpen(true)} data-testid="toolbar-ai"
            className="inline-flex items-center gap-2 px-4 py-2.5 rounded-2xl bg-gradient-to-r from-purple-500 to-pink-500 text-white text-sm font-semibold shadow-md hover:shadow-lg">
            <Sparkles size={14} /> Build with AI
          </button>
        )}
        {canEdit && (
          <button onClick={() => setBuilderTemplate({})}
            data-testid="toolbar-new"
            className="inline-flex items-center gap-2 px-4 py-2.5 rounded-2xl bg-gradient-to-r from-orange-500 to-amber-500 text-slate-900 text-sm font-bold shadow-md hover:shadow-lg">
            <Plus size={14} /> New Template
          </button>
        )}
      </div>

      {/* Search + category dropdown */}
      <div className="flex flex-wrap items-center gap-3">
        <div className="relative flex-1 max-w-md">
          <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
          <input value={search} onChange={(e) => setSearch(e.target.value)}
            data-testid="forms-search" placeholder="Search forms..."
            className="w-full pl-10 pr-3 py-2.5 text-sm border border-slate-300 rounded-2xl bg-white" />
        </div>
        <div className="relative" ref={filterRef}>
          <button onClick={() => setFilterOpen((o) => !o)} data-testid="filter-dropdown"
            className="inline-flex items-center gap-2 px-4 py-2.5 rounded-2xl border border-slate-300 bg-white text-sm font-semibold text-slate-700 hover:bg-slate-50">
            {currentFilterLabel} <ChevronDown size={14} />
          </button>
          {filterOpen && (
            <div className="absolute right-0 mt-1 w-64 rounded-2xl border border-slate-200 bg-white shadow-xl z-10 overflow-hidden" data-testid="filter-dropdown-menu">
              {CATEGORIES.map((c) => (
                <button key={c.key} onClick={() => { setFilter(c.key); setFilterOpen(false); }}
                  data-testid={`filter-opt-${c.key}`}
                  className={`w-full px-4 py-2.5 text-left text-sm font-medium hover:bg-slate-50 flex items-center justify-between ${filter === c.key ? 'bg-slate-100' : ''}`}>
                  <span className="flex items-center gap-2">
                    {c.key !== 'all' && <span className={`inline-block w-2.5 h-2.5 rounded-full ${c.pill.split(' ')[0]}`} />}
                    {c.label}
                  </span>
                  <span className="text-xs text-slate-500">{counts[c.key] ?? 0}</span>
                </button>
              ))}
            </div>
          )}
        </div>
      </div>
      </div>

      {/* Cards */}
      {loading ? (
        <div className="text-sm text-slate-500 inline-flex items-center gap-2"><Loader2 size={14} className="animate-spin" /> Loading…</div>
      ) : filtered.length === 0 ? (
        <div className="rounded-3xl border border-slate-200 bg-white p-12 text-center" data-testid="forms-empty">
          <FileText size={28} className="mx-auto text-slate-300 mb-2" />
          <div className="text-sm font-medium text-slate-700">No templates match</div>
          <div className="text-xs text-slate-500 mt-1">Try a different category or clear the search.</div>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3" data-testid="forms-grid">
          {filtered.map((t) => (
            <TemplateCard key={t.id} t={t} canEdit={canEdit}
              onPreview={() => setPreviewT(t)}
              onFill={() => setFillTemplate(t)}
              onDelete={() => removeTemplate(t)}
              onEdit={() => onEditTemplate(t)}
              onOpenSubmissions={() => navigate(`/app/forms/templates/${t.id}/submissions`)} />
          ))}
        </div>
      )}

      {importing && <ImportModal onClose={() => setImporting(false)} onImported={load} />}
      {aiOpen && <AiBuilderModal onClose={() => setAiOpen(false)} onCreated={(t) => { load(); setBuilderTemplate(t); }} />}
      {previewT && <PreviewModal template={previewT} onClose={() => setPreviewT(null)}
        onFill={() => { setFillTemplate(previewT); setPreviewT(null); }} />}
      {fillTemplate && <FillOutModal template={fillTemplate} initialValues={fillTemplate._initialValues}
        sourceScanToken={fillTemplate._sourceScanToken}
        sourceAssetId={fillTemplate._sourceAssetId}
        onClose={() => setFillTemplate(null)} onSubmitted={load} />}
      {builderTemplate !== null && <TemplateBuilder template={builderTemplate}
        onClose={() => setBuilderTemplate(null)}
        onSaved={() => load()} />}
    </div>
  );
}

// ─────────────── Read-only submission view (used by FormSubmissions) ───────────────

export function SubmissionViewModal({ submissionId, onClose }) {
  useLockBodyScroll();
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    let alive = true;
    api.get(`/forms/submissions/${submissionId}`)
      .then((r) => { if (alive) setData(r.data); })
      .catch((e) => toast.error(apiError(e)))
      .finally(() => { if (alive) setLoading(false); });
    return () => { alive = false; };
  }, [submissionId]);

  const renderValue = (f) => {
    const v = f.value;
    if (f.type === 'photo') {
      if (!Array.isArray(v) || v.length === 0) return <span className="text-slate-400 italic text-sm">No photos.</span>;
      return (
        <div className="grid grid-cols-3 gap-2">
          {v.map((p, i) => (
            <a key={i} href={`${process.env.REACT_APP_BACKEND_URL}${p.file_url}`} target="_blank" rel="noreferrer"
              className="aspect-square rounded-lg overflow-hidden border border-slate-200 hover:opacity-90">
              <img src={`${process.env.REACT_APP_BACKEND_URL}${p.file_url}`}
                alt={p.filename} className="w-full h-full object-cover" />
            </a>
          ))}
        </div>
      );
    }
    if (f.type === 'signature') {
      if (!v) return <span className="text-slate-400 italic text-sm">Not signed.</span>;
      return <img src={v} alt="signature" className="border border-slate-200 rounded-lg max-h-32 bg-white" />;
    }
    if (f.type === 'gps') {
      if (!v || v.lat == null) return <span className="text-slate-400 italic text-sm">Not captured.</span>;
      // v160.3.0-adjust-16e — Fetch the map from our backend proxy which
      // composes an OSM tile mosaic (English labels) and caches on disk.
      const lat = Number(v.lat);
      const lng = Number(v.lng);
      const apiBase = (process.env.REACT_APP_BACKEND_URL || '').replace(/\/$/, '');
      const mapUrl = `${apiBase}/api/gps-map?lat=${lat}&lng=${lng}&w=500&h=300&z=16`;
      return (
        <div className="rounded-lg border border-slate-200 overflow-hidden bg-white" data-testid="gps-map-block">
          <a href={`https://www.openstreetmap.org/?mlat=${lat}&mlon=${lng}#map=16/${lat}/${lng}`} target="_blank" rel="noreferrer" className="block">
            <img src={mapUrl} alt="Site location map"
                 className="w-full h-auto object-cover bg-slate-100"
                 style={{ maxHeight: 260 }}
                 loading="lazy"
                 onError={(e) => { e.currentTarget.style.display = 'none'; }} />
          </a>
          <div className="px-3 py-2 grid grid-cols-3 gap-2 text-[11px] text-slate-600">
            <div><span className="block text-slate-400 uppercase tracking-wider">Lat</span>{lat.toFixed(5)}</div>
            <div><span className="block text-slate-400 uppercase tracking-wider">Lng</span>{lng.toFixed(5)}</div>
            <div><span className="block text-slate-400 uppercase tracking-wider">± m</span>{Math.round(v.accuracy ?? 0)}</div>
          </div>
        </div>
      );
    }
    if (f.type === 'textarea') return <div className="text-sm text-slate-800 whitespace-pre-line">{v || '—'}</div>;
    if (f.type === 'vehicle_navixy') {
      if (!v || typeof v !== 'object') return <span className="text-slate-400 italic text-sm">No vehicle selected.</span>;
      return (
        <div className="inline-flex items-center gap-2 px-3 py-2 rounded-lg bg-slate-100 text-sm">
          <span className="font-medium text-slate-900">{v.label || 'Manual entry'}</span>
          <span className="text-slate-500">·</span>
          <span className="font-mono font-semibold text-slate-800">{v.registration || '—'}</span>
        </div>
      );
    }
    // v160.3.0-adjust-16c — Worker picker returns `[{worker_id, name,
    // company_label}, …]` — must render the names, NOT dump the object
    // as a React child (previously crashed the modal with "Objects are
    // not valid as a React child").
    if (f.type === 'worker_picker') {
      if (!Array.isArray(v) || v.length === 0) {
        return <span className="text-slate-400 italic text-sm">Not assigned.</span>;
      }
      return (
        <div className="flex flex-wrap gap-2">
          {v.map((w, i) => (
            <span key={i} className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-slate-100 text-slate-800 text-xs">
              <span className="font-medium">{w?.name || '—'}</span>
              {w?.company_label && (
                <span className="text-slate-500">· {w.company_label}</span>
              )}
            </span>
          ))}
        </div>
      );
    }
    // v160.3.9.4 — Graceful chip rendering for job_picker + site_picker
    // submission values. Visitor Register was `job_picker` before v160.3.9.4
    // and `site_picker` after — both value shapes must render legibly on
    // the submission viewer (not as raw JSON.stringify() blobs).
    if (f.type === 'job_picker' || f.type === 'site_picker') {
      if (!v || typeof v !== 'object') {
        return <span className="text-slate-400 italic text-sm">Not selected.</span>;
      }
      const name = v.site_name || v.name || v.job_name || v.label || '—';
      const sub = v.job_name && v.site_name ? v.job_name
        : v.address || v.site_address || null;
      return (
        <div className="inline-flex items-center gap-2 px-3 py-2 rounded-lg bg-slate-100 text-sm">
          <span className="font-medium text-slate-900">{name}</span>
          {sub && <span className="text-slate-500">· {sub}</span>}
        </div>
      );
    }
    // v160.3.0-adjust-16c — Defensive stringification for any residual
    // object / array values so the modal never crashes on unexpected
    // shapes (e.g. legacy submissions with rich objects). Also strip any
    // literal `<b>…</b>` markup that may have leaked in from a stringified
    // template value.
    let display;
    if (v === null || v === undefined || v === '') {
      display = '—';
    } else if (typeof v === 'object') {
      display = Array.isArray(v)
        ? v.map((x) => (typeof x === 'object' ? JSON.stringify(x) : String(x))).join(', ')
        : JSON.stringify(v);
    } else {
      display = String(v);
    }
    display = display.replace(/<\/?b>/gi, '');
    return <div className="text-sm text-slate-800 whitespace-pre-line">{display}</div>;
  };

  // v160.3.0-adjust-16b — Smart label display: strip section prefix
  // ("TAILGATE — Item" → "Item") OR guidance suffix ("Fluid Levels —
  // Check oil…" → "Fluid Levels"). Mirrors backend/forms_pdf.py.
  const displayLabel = (raw) => {
    if (!raw) return 'Untitled';
    let lbl = raw.trim();
    if (lbl.includes('—')) {
      const [before, ...rest] = lbl.split('—');
      const after = rest.join('—').trim();
      const b = (before || '').trim();
      if (b && b === b.toUpperCase() && b.length <= 24 && after) {
        lbl = after;
      } else {
        lbl = b || after;
      }
    }
    lbl = lbl.replace(/\s*\([^)]*\)\s*$/, '').trim();
    return lbl || raw;
  };

  return createPortal(
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4 bg-slate-900/40 backdrop-blur-sm"
      onClick={(e) => e.target === e.currentTarget && onClose()}
      data-testid="submission-view-modal">
      <div className="w-full sm:max-w-3xl bg-white sm:rounded-3xl shadow-2xl border border-slate-200 overflow-hidden h-full sm:h-auto sm:max-h-[92vh] flex flex-col">
        <div className="px-4 sm:px-6 py-5 border-b border-slate-200 bg-white flex items-start gap-3">
          <div className="flex-1 min-w-0">
            <div className="text-[10px] uppercase tracking-[0.16em] font-semibold text-slate-500">Submission</div>
            <h2 className="font-display text-xl font-bold text-slate-900 truncate">{data?.template_name_snapshot || '…'}</h2>
            {data && <p className="text-xs text-slate-500 mt-1">By {data.submitted_by_name} · {(data.submitted_at || '').slice(0, 16).replace('T', ' ')}</p>}
          </div>
          <button onClick={onClose} className="p-2 -m-1 rounded-xl hover:bg-slate-100 min-w-[44px] min-h-[44px] flex items-center justify-center" data-testid="submission-close">
            <X size={18} />
          </button>
        </div>
        <div className="px-4 sm:px-6 py-5 overflow-y-auto space-y-4 flex-1">
          {loading ? <div className="text-sm text-slate-500 inline-flex items-center gap-2"><Loader2 size={14} className="animate-spin" /> Loading…</div>
            : !data ? <div className="text-sm text-slate-500">Submission not found.</div>
            : (data.fields || [])
                .filter((f) => {
                  // v160.3.0-adjust-16b — Suppress empty photo rows in the
                  // UI too, matching the PDF renderer.
                  if (f.type === 'photo') {
                    return Array.isArray(f.value) && f.value.some(
                      (ph) => ph && (ph.filename || ph.file_url || ph.url)
                    );
                  }
                  return true;
                })
                .map((f) => (
              <div key={f.id} className="grid grid-cols-1 sm:grid-cols-[minmax(180px,40%)_1fr] gap-2 sm:gap-4 pb-3 border-b border-slate-100 last:border-b-0">
                <label className="block text-xs font-semibold text-slate-700 sm:pt-1" data-testid={`submission-field-label-${f.id}`}>
                  {displayLabel(f.label)}
                </label>
                <div data-testid={`submission-field-value-${f.id}`}>
                  {renderValue(f)}
                </div>
              </div>
            ))}
        </div>
      </div>
    </div>,
    document.body,
  );
}

import React, { useEffect, useState } from 'react';
import { Loader2, Play, Save, CheckCircle2, AlertCircle, Mail } from 'lucide-react';
import { toast } from 'sonner';
import api from '../lib/api';
import { BackButton } from '../components/capture/Ui';
import {
  AdminCard, StatusPill, Field, Input, InputWithToggle, SavedChip, isMasked, authErrorToast,
} from '../components/IntegrationFormUI';

const empty = {
  tenant_id: '',
  client_id: '',
  secretInput: '',
  secretOnFile: null,
  sender_email: '',
  reply_to: '',
};

export default function Microsoft365Admin() {
  const [s, setS] = useState(empty);
  const [doc, setDoc] = useState(null);
  const [showSecret, setShowSecret] = useState(false);
  const [busy, setBusy] = useState({ save: false, test: false });
  const [testMsg, setTestMsg] = useState(null);

  const apply = (data) => {
    setDoc(data);
    const cfg = data?.config || {};
    setS((prev) => ({
      ...prev,
      tenant_id: cfg.tenant_id || '',
      client_id: cfg.client_id || '',
      secretOnFile: isMasked(cfg.client_secret) ? cfg.client_secret : (cfg.client_secret ? '••••' : null),
      sender_email: cfg.sender_email || '',
      reply_to: cfg.reply_to || '',
    }));
  };

  const load = async () => {
    try { const { data } = await api.get('/integrations/microsoft365'); apply(data); } catch { /* silent */ }
  };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { load(); }, []);

  const buildBody = () => ({
    tenant_id: s.tenant_id || null,
    client_id: s.client_id || null,
    client_secret: s.secretInput ? s.secretInput : (s.secretOnFile || null),
    sender_email: s.sender_email || null,
    reply_to: s.reply_to || null,
  });

  const autoSave = async () => {
    try { const { data } = await api.put('/integrations/microsoft365', buildBody()); apply(data); return true; }
    catch (e) { authErrorToast(toast, e, 'Microsoft 365'); return false; }
  };

  const save = async () => {
    setBusy((b) => ({ ...b, save: true }));
    const ok = await autoSave();
    if (ok) { toast.success('Credentials saved'); setS((p) => ({ ...p, secretInput: '' })); }
    setBusy((b) => ({ ...b, save: false }));
  };

  const test = async () => {
    if (!await autoSave()) return;
    setBusy((b) => ({ ...b, test: true })); setTestMsg(null);
    try {
      const { data } = await api.post('/integrations/microsoft365/test-connection');
      const flushed = data.flushed_from_queue || 0;
      const flushText = flushed > 0 ? ` (${flushed} queued email${flushed === 1 ? '' : 's'} also flushed)` : '';
      const txt = `Sent a self-test email to ${data.sent_to} — check the inbox.${flushText}`;
      setTestMsg({ ok: true, text: txt });
      toast.success('Test email sent');
      await load();
    } catch (e) {
      setTestMsg({ ok: false, text: e?.response?.data?.detail || e.message });
      authErrorToast(toast, e, 'Microsoft 365');
    } finally { setBusy((b) => ({ ...b, test: false })); }
  };

  const connected = doc?.status === 'connected';
  const errored = doc?.status === 'error';

  return (
    <div className="max-w-5xl mx-auto space-y-6" data-testid="m365-admin">
      <BackButton to="/app/settings/integrations" />
      <AdminCard
        title={<>Microsoft 365 <span className="text-slate-400 mx-2">—</span> Email · Graph SendMail (Application Permission)</>}
        statusPill={<StatusPill connected={connected} errored={errored} testid="m365-status-pill" labels={{ live: '● Live' }} />}
      >
        {/* Recommendation banner */}
        <div className="rounded-xl border border-[#D8CFB8] bg-[#FAF6EC] px-5 py-4 mb-7 text-sm leading-relaxed text-slate-800" data-testid="m365-recommendation">
          <div className="text-[11px] uppercase tracking-[0.18em] font-semibold text-emerald-700 mb-1">Recommended for Paneltec</div>
          <p>
            Sends invoices and statements straight from a real M365 mailbox you own (no DNS changes).
            Open <strong>portal.azure.com → Microsoft Entra ID → App registrations</strong>, create an app
            named e.g. "Paneltec Email", grant the <strong>Mail.Send</strong> Application permission
            (admin consent), then paste the three values below + the mailbox you want to send from. Once
            configured, M365 becomes the primary transport (Resend is kept as automatic fallback).
          </p>
        </div>

        {/* Form */}
        <div className="grid sm:grid-cols-2 gap-x-7 gap-y-5">
          <div>
            <Field label="Directory (tenant) ID">
              <Input value={s.tenant_id} onChange={(v) => setS({ ...s, tenant_id: v })}
                placeholder="00000000-0000-0000-0000-000000000000" testid="m365-tenant" />
            </Field>
            <p className="mt-1.5 text-[11px] text-slate-500">From your App Registration's Overview page.</p>
          </div>
          <div>
            <Field label="Application (client) ID">
              <Input value={s.client_id} onChange={(v) => setS({ ...s, client_id: v })}
                placeholder="00000000-0000-0000-0000-000000000000" testid="m365-client-id" />
            </Field>
            <p className="mt-1.5 text-[11px] text-slate-500">From the same Overview page.</p>
          </div>
          <div className="sm:col-span-2">
            <Field label="Client Secret (Value)" rightSlot={<SavedChip savedValue={s.secretOnFile} hasInput={!!s.secretInput} testid="m365-secret-saved" />}>
              <InputWithToggle value={s.secretInput} onChange={(v) => setS({ ...s, secretInput: v })}
                placeholder={s.secretOnFile || 'paste the Value column from Certificates & secrets'}
                show={showSecret} onToggle={() => setShowSecret((x) => !x)} testid="m365-secret" mono />
            </Field>
            <p className="mt-1.5 text-[11px] text-slate-500">
              <strong>Important:</strong> Azure shows the secret <strong>only once</strong>. Copy the
              <em> Value</em> field, not the Secret ID. Secrets expire — rotate before they do.
            </p>
          </div>
          <div>
            <Field label="Send-from Mailbox">
              <Input type="email" value={s.sender_email} onChange={(v) => setS({ ...s, sender_email: v })}
                placeholder="no-reply@paneltec.com.au" testid="m365-sender" />
            </Field>
            <p className="mt-1.5 text-[11px] text-slate-500">Must be a real licensed M365 mailbox or shared mailbox in your tenant.</p>
          </div>
          <div>
            <Field label="Reply-to (optional)">
              <Input type="email" value={s.reply_to} onChange={(v) => setS({ ...s, reply_to: v })}
                placeholder="admin@paneltec.com.au" testid="m365-reply-to" />
            </Field>
            <p className="mt-1.5 text-[11px] text-slate-500">Recipients hit Reply → goes here instead of the send-from mailbox.</p>
          </div>
        </div>

        {testMsg && (
          <div className={`mt-6 inline-flex items-center gap-1.5 text-sm ${testMsg.ok ? 'text-emerald-700' : 'text-red-700'}`} data-testid="m365-test-msg">
            {testMsg.ok ? <CheckCircle2 size={14} /> : <AlertCircle size={14} />} <span>{testMsg.text}</span>
          </div>
        )}

        {/* Two-button action row */}
        <div className="mt-7 flex flex-wrap gap-3">
          <button onClick={save} disabled={busy.save} data-testid="m365-save"
            className="inline-flex items-center gap-2 px-6 py-2.5 rounded-lg text-white text-sm font-semibold uppercase tracking-[0.14em] disabled:opacity-60"
            style={{ backgroundColor: '#2C6BFF' }}>
            {busy.save ? <Loader2 size={14} className="animate-spin" /> : <Save size={14} />} Save Credentials
          </button>
          <button onClick={test} disabled={busy.test} data-testid="m365-test-connection"
            className="inline-flex items-center gap-2 px-6 py-2.5 rounded-lg bg-transparent text-sm font-semibold uppercase tracking-[0.14em] disabled:opacity-60 hover:bg-black/5"
            style={{ color: '#0F1B2D', border: '1px solid #0F1B2D' }}>
            {busy.test ? <Loader2 size={14} className="animate-spin" /> : <Play size={14} />} Test Connection
          </button>
        </div>
      </AdminCard>

      {/* Setup instructions */}
      <div className="rounded-2xl border border-[#D8CFB8] p-6" style={{ backgroundColor: '#F5EFE0' }} data-testid="m365-setup-guide">
        <div className="flex items-center gap-2 mb-3">
          <Mail size={16} className="text-brand-blue" />
          <h3 className="font-display text-lg font-semibold">5-minute Azure setup</h3>
        </div>
        <ol className="space-y-2.5 text-sm leading-relaxed text-slate-800 list-decimal pl-5">
          <li>Sign in at <strong>portal.azure.com</strong> as a Global Administrator or Application Administrator.</li>
          <li>Open <strong>Microsoft Entra ID → App registrations → New registration</strong>. Name it "Paneltec Email", single tenant, <em>no redirect URI needed</em>. Click <strong>Register</strong>.</li>
          <li>On the Overview page, copy <strong>Application (client) ID</strong> and <strong>Directory (tenant) ID</strong> into the fields above.</li>
          <li>Open <strong>Certificates &amp; secrets → New client secret</strong>, choose 24-month expiry, click <strong>Add</strong>. <strong>Copy the "Value" column right away</strong> — it's only shown once. Paste it into the Client Secret field above.</li>
          <li>Open <strong>API permissions → Add a permission → Microsoft Graph → Application permissions → Mail.Send</strong>. Click <strong>Add</strong>, then <strong>Grant admin consent</strong> at the top.</li>
          <li>Set Send-from Mailbox above to a real M365 mailbox like <code className="px-1.5 py-0.5 bg-white border border-slate-200 rounded text-xs font-mono">no-reply@paneltec.com.au</code>, save, then test.</li>
          <li><strong>(Recommended)</strong> Lock the app to ONLY this mailbox via an Application Access Policy — see <a href="https://learn.microsoft.com/en-us/graph/auth-limit-mailbox-access" target="_blank" rel="noreferrer" className="text-brand-blue hover:underline">Microsoft's Graph SendMail docs</a>.</li>
        </ol>
      </div>
    </div>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import { Mail, RefreshCw, Ban, ExternalLink, AlertTriangle, Filter, Trash2, ChevronDown, Loader2, Zap } from 'lucide-react';
import { toast } from 'sonner';
import api, { apiError } from '../lib/api';
import { PageHeader } from '../components/capture/Ui';
// v160.3.7k — Inoculation sweep: lock body scroll while the Outbox detail drawer is open.
import useLockBodyScroll from '../lib/useLockBodyScroll';
import {
  AlertDialog, AlertDialogContent, AlertDialogHeader, AlertDialogTitle,
  AlertDialogDescription, AlertDialogFooter, AlertDialogCancel, AlertDialogAction,
} from '../components/ui/alert-dialog';
import {
  DropdownMenu, DropdownMenuTrigger, DropdownMenuContent, DropdownMenuItem,
  DropdownMenuLabel, DropdownMenuSeparator,
} from '../components/ui/dropdown-menu';

const STATUS_STYLES = {
  queued:    'bg-amber-100 text-amber-800 border-amber-200',
  sent:      'bg-emerald-100 text-emerald-800 border-emerald-200',
  failed:    'bg-red-100 text-red-800 border-red-200',
  cancelled: 'bg-slate-200 text-slate-700 border-slate-300',
  blocked:   'bg-amber-200 text-amber-900 border-amber-400', // Phase 4.7.3
};

const BULK_OPTIONS = [
  { key: 'sent',      label: 'Clear all sent',      statuses: ['sent'] },
  { key: 'failed',    label: 'Clear all failed',    statuses: ['failed'] },
  { key: 'cancelled', label: 'Clear all cancelled', statuses: ['cancelled'] },
  { key: 'all',       label: 'Clear all (except queued)', statuses: ['sent', 'failed', 'cancelled'] },
];

// Phase 4.7.3 — Comms Safe Mode banner. Renders ONLY when safe mode is on
// (otherwise null, so it doesn't add noise to a normal-delivery setup).
function SafeModeBanner() {
  const [status, setStatus] = useState(null);
  const [blockedCount, setBlockedCount] = useState(0);
  useEffect(() => {
    api.get('/admin/comms-safe-mode/status').then((r) => setStatus(r.data)).catch(() => {});
    api.get('/admin/comms-outbox-blocked?limit=1')
      .then((r) => setBlockedCount(r.data?.count || 0)).catch(() => {});
  }, []);
  if (!status || status.effective !== 'on') return null;
  return (
    <div className="mb-4 rounded-xl border border-amber-300 bg-amber-50 p-4 flex items-start gap-3" data-testid="outbox-safe-mode-banner">
      <div className="w-9 h-9 rounded-lg bg-amber-200 text-amber-800 flex items-center justify-center flex-shrink-0">
        <Zap size={16} className="fill-amber-600 text-amber-600" />
      </div>
      <div className="flex-1">
        <div className="font-semibold text-slate-900 text-sm">
          Comms Safe Mode is ON {status.env_locked && <span className="text-[10px] uppercase tracking-wider bg-slate-200 text-slate-700 px-1.5 py-0.5 rounded ml-1">env-locked</span>}
        </div>
        <div className="text-xs text-slate-600 mt-0.5">
          Outbound email and SMS are being CAPTURED for review but NOT delivered. Anything new will show up below as <span className="font-mono text-[11px] bg-amber-100 px-1 rounded">blocked</span> (in addition to the dedicated outbox).
        </div>
      </div>
      <Link to="/app/settings/comms-safe-mode"
        data-testid="outbox-safe-mode-link"
        className="flex-shrink-0 text-xs font-semibold text-orange-700 hover:underline inline-flex items-center gap-1">
        View blocked ({blockedCount}) <ExternalLink size={11} />
      </Link>
    </div>
  );
}

export default function Outbox() {
  const [data, setData] = useState({ items: [], m365_connected: false, count: 0 });
  const [statusF, setStatusF] = useState('');
  const [kindF, setKindF] = useState('');
  const [active, setActive] = useState(null);
  // v160.3.7k — lock body scroll while the detail drawer is open.
  useLockBodyScroll(!!active);
  const [toDelete, setToDelete] = useState(null);   // single row
  const [bulkPlan, setBulkPlan] = useState(null);   // { label, statuses, count }
  const [busy, setBusy] = useState(false);
  // v160.3.6d — per-row selection for admin bulk-delete-by-ids
  const [selected, setSelected] = useState(() => new Set());
  const [selectionDelete, setSelectionDelete] = useState(false);

  const load = async () => {
    const params = new URLSearchParams();
    if (statusF) params.set('status', statusF);
    if (kindF) params.set('related_record_type', kindF);
    try {
      const { data: d } = await api.get('/email/outbox?' + params.toString());
      setData(d);
      // v160.3.6d — drop any selected ids that no longer exist in the reloaded page
      setSelected((prev) => {
        if (prev.size === 0) return prev;
        const visible = new Set((d.items || []).map((m) => m.id));
        const next = new Set();
        prev.forEach((id) => { if (visible.has(id)) next.add(id); });
        return next.size === prev.size ? prev : next;
      });
    } catch (e) { toast.error(apiError(e)); }
  };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { load(); }, [statusF, kindF]);

  // Always-on full list counts (for the Clear dropdown — must not be filtered)
  const [fullCounts, setFullCounts] = useState({ sent: 0, failed: 0, cancelled: 0, queued: 0 });
  const loadCounts = async () => {
    try {
      const { data: d } = await api.get('/email/outbox?limit=500');
      const c = { sent: 0, failed: 0, cancelled: 0, queued: 0 };
      (d.items || []).forEach((m) => { if (m.status in c) c[m.status] += 1; });
      setFullCounts(c);
    } catch { /* silent */ }
  };
  useEffect(() => { loadCounts(); }, [data]);

  const retry  = async (id) => { try { await api.post(`/email/outbox/${id}/retry`);  toast.success('Retried'); load(); } catch (e) { toast.error(apiError(e)); } };
  const cancel = async (id) => { try { await api.post(`/email/outbox/${id}/cancel`); toast.success('Cancelled'); load(); } catch (e) { toast.error(apiError(e)); } };

  const doDelete = async () => {
    if (!toDelete) return;
    setBusy(true);
    try {
      await api.delete(`/email/outbox/${toDelete.id}`);
      toast.success('Email deleted');
      setToDelete(null);
      await load();
    } catch (e) { toast.error(apiError(e) || 'Could not delete email'); }
    finally { setBusy(false); }
  };

  const openBulk = (opt) => {
    const count = opt.statuses.reduce((acc, s) => acc + (fullCounts[s] || 0), 0);
    setBulkPlan({ ...opt, count });
  };

  const doBulk = async () => {
    if (!bulkPlan) return;
    setBusy(true);
    try {
      let deletedTotal = 0;
      for (const status of bulkPlan.statuses) {
        const { data: r } = await api.post('/email/outbox/bulk-delete', { filter: { status } });
        deletedTotal += r.deleted || 0;
      }
      toast.success(`${deletedTotal} email${deletedTotal === 1 ? '' : 's'} deleted`);
      setBulkPlan(null);
      await load();
    } catch (e) { toast.error(apiError(e) || 'Bulk delete failed'); }
    finally { setBusy(false); }
  };

  // v160.3.6d — selection helpers + ids-based bulk delete (admin only)
  const toggleRow = (id) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  };
  const visibleIds = data.items.map((m) => m.id);
  const allSelected = visibleIds.length > 0 && visibleIds.every((id) => selected.has(id));
  const someSelected = !allSelected && visibleIds.some((id) => selected.has(id));
  const toggleAll = () => {
    setSelected((prev) => {
      if (visibleIds.every((id) => prev.has(id))) {
        // all → none (within the current page)
        const next = new Set(prev);
        visibleIds.forEach((id) => next.delete(id));
        return next;
      }
      // add every visible id
      const next = new Set(prev);
      visibleIds.forEach((id) => next.add(id));
      return next;
    });
  };
  const clearSelection = () => setSelected(new Set());
  const doSelectionDelete = async () => {
    if (selected.size === 0) return;
    const ids = Array.from(selected);
    setBusy(true);
    try {
      const { data: r } = await api.post('/email/outbox/bulk-delete', { ids });
      toast.success(`${r.deleted || 0} email${(r.deleted || 0) === 1 ? '' : 's'} deleted`);
      setSelectionDelete(false);
      clearSelection();
      await load();
      await loadCounts();
    } catch (e) { toast.error(apiError(e) || 'Bulk delete failed'); }
    finally { setBusy(false); }
  };

  const subtitle = useMemo(() => {
    const total = data.count;
    const chips = [];
    if (fullCounts.queued) chips.push(`${fullCounts.queued} queued`);
    if (fullCounts.sent) chips.push(`${fullCounts.sent} sent`);
    if (fullCounts.failed) chips.push(`${fullCounts.failed} failed`);
    if (fullCounts.cancelled) chips.push(`${fullCounts.cancelled} cancelled`);
    const provider = `provider: Microsoft 365${data.m365_connected ? '' : ' (not connected)'}`;
    return `${total} message${total === 1 ? '' : 's'}${chips.length ? ' · ' + chips.join(' · ') : ''} · ${provider}`;
  }, [data.count, data.m365_connected, fullCounts]);

  const hasAnyClearable = fullCounts.sent + fullCounts.failed + fullCounts.cancelled > 0;

  return (
    <div className="max-w-6xl mx-auto" data-testid="outbox-page">
      <SafeModeBanner />
      <PageHeader
        crumb="Settings / Email outbox"
        title="Email outbox"
        subtitle={subtitle}
        action={
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <button
                disabled={!hasAnyClearable}
                data-testid="outbox-clear-trigger"
                className="inline-flex items-center gap-1.5 px-4 py-2 rounded-lg border border-rose-200 bg-white text-rose-600 text-sm font-medium hover:bg-rose-50 hover:border-rose-300 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <Trash2 size={13} /> Clear <ChevronDown size={13} />
              </button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-60">
              <DropdownMenuLabel>Bulk delete</DropdownMenuLabel>
              <DropdownMenuSeparator />
              {BULK_OPTIONS.map((opt) => {
                const count = opt.statuses.reduce((a, s) => a + (fullCounts[s] || 0), 0);
                return (
                  <DropdownMenuItem
                    key={opt.key}
                    disabled={count === 0}
                    onClick={() => openBulk(opt)}
                    data-testid={`outbox-clear-${opt.key}`}
                  >
                    <span className="flex-1">{opt.label}</span>
                    <span className="text-xs text-slate-400 ml-2">{count}</span>
                  </DropdownMenuItem>
                );
              })}
              <DropdownMenuSeparator />
              <div className="px-2 py-1.5 text-[11px] text-slate-500">
                Queued emails are protected from bulk delete.
              </div>
            </DropdownMenuContent>
          </DropdownMenu>
        }
      />

      {!data.m365_connected && (
        <div className="mb-5 rounded-xl border border-amber-200 bg-amber-50 p-4 flex items-start gap-3" data-testid="m365-banner">
          <AlertTriangle size={18} className="text-amber-600 shrink-0 mt-0.5" />
          <div className="text-sm text-amber-900">
            <strong>Microsoft 365 not connected.</strong> Queued emails won't send until M365 is configured in
            <a href="/app/settings/integrations" className="underline ml-1">Settings → Integrations</a>.
          </div>
        </div>
      )}

      <div className="flex flex-wrap gap-2 mb-4 items-center">
        <Filter size={14} className="text-slate-400" />
        <select value={statusF} onChange={(e) => setStatusF(e.target.value)}
          className="text-sm border border-slate-300 rounded-lg px-2 py-1.5" data-testid="outbox-filter-status">
          <option value="">All statuses</option>
          <option value="queued">Queued</option>
          <option value="sent">Sent</option>
          <option value="failed">Failed</option>
          <option value="cancelled">Cancelled</option>
        </select>
        <select value={kindF} onChange={(e) => setKindF(e.target.value)}
          className="text-sm border border-slate-300 rounded-lg px-2 py-1.5" data-testid="outbox-filter-kind">
          <option value="">All record types</option>
          {['swms', 'pre_starts', 'site_diary', 'hazards', 'incidents', 'inspections',
            'contractors', 'renewals', 'audit_exports'].map((k) => <option key={k} value={k}>{k}</option>)}
        </select>
        <button onClick={load} className="text-sm inline-flex items-center gap-1 px-2.5 py-1.5 border border-slate-300 rounded-lg hover:bg-slate-50">
          <RefreshCw size={13} /> Refresh
        </button>
      </div>

      <div className="rounded-2xl border border-slate-200 bg-white overflow-hidden">
        <table className="w-full text-sm">
          <thead className="bg-slate-50 text-[11px] uppercase tracking-wider text-slate-500">
            <tr>
              {/* v160.3.6d — master checkbox column */}
              <th className="w-10 px-3 py-2.5">
                <input
                  type="checkbox"
                  checked={allSelected}
                  ref={(el) => { if (el) el.indeterminate = someSelected; }}
                  onChange={toggleAll}
                  disabled={visibleIds.length === 0}
                  aria-label={allSelected ? 'Deselect all visible' : 'Select all visible'}
                  data-testid="outbox-select-all"
                  className="w-3.5 h-3.5 cursor-pointer disabled:opacity-40"
                />
              </th>
              <th className="text-left px-4 py-2.5">Status</th>
              <th className="text-left px-4 py-2.5">To</th>
              <th className="text-left px-4 py-2.5">Subject</th>
              <th className="text-left px-4 py-2.5">Related</th>
              <th className="text-left px-4 py-2.5">Created</th>
              <th className="px-4 py-2.5"></th>
            </tr>
          </thead>
          <tbody>
            {data.items.length === 0 && (
              <tr><td colSpan={7} className="text-center text-sm text-slate-500 py-8">No outbox messages.</td></tr>
            )}
            {data.items.map((m) => {
              const isSelected = selected.has(m.id);
              return (
              <tr key={m.id}
                  className={`border-t border-slate-100 hover:bg-slate-50 ${isSelected ? 'bg-[#e6eff9]/40' : ''}`}
                  data-testid={`outbox-row-${m.id}`}>
                <td className="px-3 py-3 align-middle">
                  <input
                    type="checkbox"
                    checked={isSelected}
                    onChange={() => toggleRow(m.id)}
                    aria-label={`Select email ${m.subject || m.id}`}
                    data-testid={`outbox-select-${m.id}`}
                    onClick={(e) => e.stopPropagation()}
                    className="w-3.5 h-3.5 cursor-pointer"
                  />
                </td>
                <td className="px-4 py-3">
                  <span className={`text-[10px] px-2 py-0.5 rounded-full font-semibold uppercase tracking-wider border ${STATUS_STYLES[m.status]}`}>
                    {m.status}
                  </span>
                </td>
                <td className="px-4 py-3 text-slate-700 truncate max-w-[200px]">{(m.to || []).join(', ')}</td>
                <td className="px-4 py-3 font-medium cursor-pointer" onClick={() => setActive(m)}>{m.subject}</td>
                <td className="px-4 py-3 text-xs text-slate-500">{m.related_record_type || '—'}</td>
                <td className="px-4 py-3 text-xs text-slate-500">{new Date(m.created_at).toLocaleString()}</td>
                <td className="px-4 py-3 text-right whitespace-nowrap">
                  {(m.status === 'queued' || m.status === 'failed') && (
                    <button onClick={() => retry(m.id)} title="Retry" className="text-xs px-2 py-1 hover:bg-slate-100 rounded inline-flex items-center gap-1 mr-1"
                      data-testid={`outbox-retry-${m.id}`}><RefreshCw size={12} /> Retry</button>
                  )}
                  {m.status === 'queued' && (
                    <button onClick={() => cancel(m.id)} title="Cancel" className="text-xs px-2 py-1 hover:bg-red-50 text-red-700 rounded inline-flex items-center gap-1 mr-1"
                      data-testid={`outbox-cancel-${m.id}`}><Ban size={12} /> Cancel</button>
                  )}
                  <button
                    type="button"
                    onClick={(e) => { e.stopPropagation(); setToDelete(m); }}
                    title="Delete"
                    aria-label="Delete email"
                    data-testid={`outbox-delete-${m.id}`}
                    className="inline-flex items-center justify-center w-7 h-7 rounded-md border border-rose-200 bg-white text-rose-500 hover:bg-rose-500 hover:text-white hover:border-rose-500 transition-colors"
                  >
                    <Trash2 size={13} />
                  </button>
                </td>
              </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* v160.3.6d — floating selection action bar */}
      {selected.size > 0 && (
        <div
          role="region"
          aria-label="Bulk actions for selected emails"
          data-testid="outbox-selection-bar"
          className="fixed inset-x-0 bottom-6 z-30 flex justify-center px-4 pointer-events-none"
        >
          <div className="pointer-events-auto flex items-center gap-3 rounded-full border border-slate-200 bg-white shadow-xl px-5 py-3">
            <span className="text-sm font-semibold text-slate-900" data-testid="outbox-selection-count">
              {selected.size} selected
            </span>
            <span className="text-slate-300">|</span>
            <button
              type="button"
              onClick={clearSelection}
              className="text-xs font-medium text-slate-600 hover:text-slate-900"
              data-testid="outbox-selection-clear"
            >
              Clear
            </button>
            <button
              type="button"
              onClick={() => setSelectionDelete(true)}
              data-testid="outbox-selection-delete"
              className="inline-flex items-center gap-1.5 rounded-full bg-rose-600 hover:bg-rose-700 text-white text-xs font-semibold uppercase tracking-wider px-4 py-2"
            >
              <Trash2 size={13} /> Delete selected
            </button>
          </div>
        </div>
      )}

      {active && (
        <div className="fixed inset-0 bg-black/40 z-40 flex items-end sm:items-center justify-end" onClick={() => setActive(null)}>
          <div className="bg-white w-full sm:max-w-lg h-full sm:h-auto sm:max-h-[80vh] overflow-auto border-l border-slate-200 p-5" onClick={(e) => e.stopPropagation()} data-testid="outbox-drawer">
            <div className="flex items-start justify-between gap-3">
              <div>
                <div className="text-[11px] uppercase tracking-wider text-slate-500">Status</div>
                <span className={`text-[10px] px-2 py-0.5 rounded-full font-semibold uppercase border ${STATUS_STYLES[active.status]}`}>{active.status}</span>
              </div>
              <button onClick={() => setActive(null)} className="text-slate-400 hover:text-slate-700 text-2xl leading-none">&times;</button>
            </div>
            <h3 className="font-display text-xl mt-3">{active.subject}</h3>
            <div className="mt-2 text-xs text-slate-500"><Mail size={11} className="inline -mt-0.5 mr-1" /> {(active.to || []).join(', ')}</div>
            {active.cc?.length > 0 && <div className="text-xs text-slate-500">CC: {active.cc.join(', ')}</div>}
            {/* v160.3.9.40 (SEC-002) — `body_html` is now server-side sanitised
                via `bleach` before storage (see backend/email_outbox.py
                `sanitize_email_body_html`). No client-side sanitizer here — the
                server value is authoritative. The `data-sanitized="true"`
                attribute is a probe marker so security tests can assert this
                render path was taken. */}
            <div className="mt-4 border border-slate-200 rounded-lg p-3 prose prose-sm max-w-none text-sm"
                 data-sanitized="true"
                 data-testid="outbox-body-html"
                 dangerouslySetInnerHTML={{ __html: active.body_html || '' }} />
            {active.attachments?.length > 0 && (
              <div className="mt-3"><div className="text-[11px] uppercase tracking-wider text-slate-500 mb-1">Attachments</div>
                <ul className="text-sm space-y-1">{active.attachments.map((a, i) => (
                  <li key={i}><a href={a.file_url} className="text-brand-blue hover:underline inline-flex items-center gap-1"><ExternalLink size={11} /> {a.filename}</a></li>
                ))}</ul>
              </div>
            )}
            {active.error && <div className="mt-3 text-xs text-red-700 bg-red-50 border border-red-200 rounded p-2">Error: {active.error}</div>}
          </div>
        </div>
      )}

      {/* Per-row delete confirmation */}
      <AlertDialog open={!!toDelete} onOpenChange={(o) => { if (!o) setToDelete(null); }}>
        <AlertDialogContent data-testid="outbox-delete-dialog">
          <AlertDialogHeader>
            <AlertDialogTitle>Delete email?</AlertDialogTitle>
            <AlertDialogDescription>
              {toDelete && <span className="block font-medium text-slate-900 mb-2 truncate">{toDelete.subject}</span>}
              This soft-deletes the email from your outbox. Records remain in the database
              for audit but are hidden from all lists.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={busy} data-testid="outbox-delete-cancel">Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={doDelete}
              disabled={busy}
              data-testid="outbox-delete-confirm"
              className="bg-rose-600 hover:bg-rose-700 focus:ring-rose-600"
            >
              {busy ? <Loader2 size={14} className="animate-spin mr-1.5" /> : <Trash2 size={14} className="mr-1.5" />}
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Bulk delete confirmation */}
      <AlertDialog open={!!bulkPlan} onOpenChange={(o) => { if (!o) setBulkPlan(null); }}>
        <AlertDialogContent data-testid="outbox-bulk-dialog">
          <AlertDialogHeader>
            <AlertDialogTitle>{bulkPlan?.label}?</AlertDialogTitle>
            <AlertDialogDescription>
              Delete <strong>{bulkPlan?.count || 0}</strong> email{bulkPlan?.count === 1 ? '' : 's'}? This soft-deletes them
              (hidden from all lists but retained in the database for audit). Queued
              emails will not be touched.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={busy} data-testid="outbox-bulk-cancel">Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={doBulk}
              disabled={busy || !bulkPlan?.count}
              data-testid="outbox-bulk-confirm"
              className="bg-rose-600 hover:bg-rose-700 focus:ring-rose-600"
            >
              {busy ? <Loader2 size={14} className="animate-spin mr-1.5" /> : <Trash2 size={14} className="mr-1.5" />}
              Delete {bulkPlan?.count || 0}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* v160.3.6d — Selection (ids-based) bulk delete confirmation */}
      <AlertDialog open={selectionDelete} onOpenChange={(o) => { if (!o) setSelectionDelete(false); }}>
        <AlertDialogContent data-testid="outbox-selection-dialog">
          <AlertDialogHeader>
            <AlertDialogTitle>Delete {selected.size} selected email{selected.size === 1 ? '' : 's'}?</AlertDialogTitle>
            <AlertDialogDescription>
              This soft-deletes the selected emails from your outbox. Records remain in
              the database for audit but are hidden from all lists.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={busy} data-testid="outbox-selection-cancel">Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={doSelectionDelete}
              disabled={busy || selected.size === 0}
              data-testid="outbox-selection-confirm"
              className="bg-rose-600 hover:bg-rose-700 focus:ring-rose-600"
            >
              {busy ? <Loader2 size={14} className="animate-spin mr-1.5" /> : <Trash2 size={14} className="mr-1.5" />}
              Delete {selected.size}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

// Phase 3.21 Item 4 — Permission Presets admin page.
//
// Two-pane layout:
//   LEFT  : list of every preset (6 built-in read-only + N custom). Click selects.
//   RIGHT : detail view (label, description, the full matrix grid) + edit /
//           delete (custom only) / "+ Create preset" button.
//
// Built-in presets cannot be renamed or deleted but their matrix is still
// rendered so admins can see exactly what each preset grants before applying
// it to a user. Custom presets show pencil + trash with delete-confirm modal.
//
// Permission gate: `users.edit` (matches every other preset endpoint).
import React, { useEffect, useMemo, useState } from 'react';
import { toast } from 'sonner';
import api, { apiError } from '@/lib/api';
import { useCan } from '@/lib/permissions';
import { PageHeader } from '@/components/capture/Ui';
import MobileModulesSection from '@/components/settings/MobileModulesSection';
import RoleFormsSection from '@/components/settings/RoleFormsSection';
import {
  LockClosed20Regular as Lock20Regular,
  Sparkle20Filled,
  Add20Regular,
  Edit20Regular,
  Copy20Regular as Duplicate20Regular,
  Delete20Regular,
  Save20Regular,
  Checkmark16Filled,
  Dismiss16Regular,
  Phone20Regular,
  ShieldCheckmark20Regular,
} from '@fluentui/react-icons';
import {
  Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle,
} from '@/components/ui/dialog';

const ACTIONS = ['open', 'view', 'edit', 'delete', 'email', 'team_view'];
// v159.2 — `team_view` only applies to these 6 team-scoped resources.
// For every other resource we render a locked "—" cell so admins don't
// think toggling it does anything.
const TEAM_VIEW_RESOURCES = new Set([
  'swms', 'pre_starts', 'site_diary', 'hazards', 'incidents', 'inspections',
]);

export default function PermissionPresetsAdmin() {
  const can = useCan();
  const [data, setData] = useState({ built_in: [], custom: [] });
  const [loading, setLoading] = useState(true);
  const [selectedKey, setSelectedKey] = useState(null);
  const [createOpen, setCreateOpen] = useState(false);
  const [editing, setEditing] = useState(null); // {id, label, description, permissions}
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [busy, setBusy] = useState(false);
  // Phase 4.3 — extra tab for the per-role mobile module allocator.
  const [tab, setTab] = useState('presets');

  const allowed = can('users', 'view');
  const canEdit = can('users', 'edit');

  const load = async () => {
    setLoading(true);
    try {
      const { data: d } = await api.get('/permission-presets');
      setData(d || { built_in: [], custom: [] });
      const list = [...(d?.built_in || []), ...(d?.custom || [])];
      if (list.length && !list.find((p) => p.key === selectedKey)) {
        setSelectedKey(list[0].key);
      }
    } catch (e) { toast.error(apiError(e)); }
    finally { setLoading(false); }
  };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { if (allowed) load(); }, [allowed]);

  const flatList = useMemo(() => [...(data.built_in || []), ...(data.custom || [])], [data]);
  const selected = useMemo(() => flatList.find((p) => p.key === selectedKey) || flatList[0], [flatList, selectedKey]);
  const resources = useMemo(() => (selected?.permissions ? Object.keys(selected.permissions).sort() : []), [selected]);

  const handleDelete = async () => {
    if (!confirmDelete) return;
    setBusy(true);
    try {
      await api.delete(`/permission-presets/${confirmDelete.id}`);
      toast.success(`Deleted "${confirmDelete.label}"`);
      setConfirmDelete(null);
      setSelectedKey(null);
      await load();
    } catch (e) { toast.error(apiError(e)); }
    finally { setBusy(false); }
  };

  // v159.4 — before opening the delete confirm, look up how many users
  // currently share this preset's exact matrix. The confirm dialog uses
  // this to warn "N users use this preset" and offer a reassign flow.
  const [deleteAssignees, setDeleteAssignees] = useState(null);
  const requestDelete = async (preset) => {
    setConfirmDelete(preset);
    setDeleteAssignees(null);
    try {
      const { data } = await api.get(`/permission-presets/${preset.id}/assignees`);
      setDeleteAssignees(data || { count: 0, users: [] });
    } catch { setDeleteAssignees({ count: 0, users: [] }); }
  };

  // v159.3 — one-click clone of any preset (built-in or custom).
  const handleDuplicate = async (preset) => {
    const sourceId = preset.is_builtin ? preset.key : preset.id;
    setBusy(true);
    try {
      const { data: created } = await api.post(`/permission-presets/${sourceId}/duplicate`);
      toast.success(`Cloned "${preset.label}" → "${created.label}"`);
      await load();
      setSelectedKey(created.key);
    } catch (e) { toast.error(apiError(e)); }
    finally { setBusy(false); }
  };

  if (!allowed) {
    return (
      <div className="rounded-2xl border border-slate-200 bg-white p-10 text-center text-slate-500" data-testid="presets-denied">
        Access denied — you need users.view permission.
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto" data-testid="presets-admin-page">
      <PageHeader crumb="Settings / Permissions Matrix" title="Permissions Matrix"
        subtitle="Curate role presets and decide which modules show up on the mobile app."
        action={canEdit && tab === 'presets' && (
          <button onClick={() => setCreateOpen(true)} data-testid="preset-create-btn"
            className="inline-flex items-center gap-1.5 px-4 py-2.5 rounded-lg bg-brand-blue text-white text-sm font-medium hover:bg-blue-600">
            <Add20Regular /> Create preset
          </button>
        )} />

      {/* Phase 4.3 — Tab strip between Permission Presets and Mobile Modules. */}
      <div className="flex items-center gap-1 mb-4 border-b border-slate-200" data-testid="permissions-tabs">
        <TabBtn active={tab === 'presets'} onClick={() => setTab('presets')}
          icon={<ShieldCheckmark20Regular />} label="Permission Presets" testid="tab-presets" />
        <TabBtn active={tab === 'mobile'} onClick={() => setTab('mobile')}
          icon={<Phone20Regular />} label="Mobile App Modules" testid="tab-mobile" />
        <TabBtn active={tab === 'forms'} onClick={() => setTab('forms')}
          icon={<Phone20Regular />} label="Forms per role" testid="tab-forms" />
      </div>

      {tab === 'mobile' ? (
        <MobileModulesSection canEdit={canEdit} />
      ) : tab === 'forms' ? (
        <RoleFormsSection canEdit={canEdit} />
      ) : loading ? (
        <div className="text-sm text-slate-500">Loading…</div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-[280px_1fr] gap-5">
          {/* LEFT — preset list */}
          <aside className="rounded-2xl border border-slate-200 bg-white p-3" data-testid="preset-list">
            <SectionTitle>Built-in <span className="text-slate-400 font-normal">(read-only)</span></SectionTitle>
            <ul className="space-y-1">
              {(data.built_in || []).map((p) => (
                <PresetListItem key={p.key} preset={p} selected={selectedKey === p.key}
                  onSelect={() => setSelectedKey(p.key)} testid={`preset-list-${p.key}`} />
              ))}
            </ul>
            <SectionTitle className="mt-4">Custom</SectionTitle>
            {(data.custom || []).length === 0 ? (
              <div className="text-[11px] italic text-slate-400 px-2 py-2">No custom presets yet.</div>
            ) : (
              <ul className="space-y-1">
                {(data.custom || []).map((p) => (
                  <PresetListItem key={p.key} preset={p} selected={selectedKey === p.key}
                    onSelect={() => setSelectedKey(p.key)} testid={`preset-list-${p.key}`} />
                ))}
              </ul>
            )}
          </aside>

          {/* RIGHT — detail */}
          <section className="rounded-2xl border border-slate-200 bg-white p-5" data-testid="preset-detail">
            {!selected ? (
              <div className="text-sm text-slate-500">Pick a preset on the left to see its matrix.</div>
            ) : (
              <>
                <div className="flex items-start justify-between gap-3 flex-wrap mb-4">
                  <div className="min-w-0">
                    <div className="text-[10px] uppercase tracking-[0.16em] font-semibold text-violet-700 mb-1 inline-flex items-center gap-1.5">
                      <Sparkle20Filled style={{ width: 12, height: 12 }} /> {selected.is_builtin ? 'Built-in' : 'Custom'} preset
                    </div>
                    <h2 className="font-display text-2xl font-semibold text-slate-900">{selected.label}</h2>
                    {selected.description && <p className="text-sm text-slate-600 mt-1 max-w-2xl">{selected.description}</p>}
                  </div>
                  {canEdit && !selected.is_builtin && (
                    <div className="flex items-center gap-2">
                      <button onClick={() => handleDuplicate(selected)}
                        disabled={busy} data-testid="preset-detail-duplicate"
                        className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg border border-slate-300 bg-white text-sm font-medium text-slate-700 hover:bg-slate-50 disabled:opacity-60">
                        <Duplicate20Regular /> Duplicate
                      </button>
                      <button onClick={() => setEditing({
                          id: selected.id, label: selected.label, description: selected.description || '',
                          permissions: JSON.parse(JSON.stringify(selected.permissions || {})),
                        })} data-testid="preset-detail-edit"
                        className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg border border-slate-300 bg-white text-sm font-medium text-slate-700 hover:bg-slate-50">
                        <Edit20Regular /> Edit
                      </button>
                      <button onClick={() => requestDelete(selected)} data-testid="preset-detail-delete"
                        className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg border border-rose-300 text-rose-700 bg-white text-sm font-medium hover:bg-rose-50">
                        <Delete20Regular /> Delete
                      </button>
                    </div>
                  )}
                  {selected.is_builtin && (
                    <div className="flex items-center gap-2">
                      {canEdit && (
                        <button onClick={() => handleDuplicate(selected)}
                          disabled={busy} data-testid="preset-detail-duplicate"
                          className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg border border-violet-300 bg-violet-50 text-sm font-medium text-violet-800 hover:bg-violet-100 disabled:opacity-60">
                          <Duplicate20Regular /> Duplicate &amp; edit
                        </button>
                      )}
                      <div className="inline-flex items-center gap-1.5 text-[11px] font-semibold text-slate-500 px-2.5 py-1 rounded-full bg-slate-100">
                        <Lock20Regular style={{ width: 12, height: 12 }} /> Read-only
                      </div>
                    </div>
                  )}
                </div>

                {/* v159.3 — "Based on X" chip for cloned custom presets. */}
                {!selected.is_builtin && selected.based_on && (
                  <div className="mb-3 -mt-2 inline-flex items-center gap-1.5 text-[11px] font-semibold text-violet-800 px-2.5 py-1 rounded-full bg-violet-100"
                       data-testid="preset-based-on-chip">
                    <Duplicate20Regular style={{ width: 12, height: 12 }} />
                    Based on {selected.based_on.replace(/_/g, ' ')}
                  </div>
                )}

                {/* Matrix grid */}
                <div className="overflow-x-auto rounded-xl border border-slate-200">
                  <table className="zebra-list w-full text-sm">
                    <thead className="bg-slate-50 text-slate-500 text-[11px] uppercase tracking-wider">
                      <tr>
                        <th className="text-left px-3 py-2 font-semibold">Resource</th>
                        {ACTIONS.map((a) => <th key={a} className="text-center px-3 py-2 font-semibold">{a}</th>)}
                      </tr>
                    </thead>
                    <tbody>
                      {resources.map((r) => (
                        <tr key={r} className="border-t border-slate-100">
                          <td className="px-3 py-2 font-medium text-slate-700">{r}</td>
                          {ACTIONS.map((a) => {
                            // v159.2 — `team_view` only meaningful for the six
                            // team-scoped resources. Render a locked dash for
                            // everything else so the column still lines up.
                            if (a === 'team_view' && !TEAM_VIEW_RESOURCES.has(r)) {
                              return (
                                <td key={a} className="text-center px-3 py-2 text-slate-300" data-testid={`preset-cell-${r}-${a}`}>
                                  —
                                </td>
                              );
                            }
                            const v = !!selected.permissions?.[r]?.[a];
                            return (
                              <td key={a} className="text-center px-3 py-2" data-testid={`preset-cell-${r}-${a}`}>
                                {v
                                  ? <Checkmark16Filled className="inline text-emerald-600" />
                                  : <Dismiss16Regular className="inline text-slate-300" />}
                              </td>
                            );
                          })}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </>
            )}
          </section>
        </div>
      )}

      <PresetEditDialog
        open={createOpen || !!editing}
        initial={editing}
        templatePerms={selected?.permissions || null}
        onClose={() => { setCreateOpen(false); setEditing(null); }}
        onSaved={() => { setCreateOpen(false); setEditing(null); load(); }}
      />

      <Dialog open={!!confirmDelete} onOpenChange={(v) => !v && setConfirmDelete(null)}>
        <DialogContent data-testid="preset-delete-confirm">
          <DialogHeader>
            <DialogTitle className="font-display">
              {deleteAssignees && deleteAssignees.count > 0 ? 'Delete preset — reassign users first' : 'Delete preset?'}
            </DialogTitle>
            <DialogDescription>
              {!confirmDelete ? '' : (deleteAssignees === null
                ? `Checking how many users are on "${confirmDelete.label}"…`
                : deleteAssignees.count > 0
                  ? `"${confirmDelete.label}" is currently applied to ${deleteAssignees.count} user${deleteAssignees.count === 1 ? '' : 's'}. Reassign them to another preset from the user detail page before deleting — otherwise their custom overrides remain but the preset link is lost.`
                  : `"${confirmDelete.label}" will be removed for everyone in your org. No users currently share this preset's exact matrix, so nothing else changes.`)}
            </DialogDescription>
          </DialogHeader>
          {deleteAssignees && deleteAssignees.count > 0 && (
            <div className="max-h-48 overflow-y-auto rounded-lg border border-amber-200 bg-amber-50 p-2 text-xs space-y-1" data-testid="preset-delete-assignees">
              {deleteAssignees.users.slice(0, 20).map((u) => (
                <div key={u.id} className="flex items-center justify-between gap-2">
                  <span className="font-medium text-slate-800 truncate">{u.name || u.email}</span>
                  <span className="text-[10px] uppercase tracking-wide text-amber-800">{u.role}</span>
                </div>
              ))}
              {deleteAssignees.users.length > 20 && (
                <div className="text-[11px] text-amber-700 pt-1">+ {deleteAssignees.users.length - 20} more…</div>
              )}
            </div>
          )}
          <DialogFooter>
            <button onClick={() => setConfirmDelete(null)} className="px-3 py-2 rounded-lg border border-slate-300 bg-white text-sm font-medium text-slate-700">Cancel</button>
            <button onClick={handleDelete} disabled={busy || (deleteAssignees && deleteAssignees.count > 0)} data-testid="preset-delete-confirm-btn"
              className="px-4 py-2 rounded-lg bg-rose-600 text-white text-sm font-medium hover:bg-rose-700 disabled:opacity-40 disabled:cursor-not-allowed">
              {busy ? 'Deleting…' : (deleteAssignees && deleteAssignees.count > 0 ? 'Reassign users first' : 'Delete')}
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

function SectionTitle({ children, className = '' }) {
  return <div className={`px-2 mb-1.5 text-[10px] uppercase tracking-[0.12em] font-semibold text-slate-400 ${className}`}>{children}</div>;
}

// Phase 4.3 — page-level tab pill. Active tab gets an orange underline
// (matches the new 2-colour brand) and a slate-900 label; inactive tabs
// stay muted slate so the strip reads as navigation, not a CTA.
function TabBtn({ active, onClick, icon, label, testid }) {
  return (
    <button
      type="button"
      onClick={onClick}
      data-testid={testid}
      data-active={active}
      className={[
        'relative inline-flex items-center gap-2 px-4 py-2.5 text-sm font-medium transition-colors',
        active ? 'text-slate-900' : 'text-slate-500 hover:text-slate-700',
      ].join(' ')}
    >
      <span className={active ? 'text-orange-600' : 'text-slate-400'}>{icon}</span>
      {label}
      {active && <span className="absolute left-2 right-2 -bottom-px h-0.5 bg-orange-500 rounded-full" />}
    </button>
  );
}

function PresetListItem({ preset, selected, onSelect, testid }) {
  return (
    <li>
      <button onClick={onSelect} data-testid={testid}
        className={`w-full text-left rounded-lg px-2.5 py-2 text-sm transition-colors border-l-4 ${
          selected
            ? 'border-orange-500 bg-orange-50 text-slate-900 font-semibold pl-1.5'
            : 'border-transparent text-slate-700 hover:bg-slate-50 pl-1.5'
        }`}>
        <div className="flex items-center justify-between gap-2 min-w-0">
          <span className="truncate">{preset.label}</span>
          {preset.is_builtin && <Lock20Regular className="shrink-0 text-slate-400" style={{ width: 12, height: 12 }} />}
        </div>
      </button>
    </li>
  );
}

function PresetEditDialog({ open, initial, templatePerms, onClose, onSaved }) {
  const isEdit = !!initial;
  const [label, setLabel] = useState('');
  const [description, setDescription] = useState('');
  const [perms, setPerms] = useState({});
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!open) return;
    if (isEdit) {
      setLabel(initial.label || '');
      setDescription(initial.description || '');
      setPerms(JSON.parse(JSON.stringify(initial.permissions || {})));
    } else {
      setLabel(''); setDescription('');
      // Default: empty matrix using the resources present in the currently
      // selected preset (which always has the full schema after server
      // normalisation). Backend re-validates against PERMISSIONS_SCHEMA so
      // missing resources are coerced to all-false anyway.
      const empty = {};
      Object.keys(templatePerms || {}).forEach((r) => {
        empty[r] = {}; ACTIONS.forEach((a) => { empty[r][a] = false; });
      });
      setPerms(empty);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, isEdit, initial]);

  const allResources = useMemo(() => Object.keys(perms || {}).sort(), [perms]);

  const toggleCell = (r, a) => setPerms((prev) => {
    const next = { ...(prev || {}) };
    next[r] = { ...(next[r] || {}) };
    next[r][a] = !next[r][a];
    return next;
  });

  const save = async () => {
    if (!label.trim()) { toast.error('Label is required'); return; }
    setSaving(true);
    try {
      const payload = { label: label.trim(), description: description.trim(), permissions: perms };
      if (isEdit) await api.put(`/permission-presets/${initial.id}`, payload);
      else await api.post('/permission-presets', payload);
      toast.success(isEdit ? 'Preset saved' : 'Preset created');
      onSaved?.();
    } catch (e) { toast.error(apiError(e)); }
    finally { setSaving(false); }
  };

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="max-w-3xl" data-testid="preset-edit-modal">
        <DialogHeader>
          <DialogTitle className="font-display">{isEdit ? 'Edit preset' : 'Create preset'}</DialogTitle>
          <DialogDescription>Tick the (resource × action) cells this preset should grant.</DialogDescription>
        </DialogHeader>
        <div className="space-y-3 pt-2">
          <label className="block"><div className="text-xs uppercase tracking-wider font-semibold text-slate-500 mb-1">Label</div>
            <input value={label} onChange={(e) => setLabel(e.target.value)} data-testid="preset-edit-label"
              className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm" /></label>
          <label className="block"><div className="text-xs uppercase tracking-wider font-semibold text-slate-500 mb-1">Description</div>
            <textarea rows={2} value={description} onChange={(e) => setDescription(e.target.value)} data-testid="preset-edit-description"
              className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm" /></label>
          <div className="rounded-xl border border-slate-200 overflow-x-auto max-h-[50vh] overflow-y-auto">
            <table className="zebra-list w-full text-sm">
              <thead className="bg-slate-50 text-slate-500 text-[11px] uppercase tracking-wider sticky top-0">
                <tr>
                  <th className="text-left px-3 py-2 font-semibold">Resource</th>
                  {ACTIONS.map((a) => <th key={a} className="text-center px-3 py-2 font-semibold">{a}</th>)}
                </tr>
              </thead>
              <tbody>
                {allResources.map((r) => (
                  <tr key={r} className="border-t border-slate-100">
                    <td className="px-3 py-1.5 font-medium text-slate-700">{r}</td>
                    {ACTIONS.map((a) => (
                      <td key={a} className="text-center px-3 py-1.5">
                        <input type="checkbox"
                          checked={!!perms?.[r]?.[a]}
                          onChange={() => toggleCell(r, a)}
                          data-testid={`preset-edit-cell-${r}-${a}`} />
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
        <DialogFooter>
          <button onClick={onClose} className="px-3 py-2 rounded-lg border border-slate-300 bg-white text-sm font-medium text-slate-700">Cancel</button>
          <button onClick={save} disabled={saving} data-testid="preset-edit-save"
            className="inline-flex items-center gap-1.5 px-4 py-2 rounded-lg bg-brand-blue text-white text-sm font-medium disabled:opacity-60">
            <Save20Regular /> {saving ? 'Saving…' : (isEdit ? 'Save changes' : 'Create preset')}
          </button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

