export default function PlantVehicles() {
  const can = useCan();
  const canEdit = can('assets', 'edit');
  const [data, setData] = useState({ assets: [], total: 0, live: 0, manual: 0 });
  const [busy, setBusy] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState('');
  const [kind, setKind] = useState('all');
  const [assetType, setAssetType] = useState('all');
  const [q, setQ] = useState('');
  const [view, setView] = useState('list');
  const [activeMapAsset, setActiveMapAsset] = useState(null);
  const [drawerAsset, setDrawerAsset] = useState(null);
  const [drawerOpen, setDrawerOpen] = useState(false);
  // v58.13.27 — Initial tab for the drawer, used by deep-link opens
  // via `?assetDrawer=<id>&tab=<tab>`. `null` means the drawer's own
  // default ('details') applies.
  const [drawerInitialTab, setDrawerInitialTab] = useState(null);
  const [printIds, setPrintIds] = useState(null);
  // v160.3.9.20 — Unmatched maintenance count for the tab-header badge.
  const [pmUnmatched, setPmUnmatched] = useState(null);
  // v160.3.9.21e — Attention-row soft-delete confirmation.
  const [deletePending, setDeletePending] = useState(null); // { id, label } | null
  const [deleteBusy, setDeleteBusy] = useState(false);
  const [dashboardRefreshKey, setDashboardRefreshKey] = useState(0);
  const [pmUser] = useState(() => {
    try { return JSON.parse(localStorage.getItem(USER_KEY) || 'null'); }
    catch { return null; }
  });
  useEffect(() => {
    let alive = true;
    api.get('/plant-maintenance/unmatched').then((r) => {
      if (alive) setPmUnmatched(r.data?.total_unmatched_rows ?? 0);
    }).catch(() => { if (alive) setPmUnmatched(0); });
    return () => { alive = false; };
  }, []);

  const load = async () => {
    setRefreshing(true); setError('');
    try {
      const { data: d } = await api.get('/assets', { params: { kind, asset_type: assetType, q: q || undefined } });
      setData(d);
    } catch (e) { setError(apiError(e)); }
    finally { setBusy(false); setRefreshing(false); }
  };

  useEffect(() => { load(); }, [kind, assetType]);
  useEffect(() => {
    const t = setTimeout(load, q ? 300 : 0);
    return () => clearTimeout(t);
  }, [q]);

  // v58.13.27 — Deep-link opener. Reads `?assetDrawer=<id>&tab=<tab>`
  // on mount + whenever the URL changes, fetches the asset, opens the
  // drawer on the requested tab (validated against AssetDrawer.TABS),
  // then strips the query params so back-nav is clean and a reload
  // doesn't re-fire.
  const _navigate = useNavigate();
  const _location = useLocation();
  useEffect(() => {
    const params = new URLSearchParams(_location.search);
    const wantId = params.get('assetDrawer');
    const wantTab = params.get('tab');
    if (!wantId) return;
    let cancelled = false;
    (async () => {
      try {
        const { data: asset } = await api.get(`/assets/${wantId}`);
        if (cancelled) return;
        setDrawerAsset(asset);
        setDrawerInitialTab(wantTab || null);
        setDrawerOpen(true);
      } catch (e) {
        toast.error(apiError(e) || 'Asset not found');
      } finally {
        if (!cancelled) {
          // Strip query params so a reload / back-nav doesn't re-fire.
          _navigate('/app/vehicles', { replace: true });
        }
      }
    })();
    return () => { cancelled = true; };
  }, [_location.search]);

  const typeCounts = useMemo(() => {
    const m = {};
    for (const a of data.assets) m[a.asset_type] = (m[a.asset_type] || 0) + 1;
    return m;
  }, [data.assets]);

  // Phase 3.9b — load form-assignment counts per asset_type so each row can
  // show "N forms". Only admin/manager/hseq_lead can read the matrix; for
  // workers we just leave the chip hidden.
  const [formCountsByType, setFormCountsByType] = useState({});
  const [formNamesByType, setFormNamesByType] = useState({});
  useEffect(() => {
    let alive = true;
    api.get('/form-templates/assignments').then((r) => {
      if (!alive) return;
      const counts = {};
      const names = {};
      (r.data?.templates || []).forEach((t) => {
        const a = t.applies_to || {};
        const isAny = (a.kinds || []).includes('any');
        const types = a.asset_types || [];
        const kinds = a.kinds || [];
        // Track per-type (explicit) and a sentinel for "any kind".
        const targets = new Set(types);
        // Also: any kind-level match → applies to every asset_type of that kind.
        // We can't compute that without a full kind→types index, so we just
        // include this template against every asset_type the page knows
        // about. data.assets already gives us that mapping cheaply.
        if (isAny || kinds.length) {
          (data.assets || []).forEach((asset) => {
            if (isAny || (asset.kind && kinds.includes(asset.kind))) {
              if (asset.asset_type) targets.add(asset.asset_type);
            }
          });
        }
        targets.forEach((at) => {
          counts[at] = (counts[at] || 0) + 1;
          (names[at] = names[at] || []).push(t.name);
        });
      });
      setFormCountsByType(counts);
      setFormNamesByType(names);
    }).catch(() => { /* worker or other 403 — chip stays hidden */ });
    return () => { alive = false; };
  }, [data.assets]);

  const archive = async (a) => {
    if (!window.confirm(`Archive asset "${a.name}"?`)) return;
    try {
      await api.delete(`/assets/${a.id}`);
      toast.success(`Archived ${a.name}`);
      load();
    } catch (e) { toast.error(apiError(e)); }
  };

  const downloadQr = (a) => {
    api.get(`/assets/${a.id}/qr.png`, { responseType: 'blob' })
      .then((r) => {
        const url = URL.createObjectURL(r.data);
        const anchor = document.createElement('a');
        anchor.href = url;
        anchor.download = `qr-${a.rego_serial || a.scan_token}.png`;
        anchor.click();
        setTimeout(() => URL.revokeObjectURL(url), 5000);
        toast.success('QR downloaded');
      })
      .catch((e) => toast.error(apiError(e)));
  };

  // Phase 4.7.2 — Asset-QR popover actions. The QR icon button used to fire
  // `downloadQr` directly (and silently — no toast), so users assumed it was
  // dead. Now it opens a small menu with the three actions the brief asked
  // for: Print QR (reuses the existing bulk Print Labels modal pre-filtered
  // to this one asset), Copy scan link, and Download PNG.
  const copyScanLink = async (a) => {
    const token = a.scan_token;
    if (!token) { toast.error('No QR token on this asset yet.'); return; }
    const url = `${window.location.origin}/scan/${token}`;
    // v154 — iframe-safe wrapper: async → execCommand → manual modal.
    await copyToClipboard(url, { successMsg: 'Scan link copied' });
  };

  const openCreate = () => { setDrawerAsset(null); setDrawerOpen(true); };
  const openEdit = (a) => { setDrawerAsset(a); setDrawerOpen(true); };

  // v160.3.9.21e — Fetch a full asset by id (attention rows carry only id +
  // label) then open the drawer. Same for view + edit; drawer decides
  // its mode from `isEdit = !!asset?.id`.
  const openAttentionAsset = async (attentionRow) => {
    if (!attentionRow?.id) return;
    try {
      const { data: asset } = await api.get(`/assets/${attentionRow.id}`);
      setDrawerAsset(asset);
      setDrawerOpen(true);
    } catch (e) {
      toast.error(apiError(e) || 'Failed to open asset');
    }
  };

  // v160.3.9.21e — Soft-delete (archive) an asset via DELETE /api/assets/{id}.
  // Backend sets status='retired', returns 204. On success refresh both
  // the list and the dashboard's attention[] payload.
  const confirmDelete = async () => {
    if (!deletePending?.id) return;
    setDeleteBusy(true);
    try {
      await api.delete(`/assets/${deletePending.id}`);
      toast.success(`Archived: ${deletePending.label || deletePending.id.slice(0, 8)}`);
      setDeletePending(null);
      setDashboardRefreshKey((k) => k + 1);   // force ModuleDashboard remount
      load();                                  // refresh the List tab too
    } catch (e) {
      toast.error(apiError(e) || 'Delete failed');
    } finally {
      setDeleteBusy(false);
    }
  };

  if (busy && !data.assets.length && !error) {
    return <div className="text-sm text-slate-500" data-testid="assets-loading">Loading register…</div>;
  }

  const assets = data.assets || [];
  const filteredCount = assets.length;
  const totalSummary = `${filteredCount} of ${data.total} assets · ${data.live} live · ${data.manual} manual`;

  return (
    <div className="max-w-6xl mx-auto" data-testid="plant-vehicles-page">
      <PageHeader
        crumb="Compliance / Plant & Vehicles"
        title="Plant & Vehicles"
        subtitle={<>Unified asset register — live Navixy fleet + manually-added plant, tools and containers. <Link to="/app/settings/integrations" className="text-brand-blue hover:underline ml-1">Manage Navixy</Link></>}
        action={
          <div className="flex items-center gap-2">
            <button onClick={load} disabled={refreshing} className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg border border-slate-300 text-sm hover:bg-slate-50 disabled:opacity-50" data-testid="assets-refresh">
              {refreshing ? <Loader2 size={14} className="animate-spin" /> : <RefreshCw />} Refresh
            </button>
            {canEdit && (
              <>
                <button onClick={() => setPrintIds(assets.map((a) => a.id))} disabled={!assets.length}
                  className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg border border-slate-300 text-sm hover:bg-slate-50 disabled:opacity-50"
                  data-testid="assets-print-labels">
                  <Printer /> Print Labels
                </button>
                <button onClick={openCreate}
                  className="inline-flex items-center gap-1.5 px-4 py-2 rounded-lg bg-blue-600 text-white text-sm font-semibold hover:bg-blue-700"
                  data-testid="assets-add">
                  <Plus /> Add Asset
                </button>
              </>
            )}
          </div>
        }
      />

      <HowThisWorks schematicSlug="plant_vehicles" />

      <Tabs defaultValue="maintenance" className="mt-2" data-testid="vehicles-tabs">
        {/* v160.3.9.21d — Equal-width, colour-coded, active=filled/inactive=ghost tab bar.
            Order: All Maintenance · Unmatched · Vehicles from Navixy · Dashboard · Service Inbox (v58.13.18). */}
        <TabsList className="w-full grid grid-cols-2 md:grid-cols-5 gap-2 bg-transparent p-0 h-auto rounded-none border-0 shadow-none">
          {/* Tab 1 — All Maintenance (navy / Paneltec brand) */}
          <TabsTrigger value="maintenance" data-testid="vehicles-tab-maintenance"
            className="inline-flex items-center justify-center gap-2 rounded-xl border px-4 py-2.5 text-sm font-semibold tracking-tight transition-colors
              border-blue-800 text-blue-800 bg-white hover:bg-blue-50
              data-[state=active]:bg-blue-800 data-[state=active]:text-white data-[state=active]:hover:bg-blue-800
              data-[state=active]:shadow-sm">
            All Maintenance
          </TabsTrigger>

          {/* Tab 2 — Unmatched (rose / warning) */}
          <TabsTrigger value="unmatched" data-testid="vehicles-tab-unmatched"
