              </div>
            </Field>
            <Helper>Automatically pull jobs on the schedule above.</Helper>
          </div>

          <div className="sm:col-span-2">
            <Field label="Completed jobs history (days)">
              <Input type="number" value={String(s.completed_jobs_history_days)}
