                      <div className="text-[11px] text-slate-500 truncate max-w-[180px]" title={u.email}>{u.email}</div>
                    </td>
                    <td className="py-2 pr-3 text-xs text-slate-600" data-testid={`assign-role-position-${u.id}`}>
